function getDefaultDashboardLayout(): DashboardLayoutState {
  return {
    hidden: defaultHiddenDashboardWidgets,
    minimized: [],
    order: defaultDashboardWidgetOrder,
  };
}

  function getDashboardLayoutForUser(userId?: string) {
  if (typeof window === "undefined" || !userId) {
    return getDefaultDashboardLayout();
  }

  try {
    const storedLayouts = window.localStorage.getItem(
      dashboardLayoutStorageKey,
    );
    const parsedLayouts = storedLayouts
      ? (JSON.parse(storedLayouts) as Record<
          string,
          Partial<DashboardLayoutState>
        >)
      : {};
    return normalizeDashboardLayout(parsedLayouts[userId]);
  } catch {
    return getDefaultDashboardLayout();
  }
}

function normalizeDashboardLayout(
  layout: Partial<DashboardLayoutState> | undefined,
): DashboardLayoutState {
  const validWidgets = new Set(defaultDashboardWidgetOrder);
  const storedOrder = Array.isArray(layout?.order)
    ? layout.order.filter((widget) => validWidgets.has(widget))
    : [];
  const order = [
    ...storedOrder,
    ...defaultDashboardWidgetOrder.filter(
      (widget) => !storedOrder.includes(widget),
    ),
  ];

  return {
    hidden: Array.isArray(layout?.hidden)
      ? layout.hidden.filter((widget) => validWidgets.has(widget))
      : defaultHiddenDashboardWidgets,
    minimized: Array.isArray(layout?.minimized)
      ? layout.minimized.filter((widget) => validWidgets.has(widget))
      : [],
    order,
  };
}

function getZoneTables(
  tables: DemoTable[],
  showId: string,
  zoneId: SeatingZoneId,
) {
  return tables.filter(
    (table) => table.showId === showId && table.zoneId === zoneId,
  );
}

function isLegacyPlaceholderTable(table: DemoTable) {
  return (
    table.physicalTable !== true &&
    table.availabilityScope !== "operational" &&
    isLegacyPlaceholderTableCode(table.zoneId, table.tableNumber)
  );
}

function isFloorInventoryTable(table: DemoTable) {
  return table.physicalTable === true || !isLegacyPlaceholderTable(table);
}

function getZoneStats(
  tables: DemoTable[],
  bookings: DemoBooking[],
  showId: string,
  zone: SeatingZone,
) {
  const zoneTables = getZoneTables(tables, showId, zone.id);
  const physicalTables = zoneTables.filter(
    (table) => table.physicalTable === true,
  );
  const configuredPhysicalTables = physicalTables.filter(
    (table) =>
      table.capacityConfigured !== false &&
      table.status !== "disabled",
  );
  const operationalTableCapacity = configuredPhysicalTables.reduce(
    (total, table) => total + table.seatCapacity,
    0,
  );
  const bookedSeats = bookings
    .filter(
      (booking) =>
        booking.showId === showId &&
        booking.zoneId === zone.id &&
        isOperationallyActiveBooking(booking),
    )
    .reduce((total, booking) => total + booking.partySize, 0);
  const totalCapacity = getVenueZoneSeatCapacity(zone.id);

  return {
    bookedSeats,
    configuredPhysicalTableCount: configuredPhysicalTables.length,
    operationalTableCapacity,
    physicalTableCount: physicalTables.length,
    temporaryOperationalTableCount: zoneTables.filter(
      (table) =>
        table.physicalTable !== true && !isLegacyPlaceholderTable(table),
    ).length,
    unconfiguredPhysicalTableCount: physicalTables.filter(
      (table) =>
        table.capacityConfigured === false,
    ).length,
    overCapacitySeats: Math.max(bookedSeats - totalCapacity, 0),
    remainingSeats: Math.max(totalCapacity - bookedSeats, 0),
    totalCapacity,
  };
}

function mergeTablesForShows(
  currentTables: DemoTable[],
  nextTables: DemoTable[],
  showIds: string[],
) {
  const showIdSet = new Set(showIds);

  return [
    ...currentTables.filter((table) => !table.showId || !showIdSet.has(table.showId)),
    ...nextTables,
  ];
}

function getTableOccupancy(
  table: DemoTable,
  bookings: DemoBooking[],
) {
  if (table.status === "disabled") {
    return {
      booking: undefined,
      state: "blocked" as const,
    };
  }

  const booking = bookings.find(
      (currentBooking) =>
        (currentBooking.tableId === table.id ||
          currentBooking.reference === table.bookingReference) &&
      isOperationallyActiveBooking(currentBooking),
  );

  if ((booking?.status ?? "confirmed") === "checked-in") {
    return {
      booking,
      state: "checked-in" as const,
    };
  }

  if (booking) {
    return {
      booking,
      state: "reserved" as const,
    };
  }

  return {
    booking: undefined,
    state: "available" as const,
  };
}

function getNextTableId(
  tables: DemoTable[],
  showId: string,
  zoneId: SeatingZoneId,
  suffix: string,
) {
  let index = tables.length + 1;
  let nextId = `${showId}-${zoneId}-${suffix}-${index}`;

  while (tables.some((table) => table.id === nextId)) {
    index += 1;
    nextId = `${showId}-${zoneId}-${suffix}-${index}`;
  }

  return nextId;
}

function createBookingReference() {
  return createShortBookingReference();
}

function createAvailableBookingReference(bookings: DemoBooking[]) {
  for (let attempt = 0; attempt < 8; attempt += 1) {
    const reference = createBookingReference();

    if (!bookings.some((booking) => booking.reference === reference)) {
      return reference;
    }
  }

  throw new Error("A unique booking reference could not be generated.");
}

function isValidMergedOperationalParent(
  table: DemoTable,
  tables: DemoTable[],
) {
  const memberIds = table.mergedFrom ?? [];

  if (
    table.physicalTable === true ||
    table.availabilityScope !== "operational" ||
    !table.authoritativeId ||
    table.capacityConfigured === false ||
    table.mergedInto ||
    memberIds.length < 2 ||
    new Set(memberIds).size !== memberIds.length
  ) {
    return false;
  }

  const members = memberIds.map((memberId) =>
    tables.find((candidate) => candidate.id === memberId),
  );

  return (
    members.every(
      (member) =>
        Boolean(member?.authoritativeId) &&
        member?.showId === table.showId &&
        member?.zoneId === table.zoneId &&
        member?.physicalTable === true &&
        member?.capacityConfigured !== false &&
        member?.status === "disabled" &&
        member?.mergedInto === table.id &&
        !member?.mergedFrom?.length &&
        !member?.bookingReference,
    ) &&
    members.reduce(
      (total, member) => total + (member?.seatCapacity ?? 0),
      0,
    ) === table.seatCapacity
  );
}

function isTemporaryOperationalTable(table: DemoTable) {
  return (
    table.physicalTable !== true &&
    table.availabilityScope === "operational" &&
    !table.mergedFrom?.length &&
    !table.mergedInto
  );
}

function isEligibleBookingMoveTarget(
  table: DemoTable,
  booking: DemoBooking,
  tables: DemoTable[],
) {
  const isAssignableTable =
    (table.physicalTable === true && !table.mergedFrom?.length) ||
    isTemporaryOperationalTable(table) ||
    isValidMergedOperationalParent(table, tables);

  return (
    table.id !== booking.tableId &&
    table.showId === booking.showId &&
    table.zoneId === booking.zoneId &&
    isAssignableTable &&
    Boolean(table.authoritativeId) &&
    table.capacityConfigured !== false &&
    table.seatCapacity >= booking.partySize &&
    table.status === "available" &&
    !table.bookingReference &&
    !table.mergedInto
  );
}

function formatArrivalTime(arrivalTime?: string) {
  return arrivalTime
    ? formatSouthAfricanTimestamp(arrivalTime)
    : "Awaiting arrival";
}

function formatCurrency(amount: number) {
  return `R${amount.toLocaleString()}`;
}

function formatSouthAfricanDate(value: Date | string | undefined | null) {
  if (!value) {
    return "Not recorded";
  }

  const parsedDate =
    value instanceof Date
      ? value
      : /^\d{4}-\d{2}-\d{2}$/.test(value)
        ? new Date(`${value}T00:00:00`)
        : new Date(value);

  if (Number.isNaN(parsedDate.getTime())) {
    return String(value);
  }

  const day = String(parsedDate.getDate()).padStart(2, "0");
  const month = String(parsedDate.getMonth() + 1).padStart(2, "0");
  const year = parsedDate.getFullYear();

  return `${day}/${month}/${year}`;
}

function formatSouthAfricanTime(value: Date | string | undefined | null) {
  if (!value) {
    return "Not recorded";
  }

  const parsedDate = value instanceof Date ? value : new Date(value);

  if (Number.isNaN(parsedDate.getTime())) {
    return String(value);
  }

  const hours = String(parsedDate.getHours()).padStart(2, "0");
  const minutes = String(parsedDate.getMinutes()).padStart(2, "0");

  return `${hours}:${minutes}`;
}

function formatSouthAfricanTimestamp(
  value: Date | string | undefined | null,
) {
  if (!value) {
    return "Not recorded";
  }

  const parsedDate = value instanceof Date ? value : new Date(value);

  if (Number.isNaN(parsedDate.getTime())) {
    return String(value);
  }

  return `${formatSouthAfricanDate(parsedDate)} ${formatSouthAfricanTime(parsedDate)}`;
}

function formatRelativeActivity(value: string | null | undefined) {
  if (!value) {
    return "Not recorded";
  }

  const elapsedSeconds = Math.max(
    Math.floor((Date.now() - new Date(value).getTime()) / 1000),
    0,
  );

  if (!Number.isFinite(elapsedSeconds)) {
    return "Not recorded";
  }

  if (elapsedSeconds < 60) {
    return `${elapsedSeconds}s ago`;
  }

  const elapsedMinutes = Math.floor(elapsedSeconds / 60);

  if (elapsedMinutes < 60) {
    return `${elapsedMinutes}m ago`;
  }

  const elapsedHours = Math.floor(elapsedMinutes / 60);

  return `${elapsedHours}h ago`;
}

function formatDurationMs(value: number | null | undefined) {
  if (typeof value !== "number") {
    return "Not recorded";
  }

  return `${value.toLocaleString()} ms`;
}

function getPlatformOperationsStatusClass(status: string) {
  if (status === "Completed" || status === "Recorded") {
    return "border-emerald-300/35 bg-emerald-950/30 text-emerald-200";
  }

  if (status === "Failed" || status === "Attention" || status === "error") {
    return "border-red-300/35 bg-red-950/30 text-red-200";
  }

  if (
    status === "Abandoned" ||
    status === "Awaiting Payment" ||
    status === "warning"
  ) {
    return "border-amber-300/35 bg-amber-950/30 text-amber-200";
  }

  return "border-[#D8C36A]/35 bg-[#1A1208] text-[#F2D66C]";
}

function getSystemHealthLabel(status: SystemHealthStatus) {
  if (status === "healthy") {
    return "🟢 Healthy";
  }

  if (status === "offline") {
    return "🔴 Offline";
  }

  return "🟡 Warning";
}

function getSystemHealthBadgeClass(status: SystemHealthStatus) {
  if (status === "healthy") {
    return "border-emerald-300/30 bg-emerald-950/25 text-emerald-200";
  }

  if (status === "offline") {
    return "border-red-300/35 bg-red-950/30 text-red-100";
  }

  return "border-amber-300/35 bg-amber-950/25 text-amber-100";
}

function getStaffIssueStatusClass(status: StaffIssueStatus) {
  if (status === "completed") {
    return "border-emerald-300/35 bg-emerald-950/30 text-emerald-200";
  }

  if (status === "in_progress") {
    return "border-sky-300/35 bg-sky-950/30 text-sky-200";
  }

  if (status === "scheduled") {
    return "border-[#D8C36A]/35 bg-[#1A1208] text-[#F2D66C]";
  }

  return "border-zinc-500/35 bg-zinc-900/70 text-zinc-300";
}

function getStaffIssuePriorityClass(priority: StaffIssuePriority) {
  if (priority === "critical") {
    return "border-red-300/40 bg-red-950/35 text-red-100";
  }

  if (priority === "high") {
    return "border-amber-300/40 bg-amber-950/30 text-amber-100";
  }

  if (priority === "low") {
    return "border-zinc-500/35 bg-zinc-900/70 text-zinc-400";
  }

  return "border-[#D8C36A]/35 bg-[#1A1208] text-[#F2D66C]";
}

function formatOperationalShowDate(date: string) {
  const [year, month, day] = date.split("-");
  const monthNames = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
  ];

  return `${Number(day)} ${monthNames[Number(month) - 1] ?? month} ${year}`;
}

function formatFloorShowSelectorDate(date: string) {
  const [year, month, day] = date.split("-");
  const monthNames = [
    "Jan",
    "Feb",
    "Mar",
    "Apr",
    "May",
    "Jun",
    "Jul",
    "Aug",
    "Sep",
    "Oct",
    "Nov",
    "Dec",
  ];

  return `${String(Number(day)).padStart(2, "0")} ${monthNames[Number(month) - 1] ?? month} ${year}`;
}

function getFloorShowSelectorLabel(show: DemoShow) {
  const location = normalizeShowLocation(show.location ?? show.venueName);
  const locationLabel = location
    ? getShowCalendarLocationDisplay(location).alias
    : "LOC";

  return `${locationLabel} · ${formatFloorShowSelectorDate(show.date)} · ${getSouthAfricaShowTime(show)}`;
}

type PerformanceCalendarSelectorProps = {
  allLabel?: string;
  allowAllShows?: boolean;
  buttonClassName?: string;
  emptyLabel?: string;
  label?: string;
  locations?: EntryLocationKey[];
  onSelect: (showId: string) => void;
  selectedShowId: string;
  shows: DemoShow[];
};

function PerformanceCalendarSelector({
  allLabel = "All Shows",
  allowAllShows = false,
  buttonClassName,
  emptyLabel = "No active performances",
  label = "Selected Performance",
  locations,
  onSelect,
  selectedShowId,
  shows,
}: PerformanceCalendarSelectorProps) {
  const popupId = useId();
  const sortedShows = useMemo(
    () =>
      [...shows].sort((left, right) => {
        const chronological = `${left.date}T${left.time || "00:00"}`.localeCompare(
          `${right.date}T${right.time || "00:00"}`,
        );

        if (chronological !== 0) {
          return chronological;
        }

        const leftLocation =
          normalizeShowLocation(left.location ?? left.venueName) ?? "";
        const rightLocation =
          normalizeShowLocation(right.location ?? right.venueName) ?? "";

        return (
          leftLocation.localeCompare(rightLocation) ||
          left.id.localeCompare(right.id)
        );
      }),
    [shows],
  );
  const availableLocations = useMemo(() => {
    const requestedLocations =
      locations ?? showLocationOptions.map((option) => option.value);

    return requestedLocations.filter((location) =>
      sortedShows.some(
        (show) =>
          normalizeShowLocation(show.location ?? show.venueName) === location,
      ),
    );
  }, [locations, sortedShows]);
  const selectedShowAcrossLocations = sortedShows.find(
    (show) => show.id === selectedShowId || show.supabaseId === selectedShowId,
  );
  const selectedShowAcrossLocationsLocation = selectedShowAcrossLocations
    ? normalizeShowLocation(
        selectedShowAcrossLocations.location ?? selectedShowAcrossLocations.venueName,
      )
    : null;
  const [selectedLocation, setSelectedLocation] = useState<EntryLocationKey | null>(
    () =>
      (selectedShowAcrossLocationsLocation &&
      availableLocations.includes(selectedShowAcrossLocationsLocation)
        ? selectedShowAcrossLocationsLocation
        : availableLocations[0]) ?? null,
  );
  const locationShows = selectedLocation
    ? sortedShows.filter(
        (show) =>
          normalizeShowLocation(show.location ?? show.venueName) === selectedLocation,
      )
    : sortedShows;
  const today = getCurrentSouthAfricaDate();
  const nextRelevantShow =
    locationShows.find((show) => show.date >= today) ?? locationShows[0];
  const selectedShow =
    locationShows.find(
      (show) => show.id === selectedShowId || show.supabaseId === selectedShowId,
    ) ?? (allowAllShows ? undefined : nextRelevantShow);
  const initialCalendarShow = selectedShow ?? nextRelevantShow;
  const [isOpen, setIsOpen] = useState(false);
  const [calendarMonth, setCalendarMonth] = useState(
    () => initialCalendarShow?.date.slice(0, 7) ?? getCurrentShowCalendarMonth(),
  );
  const [selectedDate, setSelectedDate] = useState(
    () => selectedShow?.date ?? "",
  );

  useEffect(() => {
    if (
      selectedShowAcrossLocationsLocation &&
      availableLocations.includes(selectedShowAcrossLocationsLocation)
    ) {
      setSelectedLocation(selectedShowAcrossLocationsLocation);
      return;
    }

    setSelectedLocation((currentLocation) =>
      currentLocation && availableLocations.includes(currentLocation)
        ? currentLocation
        : availableLocations[0] ?? null,
    );
  }, [availableLocations, selectedShowAcrossLocationsLocation]);

  useEffect(() => {
    if (selectedShow) {
      setSelectedDate(selectedShow.date);
      setCalendarMonth(selectedShow.date.slice(0, 7));
      return;
    }

    if (allowAllShows) {
      setSelectedDate("");

      if (nextRelevantShow) {
        setCalendarMonth(nextRelevantShow.date.slice(0, 7));
      }
    }
  }, [allowAllShows, nextRelevantShow?.id, nextRelevantShow?.date, selectedShow?.id, selectedShow?.date]);

  const calendarAnchorDate = new Date(`${calendarMonth}-01T00:00:00`);
  const calendarMonthStart = new Date(
    calendarAnchorDate.getFullYear(),
    calendarAnchorDate.getMonth(),
    1,
  );
  const calendarDaysInMonth = new Date(
    calendarMonthStart.getFullYear(),
    calendarMonthStart.getMonth() + 1,
    0,
  ).getDate();
  const calendarStartOffset = calendarMonthStart.getDay();
  const calendarCells = [
    ...Array.from({ length: calendarStartOffset }, () => null),
    ...Array.from({ length: calendarDaysInMonth }, (_, index) => index + 1),
  ];
  const calendarMonthLabel = `${bookingCalendarMonths[calendarMonthStart.getMonth()]} ${calendarMonthStart.getFullYear()}`;
  const selectedDateShows = selectedDate
    ? locationShows.filter((show) => show.date === selectedDate)
    : [];
  const setCalendarMonthOffset = (offset: number) => {
    const [year, month] = calendarMonth.split("-").map(Number);
    const nextDate = new Date(year, month - 1 + offset, 1);

    setCalendarMonth(
      `${nextDate.getFullYear()}-${String(nextDate.getMonth() + 1).padStart(2, "0")}`,
    );
  };
  const selectDate = (dateValue: string) => {
    const dateShows = locationShows.filter((show) => show.date === dateValue);

    setSelectedDate(dateValue);

    if (dateShows.length === 1) {
      onSelect(dateShows[0].id);
      setIsOpen(false);
    }
  };
  const selectLocation = (location: EntryLocationKey) => {
    const nextLocationShows = sortedShows.filter(
      (show) =>
        normalizeShowLocation(show.location ?? show.venueName) === location,
    );
    const currentSelection = nextLocationShows.find(
      (show) => show.id === selectedShowId || show.supabaseId === selectedShowId,
    );
    const nextSelection =
      currentSelection ??
      nextLocationShows.find((show) => show.date >= today) ??
      nextLocationShows[0];

    setSelectedLocation(location);
    setSelectedDate(nextSelection?.date ?? "");
    setCalendarMonth(
      nextSelection?.date.slice(0, 7) ?? getCurrentShowCalendarMonth(),
    );

    if (nextSelection && nextSelection.id !== selectedShowId) {
      onSelect(nextSelection.id);
    }
  };

  return (
    <div className="relative">
      <button
        type="button"
        aria-expanded={isOpen}
        aria-controls={popupId}
        onClick={() => setIsOpen((current) => !current)}
        className={
          buttonClassName ??
          "mt-2 w-full rounded-xl border border-zinc-700 bg-black px-4 py-3 text-left text-white transition hover:border-[#D8C36A]/60 focus:border-[#D8C36A]/70 focus:outline-none"
        }
      >
        {selectedShow
          ? getFloorShowSelectorLabel(selectedShow)
          : allowAllShows && selectedShowId === "all"
            ? allLabel
            : emptyLabel}
      </button>

      {isOpen && (
        <div
          id={popupId}
          className="absolute left-0 top-[calc(100%+0.5rem)] z-40 w-[21rem] max-w-[86vw] rounded-[1.5rem] border border-[#D8C36A]/25 bg-zinc-950 p-4 shadow-2xl shadow-black/50"
        >
          {availableLocations.length > 1 && (
            <div
              className="mb-3 grid grid-cols-2 gap-2"
              aria-label={`${label} location`}
            >
              {availableLocations.map((location) => (
                <button
                  key={`${popupId}-${location}`}
                  type="button"
                  onClick={() => selectLocation(location)}
                  className={`rounded-full border px-3 py-2 text-xs font-semibold transition ${
                    selectedLocation === location
                      ? "border-[#D8C36A] bg-[#D8C36A] text-black"
                      : "border-white/15 bg-black/35 text-zinc-300 hover:border-[#D8C36A]/60 hover:text-white"
                  }`}
                >
                  {getShowCalendarLocationDisplay(location).alias}
                </button>
              ))}
            </div>
          )}
          <div className="mb-3 flex items-center justify-between">
            <button
              type="button"
              onClick={() => setCalendarMonthOffset(-1)}
              className="grid h-8 w-8 place-items-center rounded-full border border-white/15 text-lg text-zinc-300 transition hover:border-[#D8C36A] hover:text-[#F2D66C]"
              aria-label={`Previous ${label.toLowerCase()} month`}
            >
              ‹
            </button>
            <p className="text-sm font-semibold text-white">
              {calendarMonthLabel}
            </p>
            <button
              type="button"
              onClick={() => setCalendarMonthOffset(1)}
              className="grid h-8 w-8 place-items-center rounded-full border border-white/15 text-lg text-zinc-300 transition hover:border-[#D8C36A] hover:text-[#F2D66C]"
              aria-label={`Next ${label.toLowerCase()} month`}
            >
              ›
            </button>
          </div>
          <div className="grid grid-cols-7 gap-1 text-center text-[0.65rem] font-semibold uppercase tracking-[0.12em] text-zinc-400">
            {bookingCalendarWeekdays.map((weekday, index) => (
              <span key={`${popupId}-weekday-${weekday}-${index}`}>
                {weekday}
              </span>
            ))}
          </div>
          <div className="mt-2 grid grid-cols-7 gap-1">
            {calendarCells.map((day, index) => {
              if (!day) {
                return (
                  <span
                    key={`${popupId}-empty-${index}`}
                    className="aspect-square"
                  />
                );
              }

              const dateValue = `${calendarMonthStart.getFullYear()}-${String(
                calendarMonthStart.getMonth() + 1,
              ).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
              const showsForDate = locationShows.filter(
                (show) => show.date === dateValue,
              );
              const isAvailable = showsForDate.length > 0;
              const isSelected = selectedDate === dateValue;
              const isToday = dateValue === today;

              return (
                <button
                  key={`${popupId}-${dateValue}`}
                  type="button"
                  disabled={!isAvailable}
                  onClick={() => selectDate(dateValue)}
                  title={
                    isAvailable
                      ? `${showsForDate.length} active performance${showsForDate.length === 1 ? "" : "s"}`
                      : "No active performance"
                  }
                  className={`aspect-square rounded-xl text-sm font-semibold transition ${
                    isSelected
                      ? "bg-[#D8C36A] text-black"
                      : isAvailable
                        ? "border border-[#D8C36A]/25 bg-[#D8C36A]/10 text-[#F2D66C] hover:bg-[#D8C36A]/20"
                        : isToday
                          ? "border border-white/15 bg-white/[0.04] text-zinc-500"
                          : "bg-white/[0.03] text-zinc-700"
                  } ${isToday ? "ring-1 ring-white/20" : ""}`}
                >
                  {day}
                </button>
              );
            })}
          </div>
          {allowAllShows && (
            <div className="mt-4 border-t border-white/10 pt-3">
              <button
                type="button"
                onClick={() => {
                  onSelect("all");
                  setSelectedDate("");
                  setIsOpen(false);
                }}
                className={`w-full rounded-full border px-3 py-2 text-xs font-semibold uppercase tracking-[0.12em] transition ${
                  selectedShowId === "all"
                    ? "border-[#D8C36A] bg-[#D8C36A] text-black"
                    : "border-white/15 bg-black/35 text-zinc-300 hover:border-[#D8C36A]/60 hover:text-white"
                }`}
              >
                {allLabel}
              </button>
            </div>
          )}
          {selectedDateShows.length > 1 && (
            <div className="mt-4 border-t border-white/10 pt-3">
              <p className="mb-2 text-[0.62rem] font-semibold uppercase tracking-[0.16em] text-zinc-500">
                Choose Performance
              </p>
              <div className="flex flex-wrap gap-2">
                {selectedDateShows.map((show) => {
                  const location = normalizeShowLocation(
                    show.location ?? show.venueName,
                  );
                  const locationLabel = location
                    ? getShowCalendarLocationDisplay(location).alias
                    : "LOC";
                  const isSelected = selectedShowId === show.id;

                  return (
                    <button
                      key={`${popupId}-performance-${show.id}`}
                      type="button"
                      onClick={() => {
                        onSelect(show.id);
                        setIsOpen(false);
                      }}
                      className={`rounded-full border px-3 py-2 text-xs font-semibold uppercase tracking-[0.1em] transition ${
                        isSelected
                          ? "border-[#D8C36A] bg-[#D8C36A] text-black"
                          : "border-white/15 bg-black/35 text-zinc-300 hover:border-[#D8C36A]/60 hover:text-white"
                      }`}
                    >
                      {locationLabel} · {getSouthAfricaShowTime(show)}
                    </button>
                  );
                })}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function createZingaraUserEmail(
  name: string,
  username: string,
  email?: string,
) {
  const trimmedEmail = email?.trim();

  if (trimmedEmail && !trimmedEmail.endsWith(".example")) {
    return trimmedEmail;
  }

  const nameParts = name
    .toLowerCase()
    .replaceAll(/[^a-z\s-]/g, "")
    .split(/\s+/)
    .filter(Boolean);

  const handle =
    nameParts.length >= 2
      ? `${nameParts[0]}.${nameParts[nameParts.length - 1]}`
      : nameParts[0] ??
        username
          .toLowerCase()
          .replaceAll(/[^a-z0-9.-]/g, "")
          .replaceAll(/\.+/g, ".") ??
        "staff";

  return `${handle || "staff"}@zingara.co.za`;
}

function escapeCsvValue(value: string | number | undefined) {
  const stringValue = String(value ?? "");

  return /[",\n]/.test(stringValue)
    ? `"${stringValue.replaceAll('"', '""')}"`
    : stringValue;
}

function createCsv(rows: Array<Record<string, string | number | undefined>>) {
  if (rows.length === 0) {
    return "";
  }

  const headers = Object.keys(rows[0]);

  return [
    headers.map(escapeCsvValue).join(","),
    ...rows.map((row) =>
      headers.map((header) => escapeCsvValue(row[header])).join(","),
    ),
  ].join("\n");
}

function createCsvFromSheet(sheet: ExportSheet) {
  return [
    sheet.columns.map(escapeCsvValue).join(","),
    ...sheet.rows.map((row) =>
      sheet.columns
        .map((column) => escapeCsvValue(String(row[column] ?? "")))
        .join(","),
    ),
  ].join("\n");
}

function sanitizeExportFileName(value: string) {
  return value
    .replaceAll(/[^A-Za-z0-9._-]+/g, "-")
    .replaceAll(/-+/g, "-")
    .replaceAll(/^-|-$/g, "");
}

function escapeXml(value: ExportCellValue) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function getExcelColumnName(index: number) {
  let columnName = "";
  let currentIndex = index + 1;

  while (currentIndex > 0) {
    const remainder = (currentIndex - 1) % 26;
    columnName = String.fromCharCode(65 + remainder) + columnName;
    currentIndex = Math.floor((currentIndex - 1) / 26);
  }

  return columnName;
}

function getExcelSerialDate(date: Date) {
  const epoch = Date.UTC(1899, 11, 30);

  return (date.getTime() - epoch) / 86400000;
}

function buildCrc32Table() {
  return Array.from({ length: 256 }, (_, index) => {
    let crc = index;

    for (let bit = 0; bit < 8; bit += 1) {
      crc = crc & 1 ? 0xedb88320 ^ (crc >>> 1) : crc >>> 1;
    }

    return crc >>> 0;
  });
}

const crc32Table = buildCrc32Table();

function crc32(bytes: Uint8Array) {
  let crc = 0xffffffff;

  bytes.forEach((byte) => {
    crc = crc32Table[(crc ^ byte) & 0xff] ^ (crc >>> 8);
  });

  return (crc ^ 0xffffffff) >>> 0;
}

function writeUint16(bytes: number[], value: number) {
  bytes.push(value & 0xff, (value >>> 8) & 0xff);
}

function writeUint32(bytes: number[], value: number) {
  bytes.push(
    value & 0xff,
    (value >>> 8) & 0xff,
    (value >>> 16) & 0xff,
    (value >>> 24) & 0xff,
  );
}

function createZipBlob(files: Array<{ content: string; path: string }>) {
  const encoder = new TextEncoder();
  const bytes: number[] = [];
  const centralDirectory: number[] = [];

  files.forEach((file) => {
    const nameBytes = encoder.encode(file.path);
    const contentBytes = encoder.encode(file.content);
    const checksum = crc32(contentBytes);
    const localHeaderOffset = bytes.length;

    writeUint32(bytes, 0x04034b50);
    writeUint16(bytes, 20);
    writeUint16(bytes, 0);
    writeUint16(bytes, 0);
    writeUint16(bytes, 0);
    writeUint16(bytes, 0);
    writeUint32(bytes, checksum);
    writeUint32(bytes, contentBytes.length);
    writeUint32(bytes, contentBytes.length);
    writeUint16(bytes, nameBytes.length);
    writeUint16(bytes, 0);
    bytes.push(...nameBytes, ...contentBytes);

    writeUint32(centralDirectory, 0x02014b50);
    writeUint16(centralDirectory, 20);
    writeUint16(centralDirectory, 20);
    writeUint16(centralDirectory, 0);
    writeUint16(centralDirectory, 0);
    writeUint16(centralDirectory, 0);
    writeUint16(centralDirectory, 0);
    writeUint32(centralDirectory, checksum);
    writeUint32(centralDirectory, contentBytes.length);
    writeUint32(centralDirectory, contentBytes.length);
    writeUint16(centralDirectory, nameBytes.length);
    writeUint16(centralDirectory, 0);
    writeUint16(centralDirectory, 0);
    writeUint16(centralDirectory, 0);
    writeUint16(centralDirectory, 0);
    writeUint32(centralDirectory, 0);
    writeUint32(centralDirectory, localHeaderOffset);
    centralDirectory.push(...nameBytes);
  });

  const centralDirectoryOffset = bytes.length;

  bytes.push(...centralDirectory);
  writeUint32(bytes, 0x06054b50);
  writeUint16(bytes, 0);
  writeUint16(bytes, 0);
  writeUint16(bytes, files.length);
  writeUint16(bytes, files.length);
  writeUint32(bytes, centralDirectory.length);
  writeUint32(bytes, centralDirectoryOffset);
  writeUint16(bytes, 0);

  return new Blob([new Uint8Array(bytes)], {
    type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  });
}

function isCurrencyExportLabel(label: string) {
  const normalized = label.toLowerCase();

  if (
    normalized.includes("status") ||
    normalized.includes("method") ||
    normalized.includes("description") ||
    normalized.includes("date") ||
    normalized.includes("reference") ||
    normalized.includes("count") ||
    normalized.includes("number") ||
    normalized.includes("guest") ||
    normalized.includes("table") ||
    normalized.includes("average") ||
    (normalized.includes("booking") &&
      !normalized.includes("income") &&
      !normalized.includes("payment") &&
      !normalized.includes("revenue") &&
      !normalized.includes("value"))
  ) {
    return false;
  }

  return [
    "amount",
    "balance",
    "cash",
    "collected",
    "deposit",
    "income",
    "outstanding",
    "payment",
    "refund",
    "revenue",
    "total",
    "value",
  ].some((token) => normalized.includes(token));
}

function formatExportValueForPdf(label: string, value: ExportCellValue | undefined) {
  if (value instanceof Date) {
    return formatSouthAfricanDate(value);
  }

  if (typeof value === "number" && isCurrencyExportLabel(label)) {
    return `R ${value
      .toLocaleString("en-ZA", {
        maximumFractionDigits: 2,
        minimumFractionDigits: 2,
      })
      .replaceAll("\u00a0", " ")}`;
  }

  return String(value ?? "Not recorded");
}

function createWorksheetXml(sheet: ExportSheet) {
  const headerRows = [
    [`Generated`, new Date()],
    ...(sheet.summary ?? []),
    [],
  ];
  const rows: ExportCellValue[][] = [
    ...headerRows,
    sheet.columns,
    ...sheet.rows.map((row) =>
      sheet.columns.map((column) => row[column] ?? ""),
    ),
  ];
  const tableHeaderIndex = headerRows.length + 1;
  const lastColumn = getExcelColumnName(Math.max(sheet.columns.length - 1, 0));
  const lastRow = Math.max(rows.length, tableHeaderIndex);
  const sheetData = rows
    .map((row, rowIndex) => {
      const rowNumber = rowIndex + 1;
      const cells = row
        .map((value, columnIndex) => {
          const ref = `${getExcelColumnName(columnIndex)}${rowNumber}`;
          const tableColumnLabel =
            rowIndex > tableHeaderIndex - 1
              ? String(rows[tableHeaderIndex - 1]?.[columnIndex] ?? "")
              : "";
          const summaryLabel =
            rowIndex < tableHeaderIndex - 1 && columnIndex === 1
              ? String(row[0] ?? "")
              : "";

          if (value instanceof Date) {
            return `<c r="${ref}" s="2"><v>${getExcelSerialDate(value)}</v></c>`;
          }

          if (typeof value === "number") {
            const style =
              isCurrencyExportLabel(tableColumnLabel || summaryLabel) ? 1 : 0;

            return `<c r="${ref}" s="${style}"><v>${value}</v></c>`;
          }

          return `<c r="${ref}" t="inlineStr"><is><t>${escapeXml(value)}</t></is></c>`;
        })
        .join("");

      return `<row r="${rowNumber}">${cells}</row>`;
    })
    .join("");
  const autoFilter =
    sheet.columns.length > 0
      ? `<autoFilter ref="A${tableHeaderIndex}:${lastColumn}${lastRow}"/>`
      : "";
  const columnWidths = sheet.columns
    .map((column, index) => {
      const maxLength = Math.min(
        Math.max(
          column.length,
          ...sheet.rows.map((row) => String(row[column] ?? "").length),
          12,
        ),
        34,
      );

      return `<col min="${index + 1}" max="${index + 1}" width="${maxLength + 2}" customWidth="1"/>`;
    })
    .join("");

  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="${tableHeaderIndex}" topLeftCell="A${tableHeaderIndex + 1}" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>${columnWidths}</cols><sheetData>${sheetData}</sheetData>${autoFilter}</worksheet>`;
}

function createXlsxBlob(sheets: ExportSheet[]) {
  const workbookSheets = sheets
    .map(
      (sheet, index) =>
        `<sheet name="${escapeXml(sheet.name.slice(0, 31))}" sheetId="${index + 1}" r:id="rId${index + 1}"/>`,
    )
    .join("");
  const workbookRels = sheets
    .map(
      (_, index) =>
        `<Relationship Id="rId${index + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${index + 1}.xml"/>`,
    )
    .join("");
  const contentTypes = sheets
    .map(
      (_, index) =>
        `<Override PartName="/xl/worksheets/sheet${index + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`,
    )
    .join("");
  const files = [
    {
      path: "[Content_Types].xml",
      content: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${contentTypes}</Types>`,
    },
    {
      path: "_rels/.rels",
      content: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`,
    },
    {
      path: "xl/workbook.xml",
      content: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${workbookSheets}</sheets></workbook>`,
    },
    {
      path: "xl/_rels/workbook.xml.rels",
      content: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${workbookRels}<Relationship Id="rId${sheets.length + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`,
    },
    {
      path: "xl/styles.xml",
      content: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><numFmts count="1"><numFmt numFmtId="164" formatCode="R #,##0.00"/></numFmts><fonts count="1"><font><sz val="11"/><name val="Aptos"/></font></fonts><fills count="1"><fill><patternFill patternType="none"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="3"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="164" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/><xf numFmtId="14" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>`,
    },
    ...sheets.map((sheet, index) => ({
      path: `xl/worksheets/sheet${index + 1}.xml`,
      content: createWorksheetXml(sheet),
    })),
  ];

  return createZipBlob(files);
}

function escapePdfText(value: string) {
  return value
    .replaceAll("·", "-")
    .replaceAll("–", "-")
    .replaceAll("—", "-")
    .replaceAll("’", "'")
    .replaceAll("“", '"')
    .replaceAll("”", '"')
    .replaceAll("\u00a0", " ")
    .replaceAll("\\", "\\\\")
    .replaceAll("(", "\\(")
    .replaceAll(")", "\\)");
}

function createReportPdfBlob({
  landscape = false,
  sheets,
  subtitle,
  title,
}: {
  landscape?: boolean;
  sheets: ExportSheet[];
  subtitle: string;
  title: string;
}) {
  const width = landscape ? 842 : 595;
  const height = landscape ? 595 : 842;
  const margin = 40;
  const lineHeight = 13;
  const pages: string[] = [];
  const addPage = () => {
    pages.push("");
  };
  const addLine = (text: string, x: number, y: number, size = 9) => {
    pages[pages.length - 1] += `BT /F1 ${size} Tf ${x} ${y} Td (${escapePdfText(text)}) Tj ET\n`;
  };

  addPage();
  let y = height - margin;
  addLine(title, margin, y, 16);
  y -= 18;
  addLine(subtitle, margin, y, 9);
  y -= 18;
  addLine(`Generated ${formatSouthAfricanTimestamp(new Date())}`, margin, y, 8);
  y -= 22;

  sheets.forEach((sheet) => {
    if (y < 120) {
      addPage();
      y = height - margin;
    }

    addLine(sheet.name, margin, y, 13);
    y -= 16;

    (sheet.summary ?? []).forEach(([label, value]) => {
      if (y < margin) {
        addPage();
        y = height - margin;
      }
      addLine(`${label}: ${formatExportValueForPdf(label, value)}`, margin, y, 8);
      y -= lineHeight;
    });

    const visibleColumns = sheet.columns.slice(
      0,
      landscape ? 9 : 7,
    );

    if (visibleColumns.length > 0) {
      if (y < 80) {
        addPage();
        y = height - margin;
      }
      addLine(visibleColumns.join(" | "), margin, y, 7);
      y -= lineHeight;
    }

    const rows = sheet.rows.length > 0 ? sheet.rows : [{ Notice: "No matching records" }];
    rows.forEach((row) => {
      if (y < margin + 24) {
        addPage();
        y = height - margin;
        if (visibleColumns.length > 0) {
          addLine(visibleColumns.join(" | "), margin, y, 7);
          y -= lineHeight;
        }
      }

      addLine(
        visibleColumns
          .map((column) => {
            const value = row[column];

            return formatExportValueForPdf(column, value);
          })
          .join(" | ")
          .slice(0, 150),
        margin,
        y,
        7,
      );
      y -= lineHeight;
    });

    y -= 14;
  });

  const objects: string[] = [];
  const pageRefs: string[] = [];

  objects.push("<< /Type /Catalog /Pages 2 0 R >>");
  objects.push("");
  objects.push("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>");

  pages.forEach((content, index) => {
    const pageObjectId = objects.length + 1;
    const contentObjectId = pageObjectId + 1;

    pageRefs.push(`${pageObjectId} 0 R`);
    objects.push(
      `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${width} ${height}] /Resources << /Font << /F1 3 0 R >> >> /Contents ${contentObjectId} 0 R >>`,
    );
    objects.push(
      `<< /Length ${content.length} >>\nstream\n${content}BT /F1 8 Tf ${width - 90} 24 Td (Page ${index + 1} of ${pages.length}) Tj ET\nendstream`,
    );
  });

  objects[1] = `<< /Type /Pages /Kids [${pageRefs.join(" ")}] /Count ${pages.length} >>`;

  let pdf = "%PDF-1.4\n";
  const offsets: number[] = [0];

  objects.forEach((object, index) => {
    offsets.push(pdf.length);
    pdf += `${index + 1} 0 obj\n${object}\nendobj\n`;
  });

  const xrefOffset = pdf.length;
  pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
  offsets.slice(1).forEach((offset) => {
    pdf += `${String(offset).padStart(10, "0")} 00000 n \n`;
  });
  pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`;

  return new Blob([pdf], { type: "application/pdf" });
}

function parseCsvTable(text: string) {
  const rows: string[][] = [];
  let field = "";
  let row: string[] = [];
  let isQuoted = false;

  for (let index = 0; index < text.length; index += 1) {
    const character = text[index];
    const nextCharacter = text[index + 1];

    if (character === '"' && isQuoted && nextCharacter === '"') {
      field += '"';
      index += 1;
    } else if (character === '"') {
      isQuoted = !isQuoted;
    } else if (character === "," && !isQuoted) {
      row.push(field.trim());
      field = "";
    } else if (
      (character === "\n" || character === "\r") &&
      !isQuoted
    ) {
      if (character === "\r" && nextCharacter === "\n") {
        index += 1;
      }
      row.push(field.trim());
      if (row.some(Boolean)) {
        rows.push(row);
      }
      field = "";
      row = [];
    } else {
      field += character;
    }
  }

  if (isQuoted) {
    throw new Error("Malformed CSV: a quoted field was not closed.");
  }

  row.push(field.trim());
  if (row.some(Boolean)) {
    rows.push(row);
  }

  return rows;
}

function normalizePortabilityKey(value: string) {
  return value
    .trim()
    .toLowerCase()
    .replaceAll(/[^a-z0-9]+/g, "_")
    .replaceAll(/^_|_$/g, "");
}

function normalizePortabilityLookupValue(value: string) {
  return value.trim().toLowerCase();
}

function isExcelSerialNumber(value: string) {
  return /^\d+(\.\d+)?$/.test(value.trim());
}

function parseExcelSerialDate(value: number) {
  const excelEpoch = Date.UTC(1899, 11, 30);

  return new Date(excelEpoch + value * 86400000);
}

function formatImportDateValue(value?: string | null) {
  const trimmedValue = value?.trim();

  if (!trimmedValue) {
    return "";
  }

  if (isExcelSerialNumber(trimmedValue)) {
    const parsedDate = parseExcelSerialDate(Number(trimmedValue));

    if (!Number.isNaN(parsedDate.getTime())) {
      return parsedDate.toISOString().slice(0, 10);
    }
  }

  const directDateMatch = trimmedValue.match(
    /^(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})$/,
  );

  if (directDateMatch) {
    const [, day, month, year] = directDateMatch;
    const fullYear = year.length === 2 ? `20${year}` : year;

    return `${fullYear}-${month.padStart(2, "0")}-${day.padStart(2, "0")}`;
  }

  const parsedDate = new Date(trimmedValue);

  if (!Number.isNaN(parsedDate.getTime())) {
    return parsedDate.toISOString().slice(0, 10);
  }

  return trimmedValue;
}

function formatImportTimeValue(value?: string | null) {
  const trimmedValue = value?.trim();

  if (!trimmedValue) {
    return "";
  }

  if (isExcelSerialNumber(trimmedValue)) {
    const numericValue = Number(trimmedValue);
    const fractionalDay = numericValue % 1;
    const totalMinutes = Math.round(fractionalDay * 24 * 60);
    const hours = Math.floor(totalMinutes / 60) % 24;
    const minutes = totalMinutes % 60;

    return `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}`;
  }

  const directMatch = trimmedValue.match(/\b(\d{1,2})[:hH](\d{2})\b/);

  if (directMatch) {
    return `${directMatch[1].padStart(2, "0")}:${directMatch[2]}`;
  }

  const hourOnlyMatch = trimmedValue.match(/\b(\d{1,2})\b/);

  if (
    hourOnlyMatch &&
    trimmedValue.replace(/\D/g, "") === hourOnlyMatch[1]
  ) {
    return `${hourOnlyMatch[1].padStart(2, "0")}:00`;
  }

  return trimmedValue;
}

function getImportMoneyValue(value?: string | null) {
  const trimmedValue = value?.trim();

  if (!trimmedValue) {
    return "";
  }

  const parsedValue = Number(trimmedValue.replace(/[^\d.-]/g, ""));

  return Number.isFinite(parsedValue) ? String(parsedValue) : "";
}

function getImportMoneyNumber(value?: string | null) {
  return Number(getImportMoneyValue(value) || 0);
}

function formatImportMoneyNumber(value: number) {
  const normalizedValue = Math.max(
    Math.round((Number.isFinite(value) ? value : 0) * 100) / 100,
    0,
  );

  return Number.isInteger(normalizedValue)
    ? String(normalizedValue)
    : normalizedValue.toFixed(2);
}

function getDineplanValue(record: Record<string, string>, key: string) {
  return record[normalizePortabilityKey(key)]?.trim() ?? "";
}

function isDineplanLegacyHeaders(headers: string[]) {
  const headerKeys = new Set(headers.map(normalizePortabilityKey));
  const dineplanHeaderMatches = [
    "booking_reference",
    "booking_type",
    "source",
    "last_modified",
    "created",
    "last_modified_by",
    "booking_status",
    "booking_date",
    "booking_month",
    "time",
    "seating_area",
    "covers",
    "table_s",
    "guest_name",
    "requested_amount",
    "total_paid",
    "total_refunded",
    "total_balance",
  ].filter((key) => headerKeys.has(key));

  return (
    headerKeys.has("booking_reference") &&
    headerKeys.has("guest_name") &&
    headerKeys.has("covers") &&
    headerKeys.has("seating_area") &&
    headerKeys.has("time") &&
    dineplanHeaderMatches.length >= 6
  );
}

type DineplanGuestListRecord = {
  company: string;
  email: string;
  emailOptIn: string;
  firstName: string;
  fullName: string;
  notes: string;
  phone: string;
  smsOptIn: string;
  sourceId: string;
  surname: string;
};

function isDineplanGuestListHeaders(headers: string[]) {
  const headerKeys = new Set(headers.map(normalizePortabilityKey));

  return (
    (headerKeys.has("first_name") || headerKeys.has("firstname")) &&
    (headerKeys.has("last_name") ||
      headerKeys.has("surname") ||
      headerKeys.has("lastname")) &&
    (headerKeys.has("contact_number") ||
      headerKeys.has("phone") ||
      headerKeys.has("mobile") ||
      headerKeys.has("email"))
  );
}

function getDineplanGuestListValue(
  record: Record<string, string>,
  ...keys: string[]
) {
  for (const key of keys) {
    const value = record[normalizePortabilityKey(key)]?.trim();

    if (value) {
      return value;
    }
  }

  return "";
}

function normalizeDineplanPersonKey(value: string) {
  return value
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/\p{Diacritic}/gu, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function parseDineplanGuestList(
  parsed: { headers: string[]; records: Record<string, string>[] },
) {
  if (!isDineplanGuestListHeaders(parsed.headers)) {
    throw new Error("Upload a Dineplan Guest List export with First Name, Last Name and contact columns.");
  }

  return parsed.records
    .map((record) => {
      const firstName = getDineplanGuestListValue(
        record,
        "First Name",
        "Firstname",
      );
      const surname = getDineplanGuestListValue(
        record,
        "Last Name",
        "Surname",
        "Lastname",
      );

      return {
        company: getDineplanGuestListValue(record, "Company"),
        email: getDineplanGuestListValue(record, "Email"),
        emailOptIn: getDineplanGuestListValue(
          record,
          "Email Opt In",
          "Email Opt-In",
          "Email OptIn",
        ),
        firstName,
        fullName: [firstName, surname].filter(Boolean).join(" ").trim(),
        notes: [
          getDineplanGuestListValue(record, "Notes"),
          getDineplanGuestListValue(record, "Guest Notes"),
          getDineplanGuestListValue(record, "Tags"),
        ]
          .filter(Boolean)
          .join(" | "),
        phone: getDineplanGuestListValue(
          record,
          "Contact Number",
          "Phone",
          "Mobile",
          "Cell",
        ),
        smsOptIn: getDineplanGuestListValue(
          record,
          "SMS Opt In",
          "Sms Opt In",
          "SMS Opt-In",
          "Sms OptIn",
        ),
        sourceId: getDineplanGuestListValue(
          record,
          "Guest ID",
          "Customer ID",
          "Dineplan Guest ID",
          "ID",
        ),
        surname,
      } satisfies DineplanGuestListRecord;
    })
    .filter((record) => record.firstName || record.surname || record.email || record.phone);
}

function getConsentStatus(value: string) {
  const normalizedValue = normalizePortabilityLookupValue(value);

  if (["yes", "y", "true", "1", "opted in", "subscribed"].includes(normalizedValue)) {
    return "Yes";
  }

  if (["no", "n", "false", "0", "opted out", "unsubscribed"].includes(normalizedValue)) {
    return "No";
  }

  return "Unknown";
}

function maskContactAvailability(value: string) {
  return value.trim() ? "Available" : "Not available";
}

function getReservationGuestMatch(
  sourceGuestName: string,
  sourceGuestId: string,
  guestList: DineplanGuestListRecord[] | null,
) {
  if (!guestList) {
    return {
      status: "NO GUEST LIST",
      candidates: [] as DineplanGuestListRecord[],
      match: null as DineplanGuestListRecord | null,
    };
  }

  if (sourceGuestId.trim()) {
    const idCandidates = guestList.filter(
      (guest) =>
        normalizePortabilityLookupValue(guest.sourceId) ===
        normalizePortabilityLookupValue(sourceGuestId),
    );

    if (idCandidates.length === 1) {
      return {
        status: "MATCHED",
        candidates: idCandidates,
        match: idCandidates[0],
      };
    }

    if (idCandidates.length > 1) {
      return {
        status: "AMBIGUOUS",
        candidates: idCandidates,
        match: null as DineplanGuestListRecord | null,
      };
    }
  }

  const nameParts = sourceGuestName.trim().split(/\s+/).filter(Boolean);
  const firstName = normalizeDineplanPersonKey(nameParts[0] ?? "");
  const surnameInitial =
    normalizeDineplanPersonKey(nameParts[1] ?? "").charAt(0) || "";

  if (!firstName || !surnameInitial) {
    return {
      status: "NO MATCH",
      candidates: [] as DineplanGuestListRecord[],
      match: null as DineplanGuestListRecord | null,
    };
  }

  const candidates = guestList.filter(
    (guest) =>
      normalizeDineplanPersonKey(guest.firstName) === firstName &&
      normalizeDineplanPersonKey(guest.surname).startsWith(surnameInitial),
  );

  if (candidates.length === 1) {
    return {
      status: "MATCHED",
      candidates,
      match: candidates[0],
    };
  }

  return {
    status: candidates.length > 1 ? "AMBIGUOUS" : "NO MATCH",
    candidates,
    match: null as DineplanGuestListRecord | null,
  };
}

function normalizeDineplanStatus(value: string) {
  const normalizedValue = normalizePortabilityLookupValue(value);

  if (normalizedValue.includes("cancel")) {
    return "Cancelled";
  }

  if (normalizedValue.includes("no show")) {
    return "No Show";
  }

  if (normalizedValue.includes("deposit required")) {
    return "Pending Payment";
  }

  if (normalizedValue.includes("active")) {
    return "Confirmed";
  }

  return value || "Pending Payment";
}

function normalizeDineplanPaymentStatus(record: Record<string, string>) {
  const status = normalizePortabilityLookupValue(getDineplanValue(record, "Booking Status"));
  const bookingTotal = getImportMoneyNumber(getDineplanValue(record, "Requested Amount"));
  const totalPaid = getImportMoneyNumber(getDineplanValue(record, "Total Paid"));
  const totalRefunded = getImportMoneyNumber(getDineplanValue(record, "Total Refunded"));
  const netPaid = Math.max(totalPaid - totalRefunded, 0);

  if (status.includes("deposit required")) {
    return "Pending Payment";
  }

  if (bookingTotal <= 0) {
    return "Comp/VIP";
  }

  if (totalRefunded > 0 && netPaid <= 0) {
    return "Refunded";
  }

  if (netPaid >= bookingTotal) {
    return "Fully Paid";
  }

  if (netPaid > 0) {
    return "Deposit Paid";
  }

  return "Pending Payment";
}

function normalizeDineplanSeatingArea(value: string) {
  const normalizedValue = normalizePortabilityLookupValue(value);
  const withoutPrice = value.replace(/\s*r\s*\d+(\.\d{1,2})?\s*pp\b/i, "").trim();

  if (normalizedValue.includes("golden circle")) {
    return "Golden Circle";
  }

  if (normalizedValue.includes("middle ring")) {
    return "Middle Ring";
  }

  if (
    normalizedValue.includes("private raised booth") ||
    normalizedValue.includes("private booth") ||
    normalizedValue.includes("royal booth")
  ) {
    return "Private Booths";
  }

  if (
    normalizedValue.includes("royal balcony") ||
    normalizedValue.includes("balcony")
  ) {
    return "Royal Balcony";
  }

  return withoutPrice || value;
}

function getDineplanTableValue(record: Record<string, string>) {
  return (
    getDineplanValue(record, "Table(s)") ||
    getDineplanValue(record, "Tables") ||
    getDineplanValue(record, "Table")
  );
}

function getDineplanAnyValue(record: Record<string, string>, keys: string[]) {
  for (const key of keys) {
    const value = getDineplanValue(record, key);

    if (value) {
      return value;
    }
  }

  return "";
}

function normalizeDineplanRecord(
  record: Record<string, string>,
  sourceLocation: DataPortabilitySourceLocation,
) {
  const bookingDate = formatImportDateValue(getDineplanValue(record, "Booking Date"));
  const showTime = formatImportTimeValue(getDineplanValue(record, "Time"));
  const requestedAmount = getImportMoneyNumber(getDineplanValue(record, "Requested Amount"));
  const totalPaid = getImportMoneyNumber(getDineplanValue(record, "Total Paid"));
  const totalRefunded = getImportMoneyNumber(getDineplanValue(record, "Total Refunded"));
  const netPaid = Math.max(totalPaid - totalRefunded, 0);
  const balanceDue = Math.max(requestedAmount - netPaid, 0);
  const legacyTotalBalance = getImportMoneyValue(
    getDineplanValue(record, "Total Balance"),
  );
  const sourceReference = getDineplanValue(record, "Booking Reference");

  return {
    booking_date:
      formatImportDateValue(getDineplanValue(record, "Created")) || bookingDate,
    booking_reference: sourceReference
      ? `DP-${sourceReference.replace(/[^A-Za-z0-9-]/g, "").toUpperCase()}`
      : "",
    booking_status: normalizeDineplanStatus(
      getDineplanValue(record, "Booking Status"),
    ),
    booking_total: formatImportMoneyNumber(requestedAmount),
    booking_type: getDineplanValue(record, "Booking Type") || "Standard",
    corporate_flag: getDineplanValue(record, "Company") ? "Yes" : "No",
    customer_email: "",
    customer_name:
      getDineplanValue(record, "Guest Name") ||
      getDineplanValue(record, "Company") ||
      getDineplanValue(record, "Group Name"),
    customer_phone: "",
    guest_notes: [
      getDineplanValue(record, "Booking Notes"),
      getDineplanValue(record, "Guest Notes"),
      getDineplanValue(record, "Special Requests"),
      getDineplanValue(record, "Payment Notes"),
      legacyTotalBalance
        ? `Legacy Total Balance: R${legacyTotalBalance}`
        : "",
    ]
      .filter(Boolean)
      .join(" | "),
    location: sourceLocation,
    number_of_guests: getDineplanValue(record, "Covers"),
    payment_status: normalizeDineplanPaymentStatus(record),
    seating_zone: normalizeDineplanSeatingArea(
      getDineplanValue(record, "Seating Area"),
    ),
    show: "Dineplan Legacy Export",
    show_date: bookingDate,
    show_time: showTime,
    source_booking_reference: sourceReference,
    source_date: bookingDate,
    source_format: "Dineplan Legacy Export",
    source_guest_id: getDineplanAnyValue(record, [
      "Guest ID",
      "Customer ID",
      "Dineplan Guest ID",
    ]),
    source_legacy_total_balance: legacyTotalBalance,
    source_total_paid: formatImportMoneyNumber(totalPaid),
    source_total_refunded: formatImportMoneyNumber(totalRefunded),
    source_seating_area: getDineplanValue(record, "Seating Area"),
    source_table: getDineplanTableValue(record),
    source_time: showTime,
    table: getDineplanTableValue(record),
    amount_paid: formatImportMoneyNumber(netPaid),
    balance_due: formatImportMoneyNumber(balanceDue),
  };
}

function normalizePortabilityParsedTable(
  parsed: { headers: string[]; records: Record<string, string>[] },
  entity: DataPortabilityEntity,
  sourceLocation: DataPortabilitySourceLocation,
) {
  if (entity !== "bookings" || !isDineplanLegacyHeaders(parsed.headers)) {
    return {
      ...parsed,
      sourceFormat: "zingara-template" as DataPortabilitySourceFormat,
    };
  }

  return {
    headers: dataPortabilityColumns.bookings.map((column) => column.label),
    records: parsed.records.map((record) =>
      normalizeDineplanRecord(record, sourceLocation),
    ),
    sourceFormat: "dineplan-legacy" as DataPortabilitySourceFormat,
  };
}

function parsePortabilityTable(rows: string[][]) {
  if (rows.length < 2) {
    return { headers: rows[0] ?? [], records: [] };
  }

  const knownHeaderKeys = new Set(
    [
      ...Object.values(dataPortabilityColumns)
        .flat()
        .map((column) => column.key),
      "booking_month",
      "cancelled",
      "company",
      "contact_number",
      "covers",
      "created",
      "deleted",
      "dineplan_guest_id",
      "email",
      "email_opt_in",
      "email_optin",
      "first_name",
      "firstname",
      "guest_name",
      "guest_id",
      "last_modified",
      "last_modified_by",
      "last_name",
      "lastname",
      "mobile",
      "no_show",
      "phone",
      "payment_notes",
      "requested_amount",
      "seating_area",
      "sms_opt_in",
      "sms_optin",
      "source",
      "special_requests",
      "surname",
      "table_s",
      "time",
      "total_balance",
      "total_paid",
      "total_refunded",
    ],
  );
  const headerRowIndex = rows.findIndex((row) =>
    row.filter((cell) => knownHeaderKeys.has(normalizePortabilityKey(cell)))
      .length >= 2,
  );

  if (headerRowIndex < 0) {
    const firstNonEmptyRow = rows.find((row) =>
      row.some((cell) => Boolean(cell.trim())),
    );

    return { headers: firstNonEmptyRow ?? [], records: [] };
  }

  const headers = rows[headerRowIndex].map((header) => header.trim());
  const records = rows
    .slice(headerRowIndex + 1)
    .filter((row) => row.some((cell) => Boolean(cell.trim())))
    .map((values) =>
      headers.reduce(
        (record, header, index) => ({
          ...record,
          [normalizePortabilityKey(header)]: values[index]?.trim() ?? "",
        }),
        {} as Record<string, string>,
      ),
    );

  return { headers, records };
}

function readZipUint16(bytes: Uint8Array, offset: number) {
  return bytes[offset] | (bytes[offset + 1] << 8);
}

function readZipUint32(bytes: Uint8Array, offset: number) {
  return (
    bytes[offset] |
    (bytes[offset + 1] << 8) |
    (bytes[offset + 2] << 16) |
    (bytes[offset + 3] << 24)
  ) >>> 0;
}

async function inflateZipEntry(bytes: Uint8Array) {
  const buffer = new ArrayBuffer(bytes.byteLength);

  new Uint8Array(buffer).set(bytes);

  const stream = new Blob([buffer]).stream().pipeThrough(
    new DecompressionStream("deflate-raw"),
  );
  const inflatedBuffer = await new Response(stream).arrayBuffer();

  return new Uint8Array(inflatedBuffer);
}

async function readXlsxFiles(file: File) {
  const bytes = new Uint8Array(await file.arrayBuffer());
  let eocdOffset = -1;

  for (let index = bytes.length - 22; index >= 0; index -= 1) {
    if (readZipUint32(bytes, index) === 0x06054b50) {
      eocdOffset = index;
      break;
    }
  }

  if (eocdOffset < 0) {
    throw new Error("The uploaded workbook could not be read.");
  }

  const entryCount = readZipUint16(bytes, eocdOffset + 10);
  const centralDirectoryOffset = readZipUint32(bytes, eocdOffset + 16);
  const decoder = new TextDecoder();
  const files = new Map<string, string>();
  let cursor = centralDirectoryOffset;

  for (let index = 0; index < entryCount; index += 1) {
    if (readZipUint32(bytes, cursor) !== 0x02014b50) {
      break;
    }

    const compressionMethod = readZipUint16(bytes, cursor + 10);
    const compressedSize = readZipUint32(bytes, cursor + 20);
    const fileNameLength = readZipUint16(bytes, cursor + 28);
    const extraLength = readZipUint16(bytes, cursor + 30);
    const commentLength = readZipUint16(bytes, cursor + 32);
    const localHeaderOffset = readZipUint32(bytes, cursor + 42);
    const fileName = decoder.decode(
      bytes.slice(cursor + 46, cursor + 46 + fileNameLength),
    );
    const localFileNameLength = readZipUint16(bytes, localHeaderOffset + 26);
    const localExtraLength = readZipUint16(bytes, localHeaderOffset + 28);
    const dataStart =
      localHeaderOffset + 30 + localFileNameLength + localExtraLength;
    const compressed = bytes.slice(dataStart, dataStart + compressedSize);
    const contentBytes =
      compressionMethod === 0
        ? compressed
        : compressionMethod === 8
          ? await inflateZipEntry(compressed)
          : null;

    if (contentBytes) {
      files.set(fileName, decoder.decode(contentBytes));
    }

    cursor += 46 + fileNameLength + extraLength + commentLength;
  }

  return files;
}

function getXmlText(node: Element | null) {
  return node?.textContent ?? "";
}

function getXlsxColumnIndex(cellReference: string | null) {
  const columnReference = cellReference?.match(/[A-Z]+/i)?.[0] ?? "";

  if (!columnReference) {
    return -1;
  }

  return columnReference
    .toUpperCase()
    .split("")
    .reduce(
      (index, character) =>
        index * 26 + character.charCodeAt(0) - "A".charCodeAt(0) + 1,
      0,
    ) - 1;
}

async function parseXlsxTable(file: File) {
  const files = await readXlsxFiles(file);
  const workbookXml = files.get("xl/workbook.xml");
  const workbookRelsXml = files.get("xl/_rels/workbook.xml.rels");

  if (!workbookXml || !workbookRelsXml) {
    throw new Error("The uploaded workbook is missing worksheet metadata.");
  }

  const parser = new DOMParser();
  const workbook = parser.parseFromString(workbookXml, "application/xml");
  const rels = parser.parseFromString(workbookRelsXml, "application/xml");
  const firstSheet = workbook.getElementsByTagName("sheet")[0];
  const relationshipId = firstSheet?.getAttribute("r:id");
  const relationship = Array.from(
    rels.getElementsByTagName("Relationship"),
  ).find((item) => item.getAttribute("Id") === relationshipId);
  const target = relationship?.getAttribute("Target") ?? "worksheets/sheet1.xml";
  const worksheetPath = target.startsWith("/")
    ? target.slice(1)
    : target.startsWith("xl/")
      ? target
      : `xl/${target}`;
  const worksheetXml = files.get(worksheetPath);

  if (!worksheetXml) {
    throw new Error("The uploaded workbook does not contain a readable sheet.");
  }

  const sharedStringsXml = files.get("xl/sharedStrings.xml");
  const sharedStrings = sharedStringsXml
    ? Array.from(
        parser
          .parseFromString(sharedStringsXml, "application/xml")
          .getElementsByTagName("si"),
      ).map((item) =>
        Array.from(item.getElementsByTagName("t"))
          .map((textNode) => textNode.textContent ?? "")
          .join(""),
      )
    : [];
  const worksheet = parser.parseFromString(worksheetXml, "application/xml");

  return Array.from(worksheet.getElementsByTagName("row")).map((row) => {
    const cells = Array.from(row.getElementsByTagName("c"));
    const values: string[] = [];

    cells.forEach((cell, fallbackIndex) => {
      const type = cell.getAttribute("t");
      const columnIndex = getXlsxColumnIndex(cell.getAttribute("r"));
      const resolvedIndex = columnIndex >= 0 ? columnIndex : fallbackIndex;
      let cellValue = "";

      if (type === "inlineStr") {
        cellValue = getXmlText(cell.getElementsByTagName("t")[0]).trim();
      } else {
        const value = getXmlText(cell.getElementsByTagName("v")[0]).trim();

        cellValue = type === "s" ? sharedStrings[Number(value)] ?? "" : value;
      }

      values[resolvedIndex] = cellValue;
    });

    return values.map((value) => value ?? "");
  });
}

async function parsePortabilityFile(
  file: File,
  entity: DataPortabilityEntity,
  sourceLocation: DataPortabilitySourceLocation,
) {
  const fileName = file.name.toLowerCase();

  if (fileName.endsWith(".csv") || fileName.endsWith(".txt")) {
    return normalizePortabilityParsedTable(
      parsePortabilityTable(parseCsvTable(await file.text())),
      entity,
      sourceLocation,
    );
  }

  if (fileName.endsWith(".xlsx")) {
    return normalizePortabilityParsedTable(
      parsePortabilityTable(await parseXlsxTable(file)),
      entity,
      sourceLocation,
    );
  }

  throw new Error("Upload a CSV or XLSX file.");
}

async function parseDineplanGuestListFile(file: File) {
  const fileName = file.name.toLowerCase();
  let parsed: { headers: string[]; records: Record<string, string>[] };

  if (fileName.endsWith(".csv") || fileName.endsWith(".txt")) {
    parsed = parsePortabilityTable(parseCsvTable(await file.text()));
  } else if (fileName.endsWith(".xlsx")) {
    parsed = parsePortabilityTable(await parseXlsxTable(file));
  } else {
    throw new Error("Upload a Dineplan Guest List CSV or XLSX file.");
  }

  return parseDineplanGuestList(parsed);
}

function isValidPortabilityEmail(value: string) {
  return !value || /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
}

function isValidPortabilityPhone(value: string) {
  return !value || /^[0-9+()\s.-]{7,}$/.test(value.trim());
}

function isValidPortabilityDate(value: string) {
  return !value || !Number.isNaN(new Date(value).getTime());
}

function isValidPortabilityNumber(value: string) {
  return !value || Number.isFinite(Number(value.replaceAll(",", "")));
}

function isLikelyBookingReference(value: string) {
  return /^[A-Z0-9][A-Z0-9-]{3,}$/i.test(value.trim());
}

function getImportTableSortValue(value: string) {
  return value.replace(/\d+/g, (match) => match.padStart(6, "0"));
}

function formatPercent(value: number) {
  return `${Math.round(value)}%`;
}

function getBarWidth(value: number, maxValue: number) {
  if (maxValue <= 0) {
    return 0;
  }

  return Math.max(4, Math.round((value / maxValue) * 100));
}

function getCustomerKey(customer: {
  email?: string;
  name?: string;
  phone?: string;
}) {
  const email = customer.email?.trim().toLowerCase();
  const phone = customer.phone?.replace(/\D/g, "");
  const name = customer.name?.trim().toLowerCase();

  return email || phone || name || "unknown-customer";
}

function normalizeCustomerValue(value?: string | null) {
  return (value ?? "").trim().toLowerCase();
}

function normalizeCustomerPhone(value?: string | null) {
  return (value ?? "").replace(/\D/g, "");
}

function getLiveCustomerName(customer: LiveCustomerRecord) {
  return [customer.first_name, customer.surname]
    .filter(Boolean)
    .join(" ")
    .trim();
}

function getLiveCustomerKey(customer: LiveCustomerRecord) {
  const preferencesKey = normalizeCustomerValue(
    customer.preferences?.customerKey,
  );

  return (
    preferencesKey ||
    normalizeCustomerValue(customer.email) ||
    normalizeCustomerPhone(customer.mobile) ||
    normalizeCustomerValue(getLiveCustomerName(customer)) ||
    customer.id
  );
}

function getCustomerProfileSelectionId(profile: CustomerProfile) {
  return profile.customerId
    ? `customer:${profile.customerId}`
    : `snapshot:${profile.key}`;
}

type LiveCustomerResolutionInput = {
  customer: {
    email?: string;
    key?: string;
    phone?: string;
  };
  records?: LiveCustomerRecord[];
};

function resolveLiveCustomer(input: LiveCustomerResolutionInput) {
  const email = normalizeCustomerValue(input.customer.email);
  const phone = normalizeCustomerPhone(input.customer.phone);
  const key = input.customer.key;
  const records = input.records ?? [];
  const normalizedKey = normalizeCustomerValue(key);

  const deterministicCustomer = normalizedKey
    ? records.find(
        (record) =>
          normalizeCustomerValue(record.preferences?.customerKey) ===
          normalizedKey,
      )
    : undefined;

  const keyEmailMatch = deterministicCustomer
    ? undefined
    : normalizedKey && normalizedKey.includes("@")
      ? records.find(
          (record) =>
            normalizeCustomerValue(record.email) === normalizedKey,
        )
      : undefined;

  const keyPhoneMatch = deterministicCustomer || keyEmailMatch ? undefined : key
    ? records.find((record) => normalizeCustomerPhone(record.mobile) === normalizeCustomerPhone(key))
    : undefined;

  if (deterministicCustomer) {
    return deterministicCustomer;
  }

  if (keyEmailMatch) {
    return keyEmailMatch;
  }

  if (keyPhoneMatch) {
    return keyPhoneMatch;
  }

  const emailMatches = email
    ? records.filter(
        (record) => normalizeCustomerValue(record.email) === email,
      )
    : [];

  if (emailMatches.length === 1) {
    return emailMatches[0];
  }

  const phoneMatches = phone
    ? records.filter(
        (record) => normalizeCustomerPhone(record.mobile) === phone,
      )
    : [];

  if (phoneMatches.length === 1) {
    return phoneMatches[0];
  }

  return null;
}

function isLiveCustomerArchived(customer: LiveCustomerRecord | null | undefined) {
  return Boolean(customer?.preferences?.archivedAt);
}

async function loadLiveCustomerRecords() {
  const response = await fetch("/api/admin/customers", {
    cache: "no-store",
  });

  if (!response.ok) {
    throw new Error(`Customer records request failed (${response.status}).`);
  }

  const payload = (await response.json()) as {
    rows?: LiveCustomerRecord[];
  };

  return payload.rows ?? [];
}

function getStoredNotificationPreferences() {
  if (typeof window === "undefined") {
    return {} as Partial<Record<NotificationPreferenceKey, boolean>>;
  }

  try {
    const storedPreferences = window.localStorage.getItem(
      notificationPreferenceStorageKey,
    );

    return storedPreferences
      ? (JSON.parse(storedPreferences) as Partial<Record<
          NotificationPreferenceKey,
          boolean
        >>)
      : ({} as Partial<Record<NotificationPreferenceKey, boolean>>);
  } catch {
    return {} as Partial<Record<NotificationPreferenceKey, boolean>>;
  }
}

function storeNotificationPreferences(
  preferences: Partial<Record<NotificationPreferenceKey, boolean>>,
) {
  try {
    window.localStorage.setItem(
      notificationPreferenceStorageKey,
      JSON.stringify(preferences),
    );
  } catch {
    // Some private browsing contexts block local storage.
  }
}

function getPushOnboardingDismissed() {
  if (typeof window === "undefined") {
    return false;
  }

  return window.sessionStorage.getItem(pushOnboardingDismissedStorageKey) === "true";
}

function storePushOnboardingDismissed() {
  try {
    window.sessionStorage.setItem(pushOnboardingDismissedStorageKey, "true");
  } catch {
    // Some private browsing contexts block session storage.
  }
}

function getPlatformTicketUrl(reference: string) {
  const ticketUrl = getTicketUrl(reference);

  if (typeof window === "undefined") {
    return ticketUrl;
  }

  const returnTo = `/admin?booking=${encodeURIComponent(reference)}`;
  const contextualTicketUrl = new URL(ticketUrl, window.location.origin);

  contextualTicketUrl.searchParams.set("returnTo", returnTo);

  return `${contextualTicketUrl.pathname}${contextualTicketUrl.search}`;
}

function getBookingFinancials(booking: DemoBooking) {
  const totalPrice = booking.totalPrice;
  const addonsTotal = booking.addonsTotal ?? 0;
  const subtotalPrice = booking.subtotalPrice ?? booking.totalPrice;
  const ticketBreakdown = getIncludedBookingFeeBreakdown(
    Math.max(subtotalPrice - addonsTotal, 0),
  );
  const depositPercentage = booking.depositPercentage ?? 100;
  const depositAmount = Math.ceil(
    totalPrice * (depositPercentage / 100),
  );
  const paymentStatus = getBookingPaymentStatus(booking);
  const amountPaid =
    booking.amountPaid ??
    (paymentStatus === "fully-paid"
      ? totalPrice
      : paymentStatus === "deposit-paid"
        ? depositAmount
        : 0);
  const balanceDue =
    paymentStatus === "comp-vip" || paymentStatus === "refunded"
      ? 0
      : booking.balanceDue ?? Math.max(totalPrice - amountPaid, 0);

  return {
    addonsTotal,
    amountPaid,
    balanceDue,
    bookingFeeAmount: ticketBreakdown.bookingFee,
    depositAmount,
    discountAmount: booking.discountAmount ?? 0,
    paymentOption: booking.paymentOption ?? "full",
    paymentStatus,
    serviceFeeAmount: booking.serviceFeeAmount ?? 0,
    subtotalPrice,
    ticketAmount: ticketBreakdown.ticketAmount,
    totalPrice,
  };
}

function getBookingPaymentStatus(
  booking: Pick<
    DemoBooking,
    | "amountPaid"
    | "balanceDue"
    | "paymentStatus"
    | "status"
    | "totalPrice"
  >,
): PaymentStatus {
  if (booking.paymentStatus) {
    return booking.paymentStatus;
  }

  if ((booking.status ?? "confirmed") === "cancelled") {
    return "pending-payment";
  }

  if ((booking.amountPaid ?? 0) >= booking.totalPrice) {
    return "fully-paid";
  }

  if ((booking.amountPaid ?? 0) > 0) {
    return "deposit-paid";
  }

  if ((booking.balanceDue ?? 0) > 0) {
    return "pending-payment";
  }

  return "fully-paid";
}

async function getSupabaseAdminSession() {
  const authSession = await getAdminAuthSession();

  if (!authSession?.user.email) {
    return null;
  }

  return getOrCreateStaffProfileSession(authSession.user);
}

