  async function hydrateBookingHistories() {
    const requestId = bookingHistoryLoadRequestRef.current + 1;
    bookingHistoryLoadRequestRef.current = requestId;

    try {
      const historiesByReference = await getBookingHistories();

      if (requestId !== bookingHistoryLoadRequestRef.current) {
        return;
      }

      setBookings((currentBookings) =>
        currentBookings.map((booking) => {
          const histories = historiesByReference.get(booking.reference);

          if (!histories) {
            return booking;
          }

          return {
            ...booking,
            communicationHistory: [
              ...histories.communicationHistory,
              ...(booking.communicationHistory ?? []).filter(
                (record) =>
                  !histories.communicationHistory.some(
                    (historyRecord) => historyRecord.id === record.id,
                  ),
              ),
            ].sort(
              (left, right) =>
                new Date(right.sentAt).getTime() -
                new Date(left.sentAt).getTime(),
            ),
            lifecycleHistory: [
              ...histories.lifecycleHistory,
              ...(booking.lifecycleHistory ?? []).filter(
                (event) =>
                  !histories.lifecycleHistory.some(
                    (historyEvent) => historyEvent.id === event.id,
                  ),
              ),
            ].sort(
              (left, right) =>
                new Date(right.createdAt).getTime() -
                new Date(left.createdAt).getTime(),
            ),
          };
        }),
      );
    } catch (error) {
      console.error(
        "[Zingara admin] Failed to hydrate booking histories",
        error,
      );
    }
  }

  async function loadBookingList() {
    const requestId = bookingLoadRequestRef.current + 1;
    bookingLoadRequestRef.current = requestId;
    setIsBookingsLoading(true);
    setBookingLoadError("");

    try {
      const nextBookings = await getBookings({
        includeHistory: false,
        throwOnError: true,
      });

      if (requestId !== bookingLoadRequestRef.current) {
        return nextBookings;
      }

      setBookings(nextBookings);
      void hydrateBookingHistories();
      return nextBookings;
    } catch (error) {
      console.error("[Zingara admin] Failed to load bookings", error);

      if (requestId === bookingLoadRequestRef.current) {
        setBookingLoadError("Bookings could not be loaded. Try again.");
      }

      return null;
    } finally {
      if (requestId === bookingLoadRequestRef.current) {
        setIsBookingsLoading(false);
      }
    }
  }

  async function openBookingDetails(reference: string) {
    if (bookingDetailLoadingReference === reference) {
      return;
    }

    setBookingDetailLoadingReference(reference);
    setBookingDetailError(null);

    try {
      const detailedBooking = await getBooking(reference);

      if (!detailedBooking) {
        throw new Error("Booking details were not returned.");
      }

      setBookings((currentBookings) =>
        currentBookings.map((booking) =>
          booking.reference === reference ? detailedBooking : booking,
        ),
      );
      setExpandedBookingReference(reference);
    } catch (error) {
      console.error("[Zingara admin] Failed to load booking details", error);
      setBookingDetailError({
        message: "Booking details could not be loaded. Try again.",
        reference,
      });
    } finally {
      setBookingDetailLoadingReference("");
    }
  }

  async function refreshLiveCustomerRecords() {
    const requestId = liveCustomerLoadRequestRef.current + 1;
    liveCustomerLoadRequestRef.current = requestId;
    setCustomerDataLoadStatus("loading");
    setCustomerDataLoadError("");

    try {
      const records = await loadLiveCustomerRecords();

      if (requestId !== liveCustomerLoadRequestRef.current) {
        return records;
      }

      setLiveCustomerRecords(records);
      setCustomerCrmRecords(getCustomerCrmRecordsFromRows(records));
      setCustomerDataLoadStatus("loaded");
      return records;
    } catch (error) {
      console.error("[Zingara admin] Failed to load customer records", error);

      if (requestId !== liveCustomerLoadRequestRef.current) {
        return null;
      }

      setCustomerDataLoadError(
        "Customer records could not be loaded. Try again.",
      );
      setCustomerDataLoadStatus("error");
      return null;
    }
  }

  useEffect(() => {
    let isMounted = true;
    let activeAdminSession: AdminSession | null = null;

    async function loadAdminData(options: { sessionValidated?: boolean } = {}) {
      if (!activeAdminSession) {
        return;
      }

      setIsShowsLoading(true);
      setShowLoadError("");
      const showLoadRequestId = showLoadRequestRef.current + 1;
      showLoadRequestRef.current = showLoadRequestId;

      if (!options.sessionValidated) {
        const nextAdminSession = await getSupabaseAdminSession();

        if (!isMounted) {
          return;
        }

        activeAdminSession = nextAdminSession;
        setCurrentStaff(nextAdminSession);

        if (!nextAdminSession) {
          setIsShowsLoading(false);
          return;
        }
      }

      const customerRecordsRequest = refreshLiveCustomerRecords();
      const bookingsRequest = loadBookingList();

      try {
        const [
          nextShowPayload,
          nextCorporateRequests,
          nextCommunicationTemplates,
          nextVenueSettings,
          nextWaitlist,
          nextStaffProfiles,
          nextStaffRoles,
          nextPaymentRows,
        ] = await Promise.all([
          getShowsWithTables({
            tableLocation: showCalendarLocationFilterRef.current,
            tableMonth: showCalendarMonthRef.current,
          }),
          getCorporateRequests(),
          getTemplates(),
          getVenueSettings(),
          getWaitlistEntries(),
          getStaffProfiles(),
          getAvailableRoles(),
          getPayments(),
        ]);
        await customerRecordsRequest;
        const nextBookings = (await bookingsRequest) ?? [];
        const nextShows = nextShowPayload.shows;
        const nextTables =
          nextShowPayload.tablesLoaded
            ? applyBookingOccupancyToTables(nextShowPayload.tables, nextBookings)
            : getStoredDemoTables(nextShows);

        console.log("[Zingara show management] show reloaded", {
          showCount: nextShows.length,
          shows: nextShows.map((show) => ({
            date: show.date,
            id: show.id,
            label: show.label,
            status: show.operationalStatus ?? "active",
            time: getSouthAfricaShowTime(show),
          })),
        });
        console.log("[Zingara admin] dashboard show source", {
          shows: nextShows.map((show) => ({
            date: show.date,
            id: show.id,
            label: show.label,
            status: show.operationalStatus ?? "active",
            time: getSouthAfricaShowTime(show),
          })),
        });

        if (!isMounted) {
          return;
        }

        const isLatestShowLoad =
          showLoadRequestId === showLoadRequestRef.current;

        if (isLatestShowLoad && nextShowPayload.showsLoaded) {
          const nextRelevantShow = getNextRelevantOperationalShow(nextShows);

          setShows(nextShows);
          setSelectedShowId((currentShowId) =>
            nextShows.some((show) => show.id === currentShowId)
              ? currentShowId
              : nextRelevantShow?.id ?? nextShows[0]?.id ?? "",
          );
          setWorkflowShowId((currentShowId) =>
            nextShows.some((show) => show.id === currentShowId)
              ? currentShowId
              : nextRelevantShow?.id ?? nextShows[0]?.id ?? "",
          );
          setTables(nextTables);
          setShowLoadError("");
        } else if (isLatestShowLoad) {
          setShowLoadError("Shows could not be loaded. Try again.");
        }
        setCorporateRequests(nextCorporateRequests);
        setCommunicationTemplates(nextCommunicationTemplates);
        setVenueSettings(nextVenueSettings);
        setWaitlist(nextWaitlist);
        setStaffProfiles(nextStaffProfiles);
        setStaffRoles(nextStaffRoles);
        setPaymentRows(nextPaymentRows);
      } catch (error) {
        console.error("[Zingara admin] Failed to load dashboard data", error);
        if (showLoadRequestId === showLoadRequestRef.current) {
          setShowLoadError("Shows could not be loaded. Try again.");
        }
      } finally {
        if (
          isMounted &&
          showLoadRequestId === showLoadRequestRef.current
        ) {
          setIsShowsLoading(false);
        }
      }
    }

    async function restoreAdminSession() {
      const requestId = sessionRestoreRequestRef.current + 1;
      sessionRestoreRequestRef.current = requestId;
      setIsSessionRestoring(true);

      try {
        const nextAdminSession = await getSupabaseAdminSession();

        if (
          !isMounted ||
          requestId !== sessionRestoreRequestRef.current
        ) {
          return;
        }

        activeAdminSession = nextAdminSession;
        setCurrentStaff(nextAdminSession);

        if (nextAdminSession) {
          void loadAdminData({ sessionValidated: true });
        } else {
          liveCustomerLoadRequestRef.current += 1;
          setLiveCustomerRecords([]);
          setCustomerDataLoadStatus("idle");
          setCustomerDataLoadError("");
        }
      } catch (error) {
        console.error("[Zingara admin] Failed to restore staff session", error);

        if (
          isMounted &&
          requestId === sessionRestoreRequestRef.current
        ) {
          activeAdminSession = null;
          setCurrentStaff(null);
        }
      } finally {
        if (
          isMounted &&
          requestId === sessionRestoreRequestRef.current
        ) {
          setHasHydrated(true);
          setIsSessionRestoring(false);
        }
      }
    }

    function reloadAdminData() {
      void loadAdminData();
    }

    function reloadAdminSession(event?: Event) {
      const validatedSession =
        event instanceof CustomEvent
          ? (event.detail as { session?: AdminSession } | null)?.session
          : undefined;

      if (validatedSession) {
        sessionRestoreRequestRef.current += 1;
        activeAdminSession = validatedSession;
        setCurrentStaff(validatedSession);
        setHasHydrated(true);
        setIsSessionRestoring(false);
        void loadAdminData({ sessionValidated: true });
        return;
      }

      void restoreAdminSession();
    }

    const hydrationTimer = window.setTimeout(restoreAdminSession, 0);

    window.addEventListener("storage", reloadAdminSession);
    window.addEventListener(
      "zingara-demo-bookings-updated",
      reloadAdminData,
    );
    window.addEventListener(
      "zingara-demo-corporate-requests-updated",
      reloadAdminData,
    );
    window.addEventListener(adminAuthChangedEvent, reloadAdminSession);
    window.addEventListener(
      "zingara-demo-shows-updated",
      reloadAdminData,
    );
    window.addEventListener(
      "zingara-demo-tables-updated",
      reloadAdminData,
    );
    window.addEventListener(
      "zingara-demo-waitlist-updated",
      reloadAdminData,
    );
    window.addEventListener(
      "zingara-demo-customer-crm-updated",
      reloadAdminData,
    );
    window.addEventListener(
      "zingara-demo-communication-templates-updated",
      reloadAdminData,
    );
    window.addEventListener(
      "zingara-demo-venue-settings-updated",
      reloadAdminData,
    );

    return () => {
      isMounted = false;
      window.removeEventListener("storage", reloadAdminSession);
      window.removeEventListener(
        "zingara-demo-bookings-updated",
        reloadAdminData,
      );
      window.removeEventListener(
        "zingara-demo-corporate-requests-updated",
        reloadAdminData,
      );
      window.removeEventListener(adminAuthChangedEvent, reloadAdminSession);
      window.removeEventListener(
        "zingara-demo-shows-updated",
        reloadAdminData,
      );
      window.removeEventListener(
        "zingara-demo-tables-updated",
        reloadAdminData,
      );
      window.removeEventListener(
        "zingara-demo-waitlist-updated",
        reloadAdminData,
      );
      window.removeEventListener(
        "zingara-demo-customer-crm-updated",
        reloadAdminData,
      );
      window.removeEventListener(
        "zingara-demo-communication-templates-updated",
        reloadAdminData,
      );
      window.removeEventListener(
        "zingara-demo-venue-settings-updated",
        reloadAdminData,
      );
      window.clearTimeout(hydrationTimer);
    };
  }, []);

  useEffect(() => {
    if (!currentStaff) {
      return;
    }

    function handleAdminDeepLink(rawUrl = window.location.href) {
      const url = new URL(rawUrl, window.location.origin);
      const bookingReference = url.searchParams.get("booking")?.trim();
      const waitlistId = url.searchParams.get("waitlist")?.trim();
      const corporateRequestId = url.searchParams.get("corporate")?.trim();
      const section = url.searchParams.get("section")?.trim();
      const deepLinkKey = `${bookingReference ?? ""}|${waitlistId ?? ""}|${corporateRequestId ?? ""}|${section ?? ""}`;

      if (!deepLinkKey.replaceAll("|", "")) {
        return;
      }

      if (handledAdminDeepLinkRef.current === deepLinkKey) {
        return;
      }

      if (bookingReference) {
        setActiveAdminTab("bookings");
        setBookingSearch(bookingReference);
        setBookingPage(1);
      } else if (waitlistId) {
        const linkedWaitlistEntry = waitlist.find(
          (entry) => entry.id === waitlistId,
        );

        if (!linkedWaitlistEntry && waitlist.length === 0) {
          return;
        }

        setActiveAdminTab("operations");
        setActiveOperationsTab("waitlist");
        setWaitlistSearch(waitlistId);

        if (linkedWaitlistEntry) {
          setSelectedShowId(linkedWaitlistEntry.showId);
        }
      } else if (corporateRequestId) {
        setActiveAdminTab("corporate");
        setOpenCorporateRequestId(corporateRequestId);
      } else if (section === "bookings") {
        setActiveAdminTab("bookings");
      } else if (section === "waitlist") {
        setActiveAdminTab("operations");
        setActiveOperationsTab("waitlist");
      } else if (section === "corporate") {
        setActiveAdminTab("corporate");
      } else if (section === "platform-operations") {
        setActiveAdminTab("platform-operations");
      }

      handledAdminDeepLinkRef.current = deepLinkKey;
    }

    handleAdminDeepLink();

    function handleServiceWorkerMessage(event: MessageEvent) {
      if (event.data?.type !== "ZINGARA_NOTIFICATION_NAVIGATE") {
        return;
      }

      const targetUrl =
        typeof event.data.url === "string" ? event.data.url : "/admin";
      const url = new URL(targetUrl, window.location.origin);

      handleAdminDeepLink(targetUrl);

      if (
        url.origin === window.location.origin &&
        `${url.pathname}${url.search}` !==
          `${window.location.pathname}${window.location.search}`
      ) {
        window.history.pushState(null, "", `${url.pathname}${url.search}`);
      }
    }

    navigator.serviceWorker?.addEventListener(
      "message",
      handleServiceWorkerMessage,
    );

    return () => {
      navigator.serviceWorker?.removeEventListener(
        "message",
        handleServiceWorkerMessage,
      );
    };
  }, [currentStaff, waitlist]);

