  async function runPlatformTelemetryCleanup() {
    if (!isSuperAdmin) {
      return;
    }

    setPlatformOperationsCleanupStatus("Running retention cleanup...");

    try {
      const result = await fetchSupabaseApi<{
        cleanup: Record<string, number>;
      }>("/api/admin/platform-operations", {
        body: { action: "cleanup" },
        method: "POST",
      });
      const deletedTotal = Object.values(result.cleanup).reduce(
        (total, value) => total + value,
        0,
      );

      setPlatformOperationsCleanupStatus(
        `Retention cleanup complete · ${deletedTotal} expired telemetry rows removed.`,
      );
      await refreshPlatformOperations();
    } catch (error) {
      console.error("[Zingara admin] Telemetry retention cleanup failed", error);
      setPlatformOperationsCleanupStatus(
        "Retention cleanup could not be completed.",
      );
    }
  }

  async function queryPayFastRefundAvailabilityQa() {
    if (!isSuperAdmin || isPayFastRefundQaQuerying) {
      return;
    }

    const confirmed = window.confirm(
      "Query PayFast refund status for PH396M-R50QA? This cannot submit another refund and will reconcile locally only if PayFast confirms completion.",
    );

    if (!confirmed) {
      return;
    }

    setIsPayFastRefundQaQuerying(true);
    setPayFastRefundQaStatus("Querying PayFast refund status...");

    try {
      const result = await fetchSupabaseApi<PayFastRefundAvailabilityQaResult>(
        "/api/admin/qa/payfast-refund-availability",
      );
      const summary = [
        result.querySucceeded ? "Query succeeded" : "Query failed",
        `Completed: ${result.completed ? "Yes" : "No"}`,
        `Refundable: ${result.refundable ? "Yes" : "No"}`,
        `Provider state: ${result.providerState}`,
        result.message,
      ];

      setPayFastRefundQaStatus(summary.join(" · "));
    } catch (error) {
      setPayFastRefundQaStatus(
        error instanceof Error
          ? error.message
          : "PayFast refund status could not be confirmed.",
      );
    } finally {
      setIsPayFastRefundQaQuerying(false);
    }
  }

