  function updateCommunicationTemplate(
    templateId: string,
    updates: Partial<
      Pick<CommunicationTemplate, "body" | "channel" | "subject">
    >,
  ) {
    if (!canManageCommunications) {
      return;
    }

    const nextTemplates = communicationTemplates.map((template) =>
      template.id === templateId
        ? {
            ...template,
            ...updates,
            updatedAt: new Date().toISOString(),
          }
        : template,
    );

    saveCommunicationTemplates(nextTemplates);
    setWorkflowStatus("Template saved successfully.");
  }

  function createShow() {
    const showLocation = normalizeShowLocation(newShow.location);

    if (!canManageShows || !newShow.date || !newShow.time || !showLocation) {
      return;
    }

    const showId = `show-${newShow.date}-${newShow.time.replace(":", "")}`;

    if (shows.some((show) => show.id === showId)) {
      setSelectedShowId(showId);
      return;
    }

    const show: DemoShow = {
      id: showId,
      address: newShow.address.trim(),
      date: newShow.date,
      time: newShow.time,
      label: newShow.label.trim() || "Zingara Show",
      location: showLocation,
      operationalStatus: "active",
      venueName: showLocation,
    };

    saveShows([...shows, show]);
    saveTables([...tables, ...createTablesForShow(show.id)]);
    setSelectedShowId(show.id);
    setNewShow({
      address: "",
      date: "",
      time: "",
      label: "",
      location: "",
    });
  }

  async function createTable(zoneId: SeatingZoneId) {
    const newTable = newTables[zoneId];
    const tableNumber = newTable.tableNumber.trim();

    if (
      !canManageTables ||
      !selectedShowId ||
      !tableNumber ||
      newTable.seatCapacity < 1 ||
      operationalTableAction
    ) {
      return;
    }

    setOperationalTableAction(`create-${zoneId}`);

    try {
      await createOperationalShowTable({
        capacity: newTable.seatCapacity,
        showReference: selectedShowId,
        tableCode: tableNumber,
        zoneId,
      });
      await refreshAssignedShowState(selectedShowId);
      setNewTables((currentForms) => ({
        ...currentForms,
        [zoneId]: {
          tableNumber: "",
          seatCapacity: 2,
        },
      }));
      showWorkflowToast(
        `${tableNumber} was added as a temporary operational table for this performance.`,
      );
    } catch (error) {
      showWorkflowToast(
        error instanceof Error
          ? error.message
          : "The temporary operational table could not be added.",
      );
    } finally {
      setOperationalTableAction("");
    }
  }

  async function savePhysicalTableCapacity(table: DemoTable) {
    const authoritativeId = table.authoritativeId;
    const definition = getPhysicalTableDefinition(
      table.zoneId,
      table.tableNumber,
    );
    const capacity = Math.trunc(
      Number(physicalCapacityDrafts[table.id] ?? table.seatCapacity),
    );

    if (
      !canManageTables ||
      !selectedShowId ||
      !authoritativeId ||
      !definition ||
      operationalTableAction
    ) {
      return;
    }

    setOperationalTableAction(`capacity-${table.id}`);

    try {
      await setPhysicalShowTableCapacity({
        capacity,
        showReference: selectedShowId,
        tableId: authoritativeId,
        zoneId: table.zoneId,
      });
      await refreshAssignedShowState(selectedShowId);
      setPhysicalCapacityDrafts((currentDrafts) => {
        const nextDrafts = { ...currentDrafts };
        delete nextDrafts[table.id];
        return nextDrafts;
      });
      showWorkflowToast(
        `Table ${table.tableNumber} was configured for ${capacity} seats.`,
      );
    } catch (error) {
      showWorkflowToast(
        error instanceof Error
          ? error.message
          : "The physical table capacity could not be saved.",
      );
    } finally {
      setOperationalTableAction("");
    }
  }

  async function saveOperationalTableChanges(
    table: DemoTable,
    updates: Partial<Pick<DemoTable, "status">> = {},
  ) {
    const currentTable = tables.find(
      (candidate) => candidate.id === table.id,
    );
    const authoritativeId = currentTable?.authoritativeId;

    if (
      !canManageTables ||
      !selectedShowId ||
      !currentTable ||
      !authoritativeId ||
      operationalTableAction
    ) {
      return;
    }

    const nextTable = { ...currentTable, ...updates };
    setOperationalTableAction(`update-${table.id}`);

    try {
      await updateOperationalShowTable({
        capacity: nextTable.seatCapacity,
        notes: nextTable.guestNotes,
        showReference: selectedShowId,
        status: nextTable.status,
        tableCode: nextTable.tableNumber,
        tableId: authoritativeId,
        zoneId: nextTable.zoneId,
      });
      await refreshAssignedShowState(selectedShowId);
      showWorkflowToast(
        `Table ${nextTable.tableNumber} changes were saved for this performance.`,
      );
    } catch (error) {
      await refreshAssignedShowState(selectedShowId).catch(() => undefined);
      showWorkflowToast(
        error instanceof Error
          ? error.message
          : "The operational table changes could not be saved.",
      );
    } finally {
      setOperationalTableAction("");
    }
  }

  async function reallocateBookingToPhysicalTable(
    booking: DemoBooking,
    targetTableId: string,
    targetTableNumber: string,
  ) {
    if (!canManageBookings) {
      showWorkflowToast("Booking management access is required.");
      return false;
    }

    if (!booking.showId) {
      showWorkflowToast("This booking does not have a resolved performance.");
      return false;
    }

    if (!targetTableId) {
      showWorkflowToast("The selected operational table could not be resolved.");
      return false;
    }

    if (floorAssignmentInFlightRef.current.has(booking.reference)) {
      showWorkflowToast("This table assignment is already being saved.");
      return false;
    }

    floorAssignmentInFlightRef.current.add(booking.reference);

    try {
      await mapBookingPhysicalTable({
        bookingReference: booking.reference,
        targetTableId,
      });
      await refreshAssignedShowState(booking.showId);
      setPhysicalMappingSelections((currentSelections) => {
        const nextSelections = { ...currentSelections };
        delete nextSelections[booking.reference];
        return nextSelections;
      });
      showWorkflowToast(
        `${booking.reference} now uses table ${targetTableNumber}.`,
      );
      return true;
    } catch (error) {
      await refreshAssignedShowState(booking.showId).catch(() => undefined);
      showWorkflowToast(
        error instanceof Error
          ? error.message
          : "The table assignment could not be saved.",
      );
      return false;
    } finally {
      floorAssignmentInFlightRef.current.delete(booking.reference);
    }
  }

  function updateTable(
    tableId: string,
    updates: Partial<DemoTable>,
  ) {
    if (!canManageTables) {
      return;
    }

    saveTables(
      tables.map((table) =>
        table.id === tableId
          ? {
              ...table,
              ...updates,
              seatCapacity: Math.max(
                1,
                updates.seatCapacity ?? table.seatCapacity,
              ),
            }
          : table,
      ),
    );
  }

  function updateTableShowOverride(
    tableId: string,
    updates: Partial<NonNullable<DemoTable["showOverride"]>>,
  ) {
    if (!canManageTables) {
      return;
    }

    saveTables(
      tables.map((table) => {
        if (table.id !== tableId) {
          return table;
        }

        const baseSeatCapacity =
          table.baseSeatCapacity ?? table.seatCapacity;
        const baseStatus = table.baseStatus ?? table.status;
        const baseGuestNotes = table.baseGuestNotes ?? table.guestNotes;
        const baseMergeable = table.baseMergeable ?? table.mergeable ?? true;
        const nextOverride = {
          ...(table.showOverride ?? {}),
          ...updates,
          updatedAt: new Date().toISOString(),
        };

        return {
          ...table,
          baseSeatCapacity,
          baseStatus,
          baseGuestNotes,
          baseMergeable,
          seatCapacity: Math.max(
            1,
            nextOverride.seatCapacity ?? table.seatCapacity,
          ),
          status: nextOverride.status ?? table.status,
          guestNotes:
            nextOverride.operationalNotes ?? table.guestNotes,
          mergeable: nextOverride.mergeable ?? table.mergeable ?? true,
          showOverride: nextOverride,
        };
      }),
    );
  }

  function toggleDisabled(table: DemoTable) {
    void saveOperationalTableChanges(table, {
      status:
        table.status === "disabled" ? "available" : "disabled",
    });
  }

  async function mergeTable(
    zoneId: SeatingZoneId,
    primaryTable: DemoTable,
  ) {
    if (!canManageTables || operationalTableAction) {
      return;
    }

    const selectedTableIds = mergeSelections[primaryTable.id] ?? [];
    const selectedTables = selectedTableIds
      .map((tableId) => tables.find((table) => table.id === tableId))
      .filter((table): table is DemoTable => Boolean(table));
    const isExistingMergedUnit = Boolean(primaryTable.mergedFrom?.length);

    if (
      !selectedTables.length ||
      !selectedShowId ||
      !primaryTable.authoritativeId ||
      primaryTable.showId !== selectedShowId ||
      primaryTable.zoneId !== zoneId ||
      primaryTable.mergeable === false ||
      primaryTable.mergedInto ||
      (!isExistingMergedUnit &&
        (primaryTable.physicalTable !== true ||
          primaryTable.capacityConfigured === false ||
          primaryTable.status !== "available" ||
          primaryTable.bookingReference)) ||
      selectedTables.some(
        (table) =>
          table.showId !== selectedShowId ||
          table.zoneId !== zoneId ||
          table.physicalTable !== true ||
          table.capacityConfigured === false ||
          table.status !== "available" ||
          table.bookingReference ||
          table.mergeable === false ||
          table.mergedInto ||
          table.mergedFrom?.length ||
          !table.authoritativeId,
      )
    ) {
      return;
    }

    const sourceTableIds = selectedTables.map(
      (table) => table.authoritativeId as string,
    );

    if (!isExistingMergedUnit) {
      sourceTableIds.unshift(primaryTable.authoritativeId);
    }

    setOperationalTableAction(`merge-${primaryTable.id}`);

    try {
      await mergeOperationalShowTables({
        ...(isExistingMergedUnit
          ? { mergedTableId: primaryTable.authoritativeId }
          : {}),
        showReference: selectedShowId,
        sourceTableIds,
        zoneId,
      });
      await refreshAssignedShowState(selectedShowId);
      setMergeSelections((currentSelections) => ({
        ...currentSelections,
        [primaryTable.id]: [],
      }));
      const selectedCodes = selectedTables.map((table) => table.tableNumber);
      showWorkflowToast(
        isExistingMergedUnit
          ? `${selectedCodes.join(", ")} added to ${primaryTable.tableNumber}.`
          : `${[primaryTable.tableNumber, ...selectedCodes].join(" + ")} merged for this performance.`,
      );
    } catch (error) {
      showWorkflowToast(
        error instanceof Error
          ? error.message
          : "The operational tables could not be merged.",
      );
    } finally {
      setOperationalTableAction("");
    }
  }

  function getSplitMergeReview(
    mergedTable: DemoTable,
  ): SplitMergeReview {
    const booking = bookings.find(
      (currentBooking) =>
        (currentBooking.tableId === mergedTable.id ||
          currentBooking.reference === mergedTable.bookingReference) &&
        isOperationallyActiveBooking(currentBooking),
    );
    const sourceTables = tables.filter((table) =>
      mergedTable.mergedFrom?.includes(table.id),
    );
    const sourceSummary = sourceTables
      .map((table) => `${table.tableNumber} (${table.seatCapacity})`)
      .join(", ");

    if (booking) {
      return {
        booking,
        table: mergedTable,
        warning: `${booking.customer.name || "This booking"} is assigned to ${mergedTable.tableNumber}. Reallocate the booking before restoring ${sourceSummary}.`,
      };
    }

    return {
      table: mergedTable,
      warning: `${mergedTable.tableNumber} will be restored into ${sourceSummary}. Original capacities, statuses, and table links will be recovered.`,
    };
  }

  function requestSplitMergedTable(mergedTable: DemoTable) {
    if (!canManageTables || !mergedTable.mergedFrom?.length) {
      return;
    }

    setSplitMergeReview(getSplitMergeReview(mergedTable));
  }

  async function splitMergedTable(mergedTable: DemoTable) {
    if (!canManageTables || !mergedTable.mergedFrom?.length) {
      return;
    }

    const review = getSplitMergeReview(mergedTable);

    if (review.booking) {
      setSplitMergeReview(review);
      return;
    }

    if (
      !selectedShowId ||
      !mergedTable.authoritativeId ||
      operationalTableAction
    ) {
      return;
    }

    setOperationalTableAction(`unmerge-${mergedTable.id}`);

    try {
      await unmergeOperationalShowTable({
        showReference: selectedShowId,
        tableId: mergedTable.authoritativeId,
        zoneId: mergedTable.zoneId,
      });
      await refreshAssignedShowState(selectedShowId);
      showWorkflowToast(
        `${mergedTable.tableNumber} was restored to its physical member tables.`,
      );
      setSplitMergeReview(null);
    } catch (error) {
      await refreshAssignedShowState(selectedShowId).catch(() => undefined);
      showWorkflowToast(
        error instanceof Error
          ? error.message
          : "The merged table could not be restored.",
      );
    } finally {
      setOperationalTableAction("");
    }
  }

  function updateBookingCustomer(
    reference: string,
    field: keyof DemoBooking["customer"],
    value: string,
  ) {
    if (!canManageBookings || isBookingReadOnly(reference)) {
      if (isBookingReadOnly(reference)) {
        showWorkflowToast("This booking is currently being edited.");
      }
      return;
    }

    saveBookings(
      bookings.map((booking) =>
        booking.reference === reference
          ? {
              ...booking,
              customer: {
                ...booking.customer,
                [field]: value,
              },
            }
          : booking,
      ),
    );
  }

  function updateBookingOperationalField(
    reference: string,
    field:
      | "cancellationReason"
      | "operationalNotes"
      | "refundNotes",
    value: string,
  ) {
    if (!canManageBookings || isBookingReadOnly(reference)) {
      if (isBookingReadOnly(reference)) {
        showWorkflowToast("This booking is currently being edited.");
      }
      return;
    }

    saveBookings(
      bookings.map((booking) =>
        booking.reference === reference
          ? {
              ...booking,
              [field]: value,
            }
          : booking,
      ),
    );
  }

  function releaseBookingTableFromList(
    currentTables: DemoTable[],
    booking: DemoBooking,
  ) {
    const bookingTable = currentTables.find(
      (table) =>
        table.id === booking.tableId &&
        table.bookingReference === booking.reference,
    );

    if (bookingTable?.mergedFrom?.length) {
      const sourceTableIds = new Set(bookingTable.mergedFrom);

      return currentTables
        .filter((table) => table.id !== bookingTable.id)
        .map((table) =>
          sourceTableIds.has(table.id)
            ? {
                ...table,
                status: "available" as const,
                bookingReference: undefined,
                mergedInto: undefined,
                guestNotes: "",
              }
            : table,
        );
    }

    return currentTables.map((table) =>
      table.id === booking.tableId &&
      table.bookingReference === booking.reference
        ? {
            ...table,
            status: "available" as const,
            bookingReference: undefined,
            mergedInto: undefined,
            guestNotes: "",
          }
        : table,
    );
  }

  function releaseBookingTable(booking: DemoBooking) {
    if (!canManageBookings) {
      return;
    }

    saveTables(releaseBookingTableFromList(tables, booking));
  }

  function getRefundUnavailableReason(booking: DemoBooking) {
    if (!isSuperAdmin) {
      return "Super Admin access is required.";
    }

    if (!refundEligibilityLoaded) {
      return "Refund eligibility is loading.";
    }

    const result = refundEligibility[booking.reference];

    if (result?.eligible) {
      return "";
    }

    return (
      result?.reason ||
      refundReadinessReason ||
      "This booking does not have a server-confirmed refundable PayFast transaction."
    );
  }

  function createLifecycleEvent(
    booking: DemoBooking,
    toStatus: BookingStatus,
    note?: string,
  ) {
    const createdAt = new Date().toISOString();

    return {
      id: `${booking.reference}-${toStatus}-${createdAt}`,
      fromStatus: booking.status,
      toStatus,
      note,
      createdAt,
    };
  }

  function getCancellationSummary() {
    const trimmedOtherReason = cancellationOtherReason.trim();

    if (cancellationReason === "Other") {
      return trimmedOtherReason
        ? `Other: ${trimmedOtherReason}`
        : "Other";
    }

    return trimmedOtherReason
      ? `${cancellationReason}: ${trimmedOtherReason}`
      : cancellationReason;
  }

  function openCancellationModal(booking: DemoBooking) {
    if (isArchivedBooking(booking)) {
      showWorkflowToast("Restore this booking before making changes.");
      return;
    }

    if (!canManageBookings || isBookingReadOnly(booking.reference)) {
      if (isBookingReadOnly(booking.reference)) {
        showWorkflowToast("This booking is currently being edited.");
      }
      return;
    }

    setCancellingBookingReference(booking.reference);
    setCancellationReason(cancellationReasons[0]);
    setCancellationOtherReason("");
  }

  function closeCancellationModal() {
    if (isCancellingBooking) {
      return;
    }

    setCancellingBookingReference("");
    setCancellationReason(cancellationReasons[0]);
    setCancellationOtherReason("");
  }

  async function cancelBooking(booking: DemoBooking, reason: string) {
    if (!canManageBookings || isBookingReadOnly(booking.reference)) {
      if (isBookingReadOnly(booking.reference)) {
        showWorkflowToast("This booking is currently being edited.");
      }
      return;
    }

    const cancelledAt = new Date().toISOString();
    const cancelledBooking = {
      ...booking,
      cancelledAt,
      cancellationReason: reason,
      lifecycleHistory: [
        createLifecycleEvent(
          booking,
          "cancelled",
          `Cancellation reason: ${reason}`,
        ),
        ...(booking.lifecycleHistory ?? []),
      ],
      status: "cancelled" as const,
    };
    const cancellationRecord = createWorkflowCommunication(
      cancelledBooking,
      "cancellation-refund",
      "email",
      {
        refundSummary:
          "This notice records the cancellation and marks the booking for refund review.",
      },
    );

    const nextCancelledBooking = {
      ...cancelledBooking,
      communicationHistory: [
        cancellationRecord,
        ...(booking.communicationHistory ?? []),
      ],
    };
    setIsCancellingBooking(true);

    try {
      const persistedBookings =
        await persistBookingCancellation(nextCancelledBooking);

      setBookings(persistedBookings);
      releaseBookingTable(booking);
      closeBookingDetails();
      setCancellingBookingReference("");
      setCancellationReason(cancellationReasons[0]);
      setCancellationOtherReason("");
      void releaseCurrentBookingLock("cancelled");
      void sendPreferredBrowserNotification(
        "booking-cancelled",
        "booking-cancelled",
      );
      void sendZingaraStaffPushNotification("booking-cancelled", {
        bookingReference: booking.reference,
      });
      void sendZingaraGuestPushNotification("reservation-cancelled", {
        bookingReference: booking.reference,
      });
      showWorkflowToast("✓ Saved · Booking cancelled");
    } catch {
      showWorkflowToast("⚠ Could not save cancellation");
    } finally {
      setIsCancellingBooking(false);
    }
  }

  function confirmBookingCancellation() {
    if (isCancellingBooking) {
      return;
    }

    const booking = bookings.find(
      (currentBooking) =>
        currentBooking.reference === cancellingBookingReference,
    );

    if (!booking) {
      closeCancellationModal();
      return;
    }

    void cancelBooking(booking, getCancellationSummary());
  }

  function openBookingArchiveModal(mode: "all" | "filtered") {
    if (!isSuperAdmin) {
      showWorkflowToast("Super Admin access is required.");
      return;
    }

    const archivableBookings =
      mode === "all"
        ? getAllNonArchivedBookings()
        : getFilteredArchivableBookings();
    const references = archivableBookings.map((booking) => booking.reference);

    if (references.length === 0) {
      showWorkflowToast("No non-archived bookings are available to archive.");
      return;
    }

    setBookingArchiveModal({ mode, references });
    setBookingArchiveReason("End-of-period archive.");
    setBookingArchiveConfirmation("");
    setBookingArchiveStatus("");
  }

  function closeBookingArchiveModal() {
    if (isBookingArchiveSubmitting) {
      return;
    }

    setBookingArchiveModal(null);
    setBookingArchiveReason("End-of-period archive.");
    setBookingArchiveConfirmation("");
    setBookingArchiveStatus("");
  }

  async function confirmBookingArchive() {
    if (
      !bookingArchiveModal ||
      isBookingArchiveSubmitting ||
      bookingArchiveConfirmation.trim() !== "ARCHIVE BOOKINGS"
    ) {
      return;
    }

    const currentReferences =
      bookingArchiveModal.mode === "all"
        ? getAllNonArchivedBookings().map((booking) => booking.reference)
        : getFilteredArchivableBookings().map((booking) => booking.reference);

    if (
      currentReferences.length !== bookingArchiveModal.references.length ||
      currentReferences.some(
        (reference) => !bookingArchiveModal.references.includes(reference),
      )
    ) {
      setBookingArchiveModal({
        ...bookingArchiveModal,
        references: currentReferences,
      });
      setBookingArchiveConfirmation("");
      setBookingArchiveStatus(
        "The affected booking count changed. Review the updated count and confirm again.",
      );
      return;
    }

    setIsBookingArchiveSubmitting(true);
    setBookingArchiveStatus("Archiving selected bookings...");

    try {
      const persistedBookings = await archiveBookings(
        currentReferences,
        bookingArchiveReason,
      );

      setBookings(persistedBookings);
      setBookingArchiveStatus("");
      setBookingArchiveModal(null);
      setBookingArchiveReason("End-of-period archive.");
      setBookingArchiveConfirmation("");
      showWorkflowToast(
        `✓ Archived ${currentReferences.length} booking${currentReferences.length === 1 ? "" : "s"}`,
      );
    } catch {
      setBookingArchiveStatus("Archive could not be completed.");
      showWorkflowToast("⚠ Archive could not be completed");
    } finally {
      setIsBookingArchiveSubmitting(false);
    }
  }

  async function restoreBooking(booking: DemoBooking) {
    if (!isSuperAdmin) {
      showWorkflowToast("Super Admin access is required.");
      return;
    }

    try {
      const persistedBookings = await restoreBookings([booking.reference]);

      setBookings(persistedBookings);
      showWorkflowToast(`✓ Restored ${booking.reference}`);
    } catch {
      showWorkflowToast("⚠ Booking could not be restored");
    }
  }

  function updateBookingStatus(
    booking: DemoBooking,
    status: BookingStatus,
  ) {
    if (!canManageBookings || isBookingReadOnly(booking.reference)) {
      if (isBookingReadOnly(booking.reference)) {
        showWorkflowToast("This booking is currently being edited.");
      }
      return;
    }

    if (status === booking.status) {
      return;
    }

    if (status === "cancelled") {
      openCancellationModal(booking);
      return;
    }

    if (status === "refunded") {
      showWorkflowToast(
        "Use Refund Booking so provider eligibility and refund history are verified.",
      );
      return;
    }

    if (
      status === "completed" ||
      status === "no-show" ||
      status === "waitlisted"
    ) {
      releaseBookingTable(booking);
    }

    const arrivalTime =
      status === "checked-in"
        ? booking.arrivalTime ?? new Date().toISOString()
        : booking.arrivalTime;
    const lifecyclePaymentUpdates =
      status === "pending-payment" || status === "new"
          ? {
              amountPaid: booking.amountPaid ?? 0,
              balanceDue:
                booking.balanceDue ??
                Math.max(
                  booking.totalPrice - (booking.amountPaid ?? 0),
                  0,
                ),
              paymentStatus:
                booking.paymentStatus ?? ("pending-payment" as const),
            }
          : {};
    const updatedBooking = {
      ...booking,
      ...lifecyclePaymentUpdates,
      arrivalTime,
      lifecycleHistory: [
        createLifecycleEvent(
          booking,
          status,
          `Status changed to ${bookingStatusLabels[status]}.`,
        ),
        ...(booking.lifecycleHistory ?? []),
      ],
      refundNotes: booking.refundNotes,
      status,
    };
    const statusRecord = createWorkflowCommunication(
      updatedBooking,
      status === "checked-in"
        ? "check-in-confirmation"
        : "booking-update",
      "email",
      {
        updateSummary: `Status changed to ${bookingStatusLabels[status]}.`,
      },
    );

    saveBookings(
      bookings.map((currentBooking) =>
        currentBooking.reference === booking.reference
          ? {
              ...currentBooking,
              arrivalTime,
              communicationHistory: [
                statusRecord,
                ...(currentBooking.communicationHistory ?? []),
              ],
              lifecycleHistory: updatedBooking.lifecycleHistory,
              amountPaid: updatedBooking.amountPaid,
              balanceDue: updatedBooking.balanceDue,
              paymentStatus: updatedBooking.paymentStatus,
              refundNotes: updatedBooking.refundNotes,
              status,
            }
          : currentBooking,
      ),
    );
    void sendPreferredBrowserNotification(
      status === "checked-in" ? "guest-checked-in" : "new-booking",
      status === "checked-in"
        ? "check-in-confirmed"
        : "booking-updated",
    );
    if (status === "confirmed") {
      void sendZingaraGuestPushNotification("reservation-confirmed", {
        bookingReference: booking.reference,
      });
    }
    if (status === "pending-payment") {
      void sendZingaraGuestPushNotification("reservation-pending-payment", {
        bookingReference: booking.reference,
      });
    }
  }

  async function updateBookingPayment(
    booking: DemoBooking,
    paymentStatus: PaymentStatus,
  ) {
    if (!canManageBookings || isBookingReadOnly(booking.reference)) {
      if (isBookingReadOnly(booking.reference)) {
        showWorkflowToast("This booking is currently being edited.");
      }
      return;
    }

    if (paymentStatus === "refunded") {
      openRefundBookingConfirmation(booking);
      return;
    }

    const financials = getBookingFinancials(booking);
    const paymentUpdates =
      paymentStatus === "fully-paid"
        ? {
            amountPaid: financials.totalPrice,
            balanceDue: 0,
          }
        : paymentStatus === "deposit-paid"
          ? {
              amountPaid: financials.depositAmount,
              balanceDue: Math.max(
                financials.totalPrice - financials.depositAmount,
                0,
              ),
            }
          : paymentStatus === "comp-vip"
            ? {
                amountPaid: 0,
                balanceDue: 0,
              }
              : {
                  amountPaid: 0,
                  balanceDue: financials.totalPrice,
                };
    const nextStatus = booking.status;
    const paymentLifecycleNote =
      paymentStatus === "fully-paid" || paymentStatus === "deposit-paid"
        ? `Payment received: ${paymentStatusLabels[paymentStatus]}.`
        : paymentStatus === "comp-vip"
          ? "Comp booking marked by box office."
          : undefined;
    const updatedBooking = {
      ...booking,
      ...paymentUpdates,
      paymentStatus,
      lifecycleHistory:
        paymentLifecycleNote
            ? [
                createLifecycleEvent(
                  booking,
                  nextStatus,
                  paymentLifecycleNote,
                ),
                ...(booking.lifecycleHistory ?? []),
              ]
          : booking.lifecycleHistory,
      refundNotes: booking.refundNotes,
      status: nextStatus,
    };
    const paymentCommunicationTrigger =
      paymentStatus === "comp-vip"
          ? ("complimentary-booking" as const)
          : ("payment-confirmation" as const);
    const paymentRecord = createWorkflowCommunication(
      updatedBooking,
      paymentCommunicationTrigger,
      "email",
      {
        updateSummary: `Payment status changed to ${paymentStatusLabels[paymentStatus]}.`,
      },
    );

    const nextBooking = {
      ...updatedBooking,
      communicationHistory: [
        paymentRecord,
        ...(booking.communicationHistory ?? []),
      ],
    };

    setBookings((currentBookings) =>
      currentBookings.map((currentBooking) =>
        currentBooking.reference === booking.reference
          ? nextBooking
          : currentBooking,
      ),
    );

    try {
      await persistAdminBookingState(nextBooking);
      showWorkflowToast("✓ Booking updated successfully.");
      void sendPreferredBrowserNotification(
        "new-booking",
        "booking-updated",
      );

      if (paymentStatus === "fully-paid" || paymentStatus === "deposit-paid") {
        const [guestPushResult, staffPushResult] = await Promise.all([
          sendZingaraGuestPushNotification("payment-received", {
            bookingReference: booking.reference,
          }),
          sendZingaraStaffPushNotification("payment-received", {
            bookingReference: booking.reference,
          }),
        ]);

        if (!guestPushResult.ok && !staffPushResult.ok) {
          showWorkflowToast(
            "✓ Booking updated successfully. No active push subscription is available.",
          );
        } else {
          showWorkflowToast("✓ Push notification sent successfully.");
        }
      }
  } catch (error) {
      console.error("[Zingara Admin] Payment update failed", error);
      setBookings(await getBookings());
      showWorkflowToast("⚠ Booking update could not be saved.");
    }
  }

  function openRefundBookingConfirmation(booking: DemoBooking) {
    if (!canManageBookings || isBookingReadOnly(booking.reference)) {
      if (isBookingReadOnly(booking.reference)) {
        showWorkflowToast("This booking is currently being edited.");
      }
      return;
    }

    const unavailableReason = getRefundUnavailableReason(booking);

    if (unavailableReason) {
      showWorkflowToast(unavailableReason);
      return;
    }

    setRefundBookingReference(booking.reference);
    setRefundAdminPassword("");
    setRefundBookingReason(booking.refundNotes ?? "");
  }

  function closeRefundBookingConfirmation() {
    if (isRefundBookingProcessing) {
      return;
    }

    setRefundBookingReference("");
    setRefundAdminPassword("");
    setRefundBookingReason("");
  }

  async function confirmRefundBooking() {
    if (isRefundBookingProcessing || !refundBookingReference) {
      return;
    }

    const booking = bookings.find(
      (currentBooking) => currentBooking.reference === refundBookingReference,
    );
    const reason = refundBookingReason.trim();

    if (!booking) {
      closeRefundBookingConfirmation();
      return;
    }

    if (!canManageBookings || isBookingReadOnly(booking.reference)) {
      showWorkflowToast("This booking is currently being edited.");
      return;
    }

    const password = refundAdminPassword;
    const unavailableReason = getRefundUnavailableReason(booking);

    if (unavailableReason) {
      showWorkflowToast(unavailableReason);
      return;
    }

    if (!reason) {
      showWorkflowToast("Add a refund reason before recording the refund.");
      return;
    }

    if (!password) {
      showWorkflowToast("Password confirmation failed.");
      return;
    }

    setIsRefundBookingProcessing(true);

    try {
      const result = await fetchSupabaseApi<{
        message?: string;
        refund?: { amount: number; providerRefundId?: string | null; status: string };
      }>("/api/admin/bookings/refund", {
        body: {
          bookingReference: booking.reference,
          password,
          reason,
        },
        method: "POST",
      });

      saveTables(releaseBookingTableFromList(tables, booking));
      setBookings(await getBookings());
      setPaymentRows(await getPayments());
      setRefundEligibilityRefreshKey((currentKey) => currentKey + 1);
      setRefundBookingReference("");
      setRefundAdminPassword("");
      setRefundBookingReason("");
      showWorkflowToast(result.message ?? "Refund processed successfully.");
    } catch (error) {
      console.error("[Zingara Admin] Refund recording failed", error);
      setBookings(await getBookings());
      showWorkflowToast(
        error instanceof Error
          ? error.message
          : "Refund could not be processed. No changes were made to the booking.",
      );
    } finally {
      setIsRefundBookingProcessing(false);
    }
  }

  function openCompBookingConfirmation(booking: DemoBooking) {
    if (!canManageBookings || isBookingReadOnly(booking.reference)) {
      if (isBookingReadOnly(booking.reference)) {
        showWorkflowToast("This booking is currently being edited.");
      }
      return;
    }

    setCompBookingReference(booking.reference);
  }

  function closeCompBookingConfirmation() {
    if (isCompBookingProcessing) {
      return;
    }

    setCompBookingReference("");
  }

  async function confirmCompBooking() {
    if (isCompBookingProcessing || !compBookingReference) {
      return;
    }

    const booking = bookings.find(
      (currentBooking) => currentBooking.reference === compBookingReference,
    );

    if (!booking) {
      setCompBookingReference("");
      return;
    }

    if (!canManageBookings || isBookingReadOnly(booking.reference)) {
      showWorkflowToast("This booking is currently being edited.");
      return;
    }

    const updatedBooking = {
      ...booking,
      amountPaid: 0,
      balanceDue: 0,
      paymentStatus: "comp-vip" as const,
      lifecycleHistory: [
        createLifecycleEvent(
          booking,
          booking.status,
          "Comp booking marked by box office.",
        ),
        ...(booking.lifecycleHistory ?? []),
      ],
    };
    const compRecord = createWorkflowCommunication(
      updatedBooking,
      "complimentary-booking",
      "email",
      {
        updateSummary: `Payment status changed to ${paymentStatusLabels["comp-vip"]}.`,
      },
    );

    setIsCompBookingProcessing(true);
    setBookings((currentBookings) =>
      currentBookings.map((currentBooking) =>
        currentBooking.reference === booking.reference
          ? {
              ...updatedBooking,
              communicationHistory: [
                compRecord,
                ...(booking.communicationHistory ?? []),
              ],
            }
          : currentBooking,
      ),
    );

    try {
      await persistAdminBookingState(updatedBooking);
      const result = await persistCustomGuestCommunication(
        updatedBooking,
        compRecord,
      );
      const status = result.row?.status ?? (result.deduped ? "sent" : null);

      setBookings(await getBookings());
      setCompBookingReference("");

      if (result.deduped) {
        showWorkflowToast("✓ Booking updated successfully. Email already sent.");
      } else if (status === "sent") {
        showWorkflowToast("✓ Booking updated successfully. Email sent successfully.");
      } else {
        showWorkflowToast("✓ Booking updated successfully. Email could not be sent.");
      }
    } catch (error) {
      console.error("[Zingara Admin] Comp booking failed", error);
      setBookings(await getBookings());
      showWorkflowToast("⚠ Booking update could not be saved.");
    } finally {
      setIsCompBookingProcessing(false);
    }
  }

  function getReportBookings() {
    return bookings.filter((booking) => {
      const show = getBookingShow(booking);
      const paymentStatus = getBookingPaymentStatus(booking);

      return (
        Boolean(analyticsSelectedShow) &&
        bookingBelongsToShow(booking, analyticsSelectedShow) &&
        (reportDateFilter ? show?.date === reportDateFilter : true) &&
        (reportStatusFilter === "all"
          ? true
          : (booking.status ?? "confirmed") === reportStatusFilter) &&
        (reportZoneFilter === "all"
          ? true
          : booking.zoneId === reportZoneFilter) &&
        (reportPaymentFilter === "all"
          ? true
          : paymentStatus === reportPaymentFilter)
      );
    });
  }

  function getReportRows(reportType: OperationalReportType) {
    const reportBookings = getReportBookings();

    if (reportType === "waitlist") {
      return waitlist
        .filter((entry) =>
          getShowIdentityValues(analyticsSelectedShow).includes(entry.showId),
        )
        .map((entry) => ({
          reference: entry.id,
          customer: entry.customer.name,
          email: entry.customer.email,
          phone: entry.customer.phone,
          guests: entry.partySize,
          preferredZone: entry.desiredZoneTitle ?? "Any",
          status: waitlistStatusLabels[entry.status],
          notes: entry.notes,
        }));
    }

    if (reportType === "crm") {
      return customerProfiles.map((profile) => ({
        customer: profile.customer.name,
        email: profile.customer.email,
        phone: profile.customer.phone,
        bookings: profile.totalBookings,
        totalSpend: profile.totalSpend,
        favouriteZone: profile.favouriteZone,
        vipTags: profile.vipTags.join("; "),
        notes: profile.notes,
      }));
    }

    if (reportType === "table-allocations") {
      return tables
        .filter((table) =>
          table.showId
            ? getShowIdentityValues(analyticsSelectedShow).includes(table.showId)
            : false,
        )
        .map((table) => {
          const occupancy = getTableOccupancy(table, bookings);

          return {
            zone: getZoneById(table.zoneId)?.title ?? table.zoneId,
            table: table.tableNumber,
            seats: table.seatCapacity,
            status: tableOccupancyLabels[occupancy.state],
            booking: occupancy.booking?.reference,
            guest: occupancy.booking?.customer.name,
            notes: table.guestNotes,
          };
        });
    }

    if (reportType === "revenue") {
      return reportBookings.map((booking) => {
        const financials = getBookingFinancials(booking);

        return {
          reference: booking.reference,
          customer: booking.customer.name,
          status: bookingStatusLabels[booking.status ?? "confirmed"],
          paymentStatus: paymentStatusLabels[financials.paymentStatus],
          subtotal: financials.subtotalPrice,
          addons: financials.addonsTotal,
          discounts: financials.discountAmount,
          total: financials.totalPrice,
          paid: financials.amountPaid,
          outstanding: financials.balanceDue,
        };
      });
    }

    if (reportType === "check-ins") {
      return reportBookings.map((booking) => ({
        reference: booking.reference,
        customer: booking.customer.name,
        phone: booking.customer.phone,
        guests: booking.partySize,
        zone: booking.zoneTitle,
        table: booking.tableNumber,
        status: bookingStatusLabels[booking.status ?? "confirmed"],
        arrival: booking.arrivalTime
          ? formatSouthAfricanTimestamp(booking.arrivalTime)
          : "",
        signature: "",
      }));
    }

    if (reportType === "guest-list") {
      return reportBookings.map((booking) => ({
        customer: booking.customer.name,
        email: booking.customer.email,
        phone: booking.customer.phone,
        guests: booking.partySize,
        zone: booking.zoneTitle,
        table: booking.tableNumber,
        notes: booking.operationalNotes,
      }));
    }

    return reportBookings.map((booking) => {
      const financials = getBookingFinancials(booking);

      return {
        reference: booking.reference,
        show: getShowLabel(getBookingShow(booking)),
        customer: booking.customer.name,
        email: booking.customer.email,
        phone: booking.customer.phone,
        guests: booking.partySize,
        zone: booking.zoneTitle,
        table: booking.tableNumber,
        status: bookingStatusLabels[booking.status ?? "confirmed"],
        paymentStatus: paymentStatusLabels[financials.paymentStatus],
        total: financials.totalPrice,
        paid: financials.amountPaid,
        outstanding: financials.balanceDue,
        notes: booking.operationalNotes,
      };
    });
  }

  function downloadTextFile(
    filename: string,
    content: string,
    mimeType: string,
  ) {
    const url = URL.createObjectURL(new Blob([content], { type: mimeType }));
    const link = document.createElement("a");

    link.href = url;
    link.download = filename;
    link.click();
    URL.revokeObjectURL(url);
  }

  function downloadBlobFile(filename: string, blob: Blob) {
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");

    link.href = url;
    link.download = filename;
    link.click();
    URL.revokeObjectURL(url);
  }

  async function downloadTablePlan() {
    const showId = analyticsSelectedShow?.supabaseId;

    if (!showId || isTablePlanExporting) {
      setTablePlanExportStatus(
        showId
          ? "A table plan export is already in progress."
          : "Select an available performance first.",
      );
      return;
    }

    setIsTablePlanExporting(true);
    setTablePlanExportStatus("Generating table plan...");

    try {
      const authSession = await getAdminAuthSession();

      if (!authSession) {
        throw new Error("Your Admin session has expired. Sign in again.");
      }

      const response = await fetch(
        `/api/admin/analytics/table-plan?showId=${encodeURIComponent(showId)}`,
        {
          headers: {
            Authorization: `Bearer ${authSession.session.access_token}`,
          },
        },
      );

      if (!response.ok) {
        const payload = (await response.json().catch(() => ({}))) as {
          error?: string;
        };

        throw new Error(payload.error ?? "The table plan could not be generated.");
      }

      const contentDisposition = response.headers.get("content-disposition") ?? "";
      const filename =
        contentDisposition.match(/filename="([^"]+)"/i)?.[1] ??
        `Zingara_Table_Plan_${analyticsSelectedShow?.date ?? "show"}.xlsx`;

      downloadBlobFile(filename, await response.blob());
      setTablePlanExportStatus("Table plan downloaded successfully.");
    } catch (error) {
      setTablePlanExportStatus(
        error instanceof Error
          ? error.message
          : "The table plan could not be generated.",
      );
    } finally {
      setIsTablePlanExporting(false);
    }
  }

  function parseExportDate(dateValue?: string | null) {
    if (!dateValue) {
      return "Not recorded";
    }

    const date = new Date(dateValue);

    return Number.isNaN(date.getTime()) ? dateValue : date;
  }

  function getExportLocationSlug() {
    return sanitizeExportFileName(financialLocationLabel || manifestLocationLabel);
  }

  function getExportPeriodLabel() {
    if (activeFinancialReportTab === "monthly-income" ||
        activeFinancialReportTab === "complimentary-bookings") {
      return financialReportingMonth;
    }

    return `${financialDateFromValue}_to_${financialDateToValue}`;
  }

  function withRowsOrEmpty(sheet: ExportSheet): ExportSheet {
    if (sheet.rows.length > 0) {
      return sheet;
    }

    return {
      ...sheet,
      rows: [
        {
          [sheet.columns[0] ?? "Status"]: "No matching records",
        },
      ],
    };
  }

