  function normalizeImportLookupValue(value: string) {
    return value.trim().toLowerCase();
  }

  function normalizeImportTimeValue(value?: string | null) {
    const trimmedValue = value?.trim();

    if (!trimmedValue) {
      return "";
    }

    const directMatch = trimmedValue.match(/\b(\d{1,2})[:hH](\d{2})\b/);

    if (directMatch) {
      return `${directMatch[1].padStart(2, "0")}:${directMatch[2]}`;
    }

    const hourOnlyMatch = trimmedValue.match(/\b(\d{1,2})\b/);

    if (
      hourOnlyMatch &&
      trimmedValue.replace(/\D/g, "") === hourOnlyMatch[1]
    ) {
      return `${hourOnlyMatch[1].padStart(2, "0")}:00`;
    }

    const parsedDate = new Date(trimmedValue);

    if (!Number.isNaN(parsedDate.getTime())) {
      return formatSouthAfricanTime(parsedDate);
    }

    return "";
  }

  function getImportSourceTime(record: Record<string, string>) {
    const timeValue =
      record.show_time ||
      record.time ||
      record.showtime ||
      record.performance_time ||
      record.session_time ||
      record.reservation_time ||
      "";

    return normalizeImportTimeValue(timeValue);
  }

  function normalizeImportLocationValue(value?: string | null) {
    const normalizedValue = normalizeImportLookupValue(value ?? "");

    if (
      normalizedValue === "cape-town" ||
      normalizedValue === "cape town" ||
      normalizedValue === "capetown" ||
      normalizedValue === "cpt" ||
      normalizedValue === "cape town — the night court" ||
      normalizedValue === "cape town - the night court"
    ) {
      return "cape-town";
    }

    if (
      normalizedValue === "johannesburg" ||
      normalizedValue === "joburg" ||
      normalizedValue === "jhb" ||
      normalizedValue === "johannesburg — the spring court" ||
      normalizedValue === "johannesburg - the spring court"
    ) {
      return "johannesburg";
    }

    return null;
  }

  function getShowImportAliases(show: DemoShow) {
    return [
      show.id,
      show.label,
      getShowLabel(show),
      show.date,
      getSouthAfricaShowTime(show),
      `${show.label} ${show.date}`,
      `${show.label} ${show.date} ${getSouthAfricaShowTime(show)}`,
    ]
      .filter(Boolean)
      .map((value) => normalizeImportLookupValue(String(value)));
  }

  function getImportShowLocationLabel(location: EntryLocationKey) {
    return getShowLocationOption(location).label;
  }

  function getImportPerformanceLocationAlias(value: string) {
    const location = normalizeShowLocation(value);

    if (location) {
      return getShowCalendarLocationDisplay(location).alias;
    }

    const normalizedValue = normalizeImportLookupValue(value);

    if (normalizedValue.includes("joburg") || normalizedValue.includes("johannesburg")) {
      return "JHB";
    }

    if (normalizedValue.includes("cape")) {
      return "CPT";
    }

    return "LOC";
  }

  function getCompactImportPerformanceLabel({
    date,
    location,
    time,
  }: {
    date: string;
    location: string;
    time: string;
  }) {
    return `${getImportPerformanceLocationAlias(location)} • ${
      date ? formatFloorShowSelectorDate(date) : "Date TBC"
    } • ${time || "Time TBC"}`;
  }

  function getImportShowDisplay(show: DemoShow) {
    const location = normalizeShowLocation(show.location ?? show.venueName);
    const locationLabel = location
      ? getImportShowLocationLabel(location)
      : "Unknown location";

    return `${locationLabel} · ${formatOperationalShowDate(show.date)} · ${getSouthAfricaShowTime(show)}`;
  }

  function getDineplanImportScopeKey(record: Record<string, string>) {
    const showResolution = resolveImportShow(record);
    const show = showResolution.show;
    const location = record.location || "";
    const date = record.source_date || record.show_date || show?.date || "";
    const time =
      show ? getSouthAfricaShowTime(show) : record.source_time || record.show_time || "";
    const showId = show?.supabaseId ?? show?.id ?? "";

    return `${location}|${date}|${time}|${showId}`;
  }

  function getImportZoneAliases(zone: SeatingZone) {
    return [zone.id, ...getZoneSectionLookupTitles(zone.id, zone.title)].map(
      normalizeImportLookupValue,
    );
  }

  function isImportAllocatableTable(table: DataPortabilityTableSnapshotRow) {
    const status = normalizeImportLookupValue(table.status);

    return (
      !table.booking_id &&
      status !== "booked" &&
      status !== "blocked" &&
      status !== "unavailable"
    );
  }

  function toImportDemoTable(
    table: DataPortabilityTableSnapshotRow,
    zone: SeatingZone,
  ): DemoTable {
    return {
      availabilityScope: table.availability_scope ?? "public",
      bookingReference: table.booking_id ?? undefined,
      guestNotes: "",
      id: table.id,
      seatCapacity: Number(table.capacity) || 0,
      showId: table.show_id,
      status: isImportAllocatableTable(table) ? "available" : "booked",
      tableNumber: table.table_code,
      zoneId: zone.id,
    };
  }

  function getImportShowKeys(show: DemoShow) {
    return [
      show.id,
      show.supabaseId ?? "",
    ].filter(Boolean);
  }

  function getImportCapacityKey(show: DemoShow, zone: SeatingZone) {
    return `${show.supabaseId ?? show.id}|${zone.id}`;
  }

  function getImportCapacityBookingShowIds(show: DemoShow) {
    return new Set(getImportShowKeys(show));
  }

  function getDineplanCapacityStatus(record: Record<string, string>) {
    return getImportBookingStatus(record.booking_status ?? "");
  }

  function isDineplanCapacityConsumingRecord(record: Record<string, string>) {
    const status = getDineplanCapacityStatus(record);

    return status !== "cancelled" && status !== "no-show";
  }

  function getDataPortabilityAllocationLabel(
    state: DataPortabilityAllocationState,
  ) {
    if (state === "AUTO_ALLOCATED_EXISTING") {
      return "Assigned to Existing Table";
    }

    if (state === "AUTO_ALLOCATED_OVERFLOW") {
      return "Requires floor assignment";
    }

    if (state === "EXPLICIT_TABLE") {
      return "Explicit table";
    }

    if (state === "NOT_APPLICABLE") {
      return "Not applicable";
    }

    if (state === "REQUIRES_FLOOR_ASSIGNMENT") {
      return "Requires floor assignment";
    }

    return "Unresolved";
  }

  type DineplanOverflowPlan = {
    capacity: number;
    date: string;
    location: string;
    resolvedLabel: string;
    rowNumber?: number;
    tableNumber: string;
    zone: string;
  };

  type DineplanAllocationSimulationResult = {
    isOverflow: boolean;
    overflowPlan?: DineplanOverflowPlan;
    table: DemoTable;
  };

  function getImportTableCodeParts(tableNumber: string) {
    const match = tableNumber.match(/^([A-Z]+)(\d+)$/i);

    return match
      ? {
          prefix: match[1].toUpperCase(),
          sequence: Number(match[2]),
        }
      : undefined;
  }

  function getDineplanOverflowTableNumber(
    showTables: DemoTable[],
    plannedTables: DemoTable[],
    zone: SeatingZone,
  ) {
    const zoneTables = [...showTables, ...plannedTables].filter(
      (table) => table.zoneId === zone.id,
    );
    const prefixCounts = new Map<string, number>();
    let fallbackPrefix = zone.id
      .split("-")
      .map((part) => part[0]?.toUpperCase() ?? "")
      .join("");
    let highestSequence = 0;

    zoneTables.forEach((table) => {
      const parts = getImportTableCodeParts(table.tableNumber);

      if (!parts) {
        return;
      }

      prefixCounts.set(parts.prefix, (prefixCounts.get(parts.prefix) ?? 0) + 1);
    });

    const preferredPrefix =
      [...prefixCounts.entries()].sort(
        (left, right) => right[1] - left[1] || left[0].localeCompare(right[0]),
      )[0]?.[0] ?? fallbackPrefix;

    fallbackPrefix = preferredPrefix || "T";

    zoneTables.forEach((table) => {
      const parts = getImportTableCodeParts(table.tableNumber);

      if (parts?.prefix === fallbackPrefix) {
        highestSequence = Math.max(highestSequence, parts.sequence);
      }
    });

    return `${fallbackPrefix}${highestSequence + 1}`;
  }

  function buildDineplanCapacityGroups(
    records: Record<string, string>[],
    tableSnapshotPayload?: {
      showMappings: DataPortabilityTableSnapshotShowMapping[];
      tables: DataPortabilityTableSnapshotRow[];
    } | null,
  ) {
    const capacities = new Map<string, number>();
    const conflictMetadata = new Map<
      string,
      {
        affectedRows: number;
        date: string;
        location: string;
        resolvedLabel: string;
        zone: string;
      }
    >();
    const existingActivePax = new Map<string, number>();
    const incomingActivePax = new Map<string, number>();
    const conflicts = new Set<string>();
    const showIdAliases = new Map<string, string[]>();

    tableSnapshotPayload?.showMappings.forEach((mapping) => {
      const aliases = showIdAliases.get(mapping.supabaseShowId) ?? [];

      showIdAliases.set(mapping.supabaseShowId, [
        ...new Set([
          ...aliases,
          mapping.requestedShowId,
          mapping.supabaseShowId,
        ]),
      ]);
    });

    tableSnapshotPayload?.tables.forEach((table) => {
      const zone = seatingZones.find((candidate) =>
        getImportZoneAliases(candidate).includes(
          normalizeImportLookupValue(table.section),
        ),
      );

      if (!zone) {
        return;
      }

      const key = `${table.show_id}|${zone.id}`;
      const nextCapacity =
        (capacities.get(key) ?? 0) + (Number(table.capacity) || 0);

      capacities.set(key, nextCapacity);
      (showIdAliases.get(table.show_id) ?? []).forEach((alias) => {
        capacities.set(`${alias}|${zone.id}`, nextCapacity);
      });
    });

    records.forEach((record) => {
      const showResolution = resolveImportShow(record);
      const zone = resolveImportZone(record);

      if (
        !showResolution.show ||
        !zone ||
        !isDineplanCapacityConsumingRecord(record)
      ) {
        return;
      }

      const key = getImportCapacityKey(showResolution.show, zone);
      const partySize = Math.max(
        1,
        Math.round(getImportNumber(record.number_of_guests ?? "", 1)),
      );
      const existingMetadata = conflictMetadata.get(key);

      incomingActivePax.set(key, (incomingActivePax.get(key) ?? 0) + partySize);
      conflictMetadata.set(key, {
        affectedRows: (existingMetadata?.affectedRows ?? 0) + 1,
        date: record.source_date || record.show_date || "",
        location: record.location || "",
        resolvedLabel: getImportShowDisplay(showResolution.show),
        zone: zone.title,
      });
    });

    records.forEach((record) => {
      const showResolution = resolveImportShow(record);
      const zone = resolveImportZone(record);

      if (!showResolution.show || !zone) {
        return;
      }

      const key = getImportCapacityKey(showResolution.show, zone);

      if (existingActivePax.has(key)) {
        return;
      }

      const showIds = getImportCapacityBookingShowIds(showResolution.show);
      const existingPax = bookings.reduce((total, booking) => {
        if (
          !showIds.has(booking.showId ?? "") ||
          booking.zoneId !== zone.id ||
          !isOperationallyActiveBooking(booking)
        ) {
          return total;
        }

        return total + booking.partySize;
      }, 0);

      existingActivePax.set(key, existingPax);
    });

    incomingActivePax.forEach((incomingPax, key) => {
      const capacity = capacities.get(key) ?? 0;
      const existingPax = existingActivePax.get(key) ?? 0;

      if (capacity > 0 && existingPax + incomingPax > capacity) {
        conflicts.add(key);
      }
    });

    return {
      capacities,
      conflicts,
      conflictMetadata,
      existingActivePax,
      incomingActivePax,
    };
  }

  async function loadDataPortabilityTableSnapshots(showIds: string[]) {
    const uniqueShowIds = [...new Set(showIds.filter(Boolean))];

    if (uniqueShowIds.length === 0) {
      return {
        showMappings: [],
        tables: [],
      };
    }

    const queryString = new URLSearchParams({
      showIds: uniqueShowIds.join(","),
    }).toString();
    const payload = await fetchSupabaseApi<{
      showMappings?: DataPortabilityTableSnapshotShowMapping[];
      tables?: DataPortabilityTableSnapshotRow[];
    }>(`/api/admin/data-portability/imports?${queryString}`);

    return {
      showMappings: payload.showMappings ?? [],
      tables: payload.tables ?? [],
    };
  }

  function createDineplanAllocationSimulator(
    tableSnapshotPayload: {
      showMappings: DataPortabilityTableSnapshotShowMapping[];
      tables: DataPortabilityTableSnapshotRow[];
    },
  ) {
    const simulatedTablesByShow = new Map<string, DemoTable[]>();
    const tableSnapshots = tableSnapshotPayload.tables;
    const tableKeyAliases = new Map<string, string[]>();

    tableSnapshotPayload.showMappings.forEach((mapping) => {
      const aliases = tableKeyAliases.get(mapping.supabaseShowId) ?? [];

      tableKeyAliases.set(mapping.supabaseShowId, [
        ...new Set([
          ...aliases,
          mapping.requestedShowId,
          mapping.supabaseShowId,
        ]),
      ]);
    });

    tableSnapshots.forEach((table) => {
      const zone = seatingZones.find((candidate) =>
        getImportZoneAliases(candidate).includes(
          normalizeImportLookupValue(table.section),
        ),
      );

      if (!zone) {
        return;
      }

      const tablesForShow = simulatedTablesByShow.get(table.show_id) ?? [];

      tablesForShow.push(toImportDemoTable(table, zone));
      simulatedTablesByShow.set(table.show_id, tablesForShow);
    });

    simulatedTablesByShow.forEach((showTables, showId) => {
      const sortedShowTables = [...showTables].sort((left, right) =>
          getImportTableSortValue(left.tableNumber).localeCompare(
            getImportTableSortValue(right.tableNumber),
          ),
        );
      const showAliases = tableKeyAliases.get(showId) ?? [showId];

      showAliases.forEach((showAlias) => {
        simulatedTablesByShow.set(showAlias, sortedShowTables);
      });
    });

    const applyTablesToAliases = (showId: string, nextShowTables: DemoTable[]) => {
      const showAliases = [
        showId,
        ...(tableKeyAliases.get(showId) ?? []),
      ];

      tableKeyAliases.forEach((aliases, supabaseShowId) => {
        if (aliases.includes(showId)) {
          showAliases.push(supabaseShowId, ...aliases);
        }
      });

      [...new Set(showAliases)].forEach((showAlias) => {
        simulatedTablesByShow.set(showAlias, nextShowTables);
      });
    };

    const allocate = (
      record: Record<string, string>,
      show: DemoShow | undefined,
      zone: SeatingZone | undefined,
      rowNumber?: number,
    ): DineplanAllocationSimulationResult | null | undefined => {
      if (!show || !zone) {
        return undefined;
      }

      const allocationShowId = show.supabaseId ?? show.id;
      const showTables = simulatedTablesByShow.get(allocationShowId);

      if (!showTables) {
        return null;
      }

      const partySize = Math.max(
        1,
        Math.round(getImportNumber(record.number_of_guests ?? "", 1)),
      );
      const allocation = findBestTableAllocation(
        showTables,
        allocationShowId,
        zone.id,
        partySize,
      );

      if (allocation) {
        const consumedTableIds = new Set([
          allocation.table.id,
          ...allocation.sourceTables.map((table) => table.id),
        ]);
        const nextShowTables = showTables.map((table) =>
          consumedTableIds.has(table.id)
            ? {
                ...table,
                bookingReference:
                  record.booking_reference?.trim() || "dry-run-simulated",
                status: "booked" as const,
              }
            : table,
        );

        applyTablesToAliases(allocationShowId, nextShowTables);

        return {
          isOverflow: false,
          table: allocation.table,
        };
      }

      return undefined;
    };

    allocate.getOverflowPlans = () => [];

    return allocate;
  }

  function resolveImportShow(record: Record<string, string>) {
    const isDineplanRecord =
      normalizeImportLookupValue(record.source_format ?? "") ===
      "dineplan legacy export";
    const showValue = isDineplanRecord
      ? ""
      : normalizeImportLookupValue(record.show ?? "");
    const showDate = record.show_date?.trim();
    const sourceTime = getImportSourceTime(record);
    const location = normalizeImportLocationValue(record.location);
    const baseCandidates = shows.filter((show) => {
      const aliases = getShowImportAliases(show);

      return (
        (showValue ? aliases.includes(showValue) : true) &&
        (showDate ? show.date === showDate : true) &&
        (location ? show.location === location : true)
      );
    });
    const activeCandidates = baseCandidates.filter(
      (show) => !show.archivedAt && show.operationalStatus !== "inactive",
    );
    const candidates = activeCandidates.length > 0 ? activeCandidates : baseCandidates;
    const exactTimeCandidates = sourceTime
      ? candidates.filter((show) => getSouthAfricaShowTime(show) === sourceTime)
      : candidates;
    const matchedShow =
      sourceTime && exactTimeCandidates.length > 0
        ? exactTimeCandidates[0]
        : candidates.length === 1
          ? candidates[0]
          : undefined;
    const warnings: string[] = [];
    const errors: string[] = [];

    if (!showValue && !isDineplanRecord) {
      errors.push("Show is required.");
    }
    if (!showDate) {
      errors.push("Show Date is required.");
    }
    if (!location) {
      errors.push("Location must be Cape Town or Johannesburg.");
    }
    if (showValue && showDate && location && candidates.length === 0) {
      errors.push("No matching active show was found for this show/date/location.");
    }
    if (sourceTime && exactTimeCandidates.length > 1) {
      errors.push("Multiple shows match this source time. Use a more specific show value.");
    }
    if (!sourceTime && candidates.length > 1) {
      errors.push("Multiple shows match this date/location. Add Show Time.");
    }
    if (sourceTime && exactTimeCandidates.length === 0 && candidates.length > 1) {
      errors.push("Source time does not match an available show, and the date/location has multiple candidates.");
    }
    if (sourceTime && matchedShow) {
      const matchedTime = getSouthAfricaShowTime(matchedShow);

      if (matchedTime !== sourceTime) {
        warnings.push(
          `Legacy source time ${sourceTime} will map to ${getImportShowDisplay(matchedShow)}.`,
        );
      }
    }
    if (matchedShow) {
      warnings.push(`Resolved show: ${getImportShowDisplay(matchedShow)}.`);
    }

    return {
      candidates,
      errors,
      show: matchedShow,
      sourceTime,
      warnings,
    };
  }

  function getDineplanFallbackAllocation(
    record: Record<string, string>,
    show: DemoShow | undefined,
    zone: SeatingZone | undefined,
  ): DineplanAllocationSimulationResult | undefined {
    const allocation = getDineplanAutoAllocation(record, show, zone);

    return allocation
      ? {
          isOverflow: false,
          table: allocation.table,
        }
      : undefined;
  }

  function buildDataPortabilityPreview(
    entity: DataPortabilityEntity,
    fileName: string,
    parsed: {
      headers: string[];
      records: Record<string, string>[];
      sourceFormat?: DataPortabilitySourceFormat;
    },
    dineplanAllocate?: ReturnType<typeof createDineplanAllocationSimulator>,
    dineplanGuestList?: DineplanGuestListRecord[] | null,
    dineplanTableSnapshotPayload?: {
      showMappings: DataPortabilityTableSnapshotShowMapping[];
      tables: DataPortabilityTableSnapshotRow[];
    } | null,
    options?: {
      importScope?: string;
    },
  ): DataPortabilityImportPreview {
    const columns = getPortabilityColumns(entity);
    const sourceFormat = parsed.sourceFormat ?? "zingara-template";
    const importScope = options?.importScope ?? "all";
    const records =
      entity === "bookings" &&
      sourceFormat === "dineplan-legacy" &&
      importScope !== "all"
        ? parsed.records.filter(
            (record) => getDineplanImportScopeKey(record) === importScope,
          )
        : parsed.records;
    const receivedColumnKeys = new Set(
      parsed.headers.map((header) => normalizePortabilityKey(header)),
    );
    const missingRequiredColumns = columns
      .filter(
        (column) =>
          sourceFormat === "zingara-template" &&
          column.required &&
          !receivedColumnKeys.has(column.key),
      )
      .map((column) => column.label);
    const issues: DataPortabilityImportIssue[] = [];
    const existingBookingReferences = new Set(
      bookings.map((booking) => booking.reference.trim().toLowerCase()),
    );
    const existingCustomerEmails = new Set(
      [
        ...customerProfiles.map((profile) => profile.customer.email),
        ...liveCustomerRecords.map((customer) => customer.email ?? ""),
      ]
        .filter(Boolean)
        .map((email) => email.trim().toLowerCase()),
    );
    const existingCustomerPhones = new Set(
      [
        ...customerProfiles.map((profile) => profile.customer.phone),
        ...liveCustomerRecords.map((customer) => customer.mobile ?? ""),
      ]
        .filter(Boolean)
        .map(normalizeCustomerPhone),
    );
    const showAliases = new Set(shows.flatMap(getShowImportAliases));
    const locationAliases = new Set([
      "all locations",
      "cape-town",
      "cape town",
      "cape town — the night court",
      "cape town - the night court",
      "johannesburg",
      "joburg",
      "johannesburg — the spring court",
      "johannesburg - the spring court",
    ]);
    const zoneAliases = new Set(
      seatingZones.flatMap((zone) =>
        getZoneSectionLookupTitles(zone.id, zone.title).map(
          normalizeImportLookupValue,
        ),
      ),
    );
    const tableAliases = new Set(
      tables.map((table) => normalizeImportLookupValue(table.tableNumber)),
    );
    const seenBookingReferences = new Set<string>();
    const seenCustomerKeys = new Set<string>();
    const dineplanCapacityGroups =
      entity === "bookings" && sourceFormat === "dineplan-legacy"
        ? buildDineplanCapacityGroups(
            records,
            dineplanTableSnapshotPayload,
          )
        : null;

    const rows = records.map((record, index) => {
      const rowNumber = index + 2;
      const errors: string[] = [];
      const warnings: string[] = [];
      const addIssue = (
        field: string,
        message: string,
        severity: "error" | "warning" = "error",
      ) => {
        const list = severity === "error" ? errors : warnings;

        list.push(`${field}: ${message}`);
        issues.push({ field, message, rowNumber, severity });
      };

      missingRequiredColumns.forEach((field) =>
        addIssue(field, "Missing required column."),
      );

      if (entity === "bookings") {
        const reference = record.booking_reference ?? "";
        const email = record.customer_email ?? "";
        const phone = record.customer_phone ?? "";
        const showValue = record.show ?? "";
        const location = record.location ?? "";
        const zone = record.seating_zone ?? "";
        const table = record.table ?? "";
        const isDineplanRecord = sourceFormat === "dineplan-legacy";
        const showResolution = resolveImportShow(record);
        const guestMatch = isDineplanRecord
          ? getReservationGuestMatch(
              record.customer_name ?? "",
              record.source_guest_id ?? "",
              dineplanGuestList ?? null,
            )
          : null;
        const resolvedZone = zone ? resolveImportZone(record) : undefined;
        const capacityKey =
          isDineplanRecord && showResolution.show && resolvedZone
            ? getImportCapacityKey(showResolution.show, resolvedZone)
            : "";
        const isCapacityConsumingDineplanRecord =
          isDineplanRecord && isDineplanCapacityConsumingRecord(record);
        const isCapacityBlocked =
          Boolean(capacityKey) &&
          Boolean(dineplanCapacityGroups?.conflicts.has(capacityKey));
        const suggestedAllocation = isDineplanRecord
            ? !isCapacityConsumingDineplanRecord
              ? undefined
            : dineplanAllocate
            ? dineplanAllocate(record, showResolution.show, resolvedZone, rowNumber)
            : getDineplanFallbackAllocation(record, showResolution.show, resolvedZone)
          : undefined;
        const resolvedTable =
          !isDineplanRecord && showResolution.show && resolvedZone
            ? findImportTable(record, showResolution.show.id, resolvedZone.id)
            : undefined;
        const resolvedValues = {
          ...record,
          allocation_mode: isDineplanRecord
            ? "Auto-assign best-fit"
            : "Explicit table",
          resolved_show_id: showResolution.show?.id ?? "",
          resolved_show_label: showResolution.show
            ? getImportShowDisplay(showResolution.show)
            : "",
          resolved_show_time: showResolution.show
            ? getSouthAfricaShowTime(showResolution.show)
            : "",
          resolved_source_time: showResolution.sourceTime,
          resolved_table_id:
            resolvedTable?.id ?? suggestedAllocation?.table.id ?? "",
          resolved_table_number:
            resolvedTable?.tableNumber ??
            (isDineplanRecord
              ? suggestedAllocation?.table.tableNumber ?? ""
              : ""),
          resolved_zone_id: resolvedZone?.id ?? "",
          resolved_zone_title: resolvedZone?.title ?? "",
          allocation_state: getDataPortabilityAllocationLabel(
            isDineplanRecord
            ? !isCapacityConsumingDineplanRecord
                ? "NOT_APPLICABLE"
                : suggestedAllocation
                    ? "AUTO_ALLOCATED_EXISTING"
                    : showResolution.show && resolvedZone
                      ? "REQUIRES_FLOOR_ASSIGNMENT"
                      : "UNRESOLVED"
              : "EXPLICIT_TABLE",
          ),
          capacity_status:
            isDineplanRecord && capacityKey
              ? isCapacityBlocked
                ? `Overflow required: ${
                    (dineplanCapacityGroups?.existingActivePax.get(capacityKey) ??
                      0) +
                    (dineplanCapacityGroups?.incomingActivePax.get(capacityKey) ??
                      0)
                  } guests / ${
                    dineplanCapacityGroups?.capacities.get(capacityKey) ?? 0
                  } standard seats`
                : "Within configured zone capacity"
              : "",
          floor_assignment_required:
            isDineplanRecord &&
            isCapacityConsumingDineplanRecord &&
            showResolution.show &&
            resolvedZone &&
            !suggestedAllocation
              ? "Yes"
              : "No",
          guest_match_status: guestMatch?.status ?? "",
          guest_match_candidates: guestMatch
            ? String(guestMatch.candidates.length)
            : "",
          matched_guest_name: guestMatch?.match?.fullName ?? "",
          matched_email_available: guestMatch?.match
            ? maskContactAvailability(guestMatch.match.email)
            : "",
          matched_mobile_available: guestMatch?.match
            ? maskContactAvailability(guestMatch.match.phone)
            : "",
          matched_email_consent: guestMatch?.match
            ? getConsentStatus(guestMatch.match.emailOptIn)
            : "",
          matched_sms_consent: guestMatch?.match
            ? getConsentStatus(guestMatch.match.smsOptIn)
            : "",
          suggested_table:
            suggestedAllocation?.table.tableNumber ??
            (isDineplanRecord
              ? isCapacityConsumingDineplanRecord
                ? "Requires floor assignment"
                : "Not applicable"
              : ""),
          proposed_overflow_table:
            "No",
          proposed_overflow_capacity: "",
        };

        if (!reference) {
          addIssue("Booking Reference", "Required.");
        } else if (!isLikelyBookingReference(reference)) {
          addIssue("Booking Reference", "Use a valid booking reference.");
        }

        if (reference) {
          const normalizedReference = reference.trim().toLowerCase();

          if (seenBookingReferences.has(normalizedReference)) {
            addIssue("Booking Reference", "Duplicate row in this file.");
          }
          seenBookingReferences.add(normalizedReference);
        }

        if (!record.customer_name) {
          addIssue("Customer Name", "Required.");
        }
        if (sourceFormat === "dineplan-legacy" && !record.location) {
          addIssue(
            "Source Location",
            "Select JHB or CPT before uploading a Dineplan legacy export.",
          );
        }
        if (!isDineplanRecord && !email && !phone) {
          addIssue("Customer Email", "Email or phone is required.");
        }
        if (!isValidPortabilityEmail(email)) {
          addIssue("Customer Email", "Invalid email format.");
        }
        if (!isValidPortabilityPhone(phone)) {
          addIssue("Customer Phone", "Invalid phone format.");
        }
        if (!isValidPortabilityDate(record.show_date ?? "")) {
          addIssue("Show Date", "Invalid date format.");
        }
        if (!isValidPortabilityDate(record.booking_date ?? "")) {
          addIssue("Booking Date", "Invalid date format.");
        }
        ["number_of_guests", "booking_total", "amount_paid", "balance_due"].forEach(
          (field) => {
            if (!isValidPortabilityNumber(record[field] ?? "")) {
              addIssue(field, "Must be numeric.");
            }
          },
        );
        showResolution.errors.forEach((message) => addIssue("Show", message));
        showResolution.warnings.forEach((message) =>
          addIssue("Show", message, "warning"),
        );
        if (
          showValue &&
          !showAliases.has(normalizeImportLookupValue(showValue)) &&
          !showResolution.show
        ) {
          addIssue("Show", "Unknown show.");
        }
        if (
          location &&
          !locationAliases.has(normalizeImportLookupValue(location))
        ) {
          addIssue("Location", "Unknown location.");
        }
        if (zone && !zoneAliases.has(normalizeImportLookupValue(zone))) {
          addIssue("Seating Zone", "Unknown seating zone.");
        }
        if (zone && !resolvedZone) {
          addIssue("Seating Zone", "No matching seating zone was found.");
        }
        if (!isDineplanRecord && table && !tableAliases.has(normalizeImportLookupValue(table))) {
          addIssue("Table", "Unknown table.");
        }
        if (!isDineplanRecord && table && showResolution.show && resolvedZone && !resolvedTable) {
          addIssue(
            "Table",
            "No matching table was found for the resolved show and seating zone.",
          );
        }
        if (
          isDineplanRecord &&
          showResolution.show &&
          resolvedZone &&
          isCapacityConsumingDineplanRecord &&
          suggestedAllocation === null
        ) {
          addIssue(
            "Allocation",
            "Authoritative table inventory could not be loaded for the resolved show.",
          );
        }
        if (
          isDineplanRecord &&
          showResolution.show &&
          resolvedZone &&
          isCapacityConsumingDineplanRecord &&
          isCapacityBlocked
        ) {
          addIssue(
            "Capacity Health",
            `Resolved performance/zone needs operational overflow: ${
              (dineplanCapacityGroups?.existingActivePax.get(capacityKey) ??
                0) +
              (dineplanCapacityGroups?.incomingActivePax.get(capacityKey) ??
                0)
            } guests against ${
              dineplanCapacityGroups?.capacities.get(capacityKey) ?? 0
            } standard online seats. This is a grouped preflight warning, not an individual row rejection.`,
            "warning",
          );
        }
        if (
          isDineplanRecord &&
          showResolution.show &&
          resolvedZone &&
          isCapacityConsumingDineplanRecord &&
          suggestedAllocation === undefined
        ) {
          addIssue(
            "Floor Assignment",
            "Booking entitlement is valid, but no existing or permitted overflow table fit is available. Import would require manual Floor assignment.",
            "warning",
          );
        }
        if (isDineplanRecord && !isCapacityConsumingDineplanRecord) {
          addIssue(
            "Allocation",
            "Cancelled or no-show legacy booking will import without consuming table allocation.",
            "warning",
          );
        }
        if (isDineplanRecord) {
          addIssue(
            "Table",
            `Source table ${table || "not recorded"} retained as legacy metadata; Zingara allocation uses authoritative table inventory only.`,
            "warning",
          );
        }
        if (
          !isDineplanRecord &&
          ((email && !existingCustomerEmails.has(email.trim().toLowerCase())) ||
            (phone && !existingCustomerPhones.has(normalizeCustomerPhone(phone))))
        ) {
          addIssue(
            "Customer",
            "Unknown customer; review whether the confirmed import should create or link this record.",
            "warning",
          );
        }

        const valid = errors.length === 0;
        const action: DataPortabilityImportAction = !valid
          ? "Skip"
          : existingBookingReferences.has(reference.trim().toLowerCase())
            ? "Update"
            : "Create";

        return {
          action,
          errors,
          rowNumber,
          valid,
          values: resolvedValues,
          warnings,
        };
      }

      const email = record.email ?? "";
      const phone = record.phone ?? "";
      const customerKey =
        email.trim().toLowerCase() || normalizeCustomerPhone(phone);

      if (!record.customer_name) {
        addIssue("Customer Name", "Required.");
      }
      if (!email && !phone) {
        addIssue("Email", "Email or phone is required.");
      }
      if (!isValidPortabilityEmail(email)) {
        addIssue("Email", "Invalid email format.");
      }
      if (!isValidPortabilityPhone(phone)) {
        addIssue("Phone", "Invalid phone format.");
      }
      if (!isValidPortabilityDate(record.last_booking ?? "")) {
        addIssue("Last Booking", "Invalid date format.");
      }
      ["number_of_bookings", "total_guests"].forEach((field) => {
        if (!isValidPortabilityNumber(record[field] ?? "")) {
          addIssue(field, "Must be numeric.");
        }
      });
      if (customerKey) {
        if (seenCustomerKeys.has(customerKey)) {
          addIssue("Customer", "Duplicate row in this file.");
        }
        seenCustomerKeys.add(customerKey);
      }

      const valid = errors.length === 0;
      const normalizedPhone = normalizeCustomerPhone(phone);
      const action: DataPortabilityImportAction = !valid
        ? "Skip"
        : existingCustomerEmails.has(email.trim().toLowerCase()) ||
            existingCustomerPhones.has(normalizedPhone)
          ? "Update"
          : "Create";

      return {
        action,
        errors,
        rowNumber,
        valid,
        values: record,
        warnings,
      };
    });
    const performanceSummary =
      entity === "bookings" && sourceFormat === "dineplan-legacy"
        ? Array.from(
            rows
              .reduce((summary, row) => {
                const values = row.values as Record<string, string>;
                const date = values.source_date || values.show_date || "";
                const time =
                  values.resolved_show_time ||
                  values.source_time ||
                  values.show_time ||
                  "";
                const location = values.location || "";
                const resolvedLabel = values.resolved_show_label || "Unresolved";
                const scopeKey = getDineplanImportScopeKey(values);
                const compactLabel = getCompactImportPerformanceLabel({
                  date,
                  location,
                  time,
                });
                const key = `${scopeKey}|${resolvedLabel}`;
                const existing = summary.get(key);
                const rowStatus = values.resolved_show_id
                  ? "Resolved"
                  : row.errors.some((error) => error.includes("multiple matching shows"))
                    ? "Ambiguous"
                    : "Unresolved";

                if (existing) {
                  existing.bookingCount += 1;
                  if (existing.status !== "Unresolved") {
                    existing.status =
                      existing.status === "Ambiguous" || rowStatus === "Ambiguous"
                        ? "Ambiguous"
                        : rowStatus;
                  }
                } else {
                  summary.set(key, {
                    bookingCount: 1,
                    compactLabel,
                    date,
                    location,
                    resolvedLabel,
                    scopeKey,
                    status: rowStatus,
                    time,
                  });
                }

                return summary;
              }, new Map<string, NonNullable<DataPortabilityImportPreview["performanceSummary"]>[number]>())
              .values(),
          ).sort((first, second) =>
            `${getImportPerformanceLocationAlias(first.location)} ${first.date} ${first.time}`.localeCompare(
              `${getImportPerformanceLocationAlias(second.location)} ${second.date} ${second.time}`,
            ),
          )
        : undefined;
    const guestMatches =
      entity === "bookings" && sourceFormat === "dineplan-legacy"
        ? rows.filter((row) => row.values.guest_match_status === "MATCHED").length
        : undefined;
    const ambiguousGuestMatches =
      entity === "bookings" && sourceFormat === "dineplan-legacy"
        ? rows.filter((row) => row.values.guest_match_status === "AMBIGUOUS").length
        : undefined;
    const unmatchedGuests =
      entity === "bookings" && sourceFormat === "dineplan-legacy"
        ? rows.filter((row) => row.values.guest_match_status === "NO MATCH").length
        : undefined;
    const noGuestListRows =
      entity === "bookings" && sourceFormat === "dineplan-legacy"
        ? rows.filter((row) => row.values.guest_match_status === "NO GUEST LIST").length
        : undefined;
    const autoAllocatedRows =
      entity === "bookings" && sourceFormat === "dineplan-legacy"
        ? rows.filter(
            (row) => row.values.allocation_state === "Assigned to Existing Table",
          ).length
        : undefined;
    const existingAllocatedRows =
      entity === "bookings" && sourceFormat === "dineplan-legacy"
        ? rows.filter(
            (row) => row.values.allocation_state === "Assigned to Existing Table",
          ).length
        : undefined;
    const requiresFloorAssignmentRows =
      entity === "bookings" && sourceFormat === "dineplan-legacy"
        ? rows.filter(
            (row) =>
              row.values.allocation_state === "Requires floor assignment",
          ).length
        : undefined;
    const capacityConflictSummary =
      entity === "bookings" && sourceFormat === "dineplan-legacy"
        ? Array.from(dineplanCapacityGroups?.conflicts ?? [])
            .map((key) => {
              const metadata =
                dineplanCapacityGroups?.conflictMetadata.get(key);
              const legacyPax =
                dineplanCapacityGroups?.incomingActivePax.get(key) ?? 0;
              const existingPax =
                dineplanCapacityGroups?.existingActivePax.get(key) ?? 0;
              const capacity = dineplanCapacityGroups?.capacities.get(key) ?? 0;
              const requiredPax = legacyPax + existingPax;

              return {
                affectedRows: metadata?.affectedRows ?? 0,
                capacity,
                date: metadata?.date ?? "",
                existingPax,
                legacyPax,
                location: metadata?.location ?? "",
                requiredPax,
                resolvedLabel: metadata?.resolvedLabel ?? "Resolved show",
                shortagePax: Math.max(requiredPax - capacity, 0),
                zone: metadata?.zone ?? "Unknown zone",
              };
            })
            .sort((left, right) =>
              `${left.date} ${left.zone}`.localeCompare(
                `${right.date} ${right.zone}`,
              ),
          )
        : undefined;
    const overflowPlanSummary = undefined;
    const allocationSummary =
      entity === "bookings" && sourceFormat === "dineplan-legacy"
        ? [
            {
              count: existingAllocatedRows ?? 0,
              label: "Assigned To Existing Tables",
              tone: "success" as const,
            },
            {
              count: requiresFloorAssignmentRows ?? 0,
              label: "Requires Floor Assignment",
              tone:
                (requiresFloorAssignmentRows ?? 0) > 0
                  ? ("warning" as const)
                  : ("neutral" as const),
            },
            {
              count: capacityConflictSummary?.length ?? 0,
              label: "Over-Capacity Zones",
              tone:
                (capacityConflictSummary?.length ?? 0) > 0
                  ? ("warning" as const)
                  : ("neutral" as const),
            },
            {
              count: rows.filter(
                (row) => row.values.allocation_state === "Not applicable",
              ).length,
              label: "No Allocation Required",
              tone: "info" as const,
            },
          ]
        : undefined;

    return {
      allocationSummary,
      ambiguousGuestMatches,
      autoAllocatedRows,
      capacityConflictSummary,
      duplicateRows: rows.filter((row) =>
        row.errors.some((error) => error.includes("Duplicate row")),
      ).length,
      entity,
      fileName,
      guestMatches,
      headers: parsed.headers,
      invalidRows: rows.filter((row) => !row.valid).length,
      issues,
      missingRequiredColumns,
      noGuestListRows,
      overflowPlanSummary,
      performanceSummary,
      requiresFloorAssignmentRows,
      rows,
      rowsDetected: rows.length,
      sourceFormat,
      unmatchedGuests,
      validRows: rows.filter((row) => row.valid).length,
      wouldCreate: rows.filter((row) => row.action === "Create").length,
      wouldSkip: rows.filter((row) => row.action === "Skip").length,
      wouldUpdate: rows.filter((row) => row.action === "Update").length,
    };
  }

  async function handleDataPortabilityImportFile(
    event: ChangeEvent<HTMLInputElement>,
  ) {
    const file = event.target.files?.[0];

    setDataPortabilityImportError("");
    setDataPortabilityImportStatus("");

    if (!file) {
      return;
    }

    try {
      const parsed = await parsePortabilityFile(
        file,
        activeDataPortabilityEntity,
        dataPortabilitySourceLocation,
      );
      const importSource: DataPortabilityImportSourceState = {
        entity: activeDataPortabilityEntity,
        fileName: file.name,
        parsed,
      };
      let dineplanAllocate:
        | ReturnType<typeof createDineplanAllocationSimulator>
        | undefined;
      let dineplanTableSnapshots:
        | {
            showMappings: DataPortabilityTableSnapshotShowMapping[];
            tables: DataPortabilityTableSnapshotRow[];
          }
        | undefined;

      if (
        activeDataPortabilityEntity === "bookings" &&
        parsed.sourceFormat === "dineplan-legacy"
      ) {
        const resolvedShowIds = [
          ...new Set(
            parsed.records
              .map((record) => {
                const show = resolveImportShow(record).show;

                return show ? show.supabaseId ?? show.id : "";
              })
              .filter(Boolean),
          ),
        ];
        dineplanTableSnapshots =
          await loadDataPortabilityTableSnapshots(resolvedShowIds);

        dineplanAllocate =
          createDineplanAllocationSimulator(dineplanTableSnapshots);
      }

      const preview = buildDataPortabilityPreview(
        activeDataPortabilityEntity,
        file.name,
        parsed,
        dineplanAllocate,
        dataPortabilityGuestList?.records ?? null,
        dineplanTableSnapshots,
        { importScope: "all" },
      );

      setDataPortabilityImportSource(importSource);
      setDataPortabilityPreview(preview);
      setDataPortabilityImportScope("all");
      setDataPortabilityReviewFilter("all");
      setDataPortabilityGuestMatchFilter("all");
      setDataPortabilityPerformanceFilter("all");
      setDataPortabilityImportResult(null);
      setDataPortabilityImportStatus(
        `${preview.rowsDetected} row${preview.rowsDetected === 1 ? "" : "s"} parsed for dry run. No data has been written.`,
      );
    } catch (error) {
      setDataPortabilityImportError(
        error instanceof Error
          ? error.message
          : "The file could not be parsed.",
      );
    } finally {
      event.target.value = "";
    }
  }

  async function handleDataPortabilityImportScopeChange(importScope: string) {
    if (!dataPortabilityImportSource) {
      setDataPortabilityImportScope(importScope);
      return;
    }

    setDataPortabilityImportError("");
    setDataPortabilityImportStatus("");
    setDataPortabilityImportScope(importScope);

    try {
      let dineplanAllocate:
        | ReturnType<typeof createDineplanAllocationSimulator>
        | undefined;
      let dineplanTableSnapshots:
        | {
            showMappings: DataPortabilityTableSnapshotShowMapping[];
            tables: DataPortabilityTableSnapshotRow[];
          }
        | undefined;

      if (
        dataPortabilityImportSource.entity === "bookings" &&
        dataPortabilityImportSource.parsed.sourceFormat === "dineplan-legacy"
      ) {
        const scopedRecords =
          importScope === "all"
            ? dataPortabilityImportSource.parsed.records
            : dataPortabilityImportSource.parsed.records.filter(
                (record) => getDineplanImportScopeKey(record) === importScope,
              );
        const resolvedShowIds = [
          ...new Set(
            scopedRecords
              .map((record) => {
                const show = resolveImportShow(record).show;

                return show ? show.supabaseId ?? show.id : "";
              })
              .filter(Boolean),
          ),
        ];

        dineplanTableSnapshots =
          await loadDataPortabilityTableSnapshots(resolvedShowIds);
        dineplanAllocate =
          createDineplanAllocationSimulator(dineplanTableSnapshots);
      }

      const preview = buildDataPortabilityPreview(
        dataPortabilityImportSource.entity,
        dataPortabilityImportSource.fileName,
        dataPortabilityImportSource.parsed,
        dineplanAllocate,
        dataPortabilityGuestList?.records ?? null,
        dineplanTableSnapshots,
        { importScope },
      );

      setDataPortabilityPreview(preview);
      setDataPortabilityReviewFilter("all");
      setDataPortabilityGuestMatchFilter("all");
      setDataPortabilityPerformanceFilter("all");
      setDataPortabilityImportResult(null);
      setDataPortabilityImportStatus(
        importScope === "all"
          ? `${preview.rowsDetected} row${preview.rowsDetected === 1 ? "" : "s"} parsed for full-month dry run. No data has been written.`
          : `${preview.rowsDetected} row${preview.rowsDetected === 1 ? "" : "s"} parsed for selected import scope. No data has been written.`,
      );
    } catch (error) {
      setDataPortabilityImportError(
        error instanceof Error
          ? error.message
          : "The selected import scope could not be recalculated.",
      );
    }
  }

  async function handleDineplanGuestListFile(
    event: ChangeEvent<HTMLInputElement>,
  ) {
    const file = event.target.files?.[0];

    setDataPortabilityImportError("");
    setDataPortabilityImportStatus("");

    if (!file) {
      return;
    }

    try {
      const records = await parseDineplanGuestListFile(file);

      setDataPortabilityGuestList({ fileName: file.name, records });
      setDataPortabilityImportSource(null);
      setDataPortabilityImportScope("all");
      setDataPortabilityPreview(null);
      setDataPortabilityImportResult(null);
      setDataPortabilityImportStatus(
        `${records.length} Dineplan guest list row${records.length === 1 ? "" : "s"} loaded for the next dry run. No data has been written.`,
      );
    } catch (error) {
      setDataPortabilityImportError(
        error instanceof Error
          ? error.message
          : "The guest list file could not be parsed.",
      );
    } finally {
      event.target.value = "";
    }
  }

  function getDataPortabilityLogFilename() {
    const timestamp = new Date()
      .toISOString()
      .slice(0, 16)
      .replace("T", "_")
      .replace(":", "-");

    return `Import_Result_${timestamp}.xlsx`;
  }

  function getImportBookingStatus(value: string): BookingStatus {
    const normalizedValue = normalizeImportLookupValue(value);
    const matchedStatus = Object.entries(bookingStatusLabels).find(
      ([status, label]) =>
        normalizeImportLookupValue(status) === normalizedValue ||
        normalizeImportLookupValue(label) === normalizedValue,
    )?.[0] as BookingStatus | undefined;

    return matchedStatus && isValidBookingStatus(matchedStatus)
      ? matchedStatus
      : "pending-payment";
  }

  function getImportPaymentStatus(value: string): PaymentStatus {
    const normalizedValue = normalizeImportLookupValue(value);
    const matchedStatus = Object.entries(paymentStatusLabels).find(
      ([status, label]) =>
        normalizeImportLookupValue(status) === normalizedValue ||
        normalizeImportLookupValue(label) === normalizedValue,
    )?.[0] as PaymentStatus | undefined;

    return matchedStatus ?? "pending-payment";
  }

  function getImportBoolean(value: string) {
    return ["1", "true", "yes", "y"].includes(
      normalizeImportLookupValue(value),
    );
  }

  function getImportNumber(value: string, fallback = 0) {
    const parsedValue = Number(String(value).replace(/[^\d.-]/g, ""));

    return Number.isFinite(parsedValue) ? parsedValue : fallback;
  }

  function findImportShow(record: Record<string, string>) {
    return resolveImportShow(record).show;
  }

  function findImportZone(record: Record<string, string>) {
    const zoneValue = normalizeImportLookupValue(record.seating_zone ?? "");

    return (
      seatingZones.find(
        (zone) => {
          const aliases = [
            zone.id,
            ...getZoneSectionLookupTitles(zone.id, zone.title),
          ].map(normalizeImportLookupValue);

          return aliases.includes(zoneValue);
        },
      ) ?? seatingZones[0]
    );
  }

  function resolveImportZone(record: Record<string, string>) {
    const zoneValue = normalizeImportLookupValue(record.seating_zone ?? "");

    if (!zoneValue) {
      return undefined;
    }

    return seatingZones.find((zone) =>
      getImportZoneAliases(zone).includes(zoneValue),
    );
  }

  function findImportTable(
    record: Record<string, string>,
    showId: string,
    zoneId: SeatingZoneId,
  ) {
    const tableValue = normalizeImportLookupValue(record.table ?? "");

    return (
      tables.find(
        (table) =>
          table.showId === showId &&
          table.zoneId === zoneId &&
          normalizeImportLookupValue(table.tableNumber) === tableValue,
      ) ??
      tables.find(
        (table) =>
          table.zoneId === zoneId &&
          normalizeImportLookupValue(table.tableNumber) === tableValue,
      )
    );
  }

  function getDineplanAutoAllocation(
    record: Record<string, string>,
    show: DemoShow | undefined,
    zone: SeatingZone | undefined,
  ) {
    if (!show || !zone) {
      return undefined;
    }

    return findBestTableAllocation(
      tables,
      show.id,
      zone.id,
      Math.max(1, Math.round(getImportNumber(record.number_of_guests ?? "", 1))),
    );
  }

  function buildImportedBooking(
    row: DataPortabilityPreviewRow,
    existingBooking?: DemoBooking,
  ) {
    const record = row.values;
    const show = findImportShow(record);
    const zone = findImportZone(record);
    const table = show
      ? findImportTable(record, show.id, zone.id)
      : undefined;
    const now = new Date().toISOString();
    const totalPrice = getImportNumber(
      record.booking_total ?? "",
      existingBooking?.totalPrice ?? 0,
    );
    const amountPaid = getImportNumber(
      record.amount_paid ?? "",
      existingBooking?.amountPaid ?? 0,
    );
    const balanceDue = getImportNumber(
      record.balance_due ?? "",
      existingBooking?.balanceDue ?? Math.max(totalPrice - amountPaid, 0),
    );
    const partySize = Math.max(
      1,
      Math.round(
        getImportNumber(
          record.number_of_guests ?? "",
          existingBooking?.partySize ?? 1,
        ),
      ),
    );
    const reference =
      record.booking_reference?.trim() || existingBooking?.reference || "";
    const bookingStatus = getImportBookingStatus(record.booking_status ?? "");
    const importedPaymentStatus = getImportPaymentStatus(
      record.payment_status ?? "",
    );
    const paymentStatus =
      existingBooking && row.action === "Update"
        ? (existingBooking.paymentStatus ?? "pending-payment")
        : getImportBoolean(record.complimentary_flag ?? "")
          ? "comp-vip"
          : importedPaymentStatus;
    const nextBooking: DemoBooking = {
      addons: existingBooking?.addons ?? [],
      addonsTotal: existingBooking?.addonsTotal ?? 0,
      amountPaid:
        existingBooking && row.action === "Update"
          ? existingBooking.amountPaid
          : amountPaid,
      balanceDue:
        existingBooking && row.action === "Update"
          ? existingBooking.balanceDue
          : balanceDue,
      bookingDate: show ? getShowLabel(show) : (existingBooking?.bookingDate ?? ""),
      cancellationReason: existingBooking?.cancellationReason ?? "",
      cancelledAt: existingBooking?.cancelledAt,
      communicationHistory: existingBooking?.communicationHistory ?? [],
      corporatePaymentLinkSentAt: existingBooking?.corporatePaymentLinkSentAt,
      corporatePaymentToken: existingBooking?.corporatePaymentToken,
      createdAt:
        existingBooking?.createdAt || record.booking_date?.trim() || now,
      customer: {
        email:
          record.customer_email?.trim() || existingBooking?.customer.email || "",
        name:
          record.customer_name?.trim() ||
          existingBooking?.customer.name ||
          "Imported Guest",
        phone:
          record.customer_phone?.trim() || existingBooking?.customer.phone || "",
      },
      discountAmount: existingBooking?.discountAmount ?? 0,
      guestTickets: existingBooking?.guestTickets,
      lifecycleHistory: existingBooking?.lifecycleHistory ?? [],
      operationalNotes:
        record.guest_notes?.trim() ||
        existingBooking?.operationalNotes ||
        "",
      partySize,
      paymentOption: existingBooking?.paymentOption ?? "deposit",
      paymentStatus,
      pricePerPerson:
        partySize > 0
          ? Math.round(totalPrice / partySize)
          : existingBooking?.pricePerPerson ?? 0,
      promoCode: existingBooking?.promoCode,
      promoLabel: existingBooking?.promoLabel,
      reference,
      refundNotes: existingBooking?.refundNotes ?? "",
      serviceFeeAmount: existingBooking?.serviceFeeAmount ?? 0,
      showId: show?.id ?? existingBooking?.showId,
      source:
        record.corporate_flag &&
        getImportBoolean(record.corporate_flag)
          ? "corporate-direct"
          : existingBooking?.source ?? "admin",
      status: bookingStatus,
      subtotalPrice: existingBooking?.subtotalPrice ?? totalPrice,
      tableId: table?.id ?? existingBooking?.tableId ?? "imported-table",
      tableNumber:
        table?.tableNumber ||
        record.table?.trim() ||
        existingBooking?.tableNumber ||
        "Not recorded",
      ticketCode: existingBooking?.ticketCode ?? createTicketCode(reference),
      ticketIssuedAt: existingBooking?.ticketIssuedAt ?? now,
      totalPrice: existingBooking && row.action === "Update"
        ? existingBooking.totalPrice
        : totalPrice,
      zoneId: zone.id,
      zoneTitle: zone.title,
    };

    return {
      booking: nextBooking,
      missing: [
        !reference ? "Booking Reference" : "",
        !show ? "Show" : "",
        !record.customer_name?.trim() && !existingBooking?.customer.name
          ? "Customer Name"
          : "",
      ].filter(Boolean),
    };
  }

  function getDataPortabilityPreviewColumns(entity: DataPortabilityEntity) {
    if (entity === "bookings" && dataPortabilityPreview?.sourceFormat === "dineplan-legacy") {
      return [
        { key: "source_booking_reference", label: "Source Reference" },
        { key: "customer_name", label: "Customer Name" },
        { key: "guest_match_status", label: "Guest Match" },
        { key: "matched_guest_name", label: "Matched Guest" },
        { key: "matched_email_available", label: "Email" },
        { key: "matched_mobile_available", label: "Mobile" },
        { key: "matched_email_consent", label: "Email Consent" },
        { key: "matched_sms_consent", label: "SMS Consent" },
        { key: "number_of_guests", label: "Guests" },
        { key: "source_date", label: "Source Date" },
        { key: "source_time", label: "Source Time" },
        { key: "source_seating_area", label: "Source Seating" },
        { key: "source_table", label: "Source Table" },
        { key: "resolved_show_label", label: "Resolved Show" },
        { key: "resolved_zone_title", label: "Resolved Zone" },
        { key: "allocation_mode", label: "Allocation" },
        { key: "allocation_state", label: "Allocation State" },
        { key: "suggested_table", label: "Suggested Table" },
        { key: "capacity_status", label: "Capacity" },
        { key: "floor_assignment_required", label: "Floor Assignment" },
        { key: "booking_status", label: "Booking Status" },
        { key: "payment_status", label: "Payment Status" },
        { key: "booking_total", label: "Booking Total" },
        { key: "amount_paid", label: "Paid" },
        { key: "source_total_refunded", label: "Refunded" },
        { key: "balance_due", label: "Balance Due" },
        { key: "source_legacy_total_balance", label: "Legacy Total Balance" },
      ];
    }

    const sourceColumns = getPortabilityColumns(entity)
      .slice(0, 5)
      .map((column) => ({ key: column.key, label: column.label }));

    if (entity !== "bookings") {
      return sourceColumns;
    }

    return [
      ...sourceColumns,
      { key: "resolved_show_label", label: "Resolved Show" },
      { key: "resolved_zone_title", label: "Resolved Zone" },
      { key: "resolved_table_number", label: "Resolved Table" },
    ];
  }

  function isControlledDineplanImportPreview() {
    if (
      !dataPortabilityPreview ||
      dataPortabilityPreview.entity !== "bookings" ||
      dataPortabilityPreview.sourceFormat !== "dineplan-legacy" ||
      dataPortabilityPreview.invalidRows > 0 ||
      dataPortabilityPreview.rows.length !==
        controlledDineplanImportReferenceSet.size
    ) {
      return false;
    }

    const seenReferences = new Set<string>();

    return dataPortabilityPreview.rows.every((row) => {
      const reference = row.values.booking_reference?.trim().toLowerCase() ?? "";

      if (
        !row.valid ||
        row.action === "Skip" ||
        !controlledDineplanImportReferenceSet.has(reference) ||
        seenReferences.has(reference)
      ) {
        return false;
      }

      seenReferences.add(reference);

      return (
        row.values.show_date === controlledDineplanImportDate &&
        row.values.location === controlledDineplanImportLocation
      );
    });
  }

  function downloadDataPortabilityResultLog(result: DataPortabilityImportResult) {
    const sheet: ExportSheet = {
      columns: [
        "Row",
        "Action",
        "Status",
        "Message",
        "Reference",
        "Customer",
        "Warnings",
        "Errors",
      ],
      name: "Import Result",
      rows: result.logRows.map((row) => ({
        Action: row.action,
        Customer: row.customer,
        Errors: row.errors,
        Message: row.message,
        Reference: row.reference,
        Row: row.row,
        Status: row.status,
        Warnings: row.warnings,
      })),
      summary: [
        ["Dataset", dataPortabilityEntityLabels[result.dataset]],
        ["Result", result.result],
        ["Records", result.records],
        ["Created", result.created],
        ["Updated", result.updated],
        ["Skipped", result.skipped],
        ["Failed", result.failed],
        ["Restore Point", result.restorePointId],
      ],
    };

    downloadBlobFile(getDataPortabilityLogFilename(), createXlsxBlob([sheet]));
  }

  function mapDataPortabilityHistoryRow(
    row: DataPortabilityImportHistoryApiRow,
  ): DataPortabilityImportHistoryEntry {
    const rawLogRows = Array.isArray(row.result_log) ? row.result_log : [];

    return {
      completedAt: row.completed_at ?? row.started_at,
      created: row.created_count,
      dataset: row.dataset,
      durationMs: row.duration_ms,
      failed: row.failed_count,
      finalStatus: row.final_status,
      fileName: row.original_file_name,
      id: row.id,
      logRows: rawLogRows.map((logRow) => {
        const record = logRow as Partial<DataPortabilityImportLogRow>;

        return {
          action: record.action ?? "Skip",
          customer: record.customer ?? "",
          errors: Array.isArray(record.errors)
            ? record.errors.join("; ")
            : record.errors ?? "",
          message: record.message ?? "",
          reference: record.reference ?? "",
          row: Number(record.row ?? 0),
          status: record.status ?? "Success",
          warnings: Array.isArray(record.warnings)
            ? record.warnings.join("; ")
            : record.warnings ?? "",
        };
      }),
      records: row.total_rows,
      restorePointId: row.restore_point_id ?? "Not recorded",
      result:
        row.final_status === "rolled_back"
          ? "failed"
          : row.final_status === "success"
            ? "success"
            : "partial",
      skipped: row.skipped_count,
      updated: row.updated_count,
      user:
        row.staff_profiles?.email ??
        row.staff_profiles?.full_name ??
        "Staff user",
    };
  }

  async function refreshDataPortabilityHistory() {
    try {
      setDataPortabilityHistoryWarning("");
      const payload = await fetchSupabaseApi<{
        rows: DataPortabilityImportHistoryApiRow[];
      }>("/api/admin/data-portability/imports");

      setDataPortabilityImportHistory(
        (payload.rows ?? []).map(mapDataPortabilityHistoryRow),
      );
    } catch (error) {
      console.error("[Zingara data portability] History load failed", error);
      setDataPortabilityHistoryWarning(
        "Import history could not be loaded. Dry Run remains available.",
      );
    }
  }

  async function executeDataPortabilityImport() {
    if (!canViewDataPortability || !dataPortabilityPreview || isDataPortabilityImporting) {
      return;
    }

    setIsDataPortabilityImporting(true);
    setDataPortabilityImportError("");
    setDataPortabilityImportStatus("Creating durable restore point...");
    setDataPortabilityImportResult(null);

    try {
      let dineplanAllocate:
        | ReturnType<typeof createDineplanAllocationSimulator>
        | undefined;
      let dineplanTableSnapshots:
        | {
            showMappings: DataPortabilityTableSnapshotShowMapping[];
            tables: DataPortabilityTableSnapshotRow[];
          }
        | undefined;

      if (
        dataPortabilityPreview.entity === "bookings" &&
        dataPortabilityPreview.sourceFormat === "dineplan-legacy"
      ) {
        const resolvedShowIds = [
          ...new Set(
            dataPortabilityPreview.rows
              .map((row) => {
                const show = resolveImportShow(row.values).show;

                return show ? show.supabaseId ?? show.id : "";
              })
              .filter(Boolean),
          ),
        ];
        dineplanTableSnapshots =
          await loadDataPortabilityTableSnapshots(resolvedShowIds);

        dineplanAllocate =
          createDineplanAllocationSimulator(dineplanTableSnapshots);
      }

      const revalidatedPreview = buildDataPortabilityPreview(
        dataPortabilityPreview.entity,
        dataPortabilityPreview.fileName,
        {
          headers: dataPortabilityPreview.headers,
          records: dataPortabilityPreview.rows.map((row) => row.values),
          sourceFormat: dataPortabilityPreview.sourceFormat,
        },
        dineplanAllocate,
        dataPortabilityGuestList?.records ?? null,
        dineplanTableSnapshots,
      );
      const previewSignature = JSON.stringify(
        dataPortabilityPreview.rows.map((row) => ({
          action: row.action,
          errors: row.errors,
          rowNumber: row.rowNumber,
          valid: row.valid,
          warnings: row.warnings,
        })),
      );
      const revalidatedSignature = JSON.stringify(
        revalidatedPreview.rows.map((row) => ({
          action: row.action,
          errors: row.errors,
          rowNumber: row.rowNumber,
          valid: row.valid,
          warnings: row.warnings,
        })),
      );

      if (previewSignature !== revalidatedSignature) {
        throw new Error(
          "Validation changed after preview. Clear the preview and upload the file again.",
        );
      }

      setDataPortabilityImportStatus("Transactional import in progress...");
      const payload = await fetchSupabaseApi<{
        result: {
          completedAt?: string;
          created: number;
          dataset: DataPortabilityEntity;
          durationMs: number;
          failed: number;
          id: string;
          records: number;
          restorePointId: string;
          resultLog?: Array<{
            action: DataPortabilityImportAction;
            customer?: string;
            errors?: string[] | string;
            message?: string;
            reference?: string;
            row?: number | string;
            status?: "Failed" | "Skipped" | "Success";
            warnings?: string[] | string;
          }>;
          skipped: number;
          startedAt?: string;
          status: "success";
          updated: number;
        };
      }>("/api/admin/data-portability/imports", {
        body: {
          action: "execute",
          dataset: dataPortabilityPreview.entity,
          fileName: dataPortabilityPreview.fileName,
          rows: dataPortabilityPreview.rows,
        },
        method: "POST",
      });
      const importResult = payload.result;
      const completedAt =
        importResult.completedAt ?? new Date().toISOString();
      const startedAt = importResult.startedAt ?? completedAt;
      const logRows = (importResult.resultLog ?? []).map((row) => ({
        action: row.action,
        customer: row.customer ?? "",
        errors: Array.isArray(row.errors)
          ? row.errors.join("; ")
          : row.errors ?? "",
        message: row.message ?? "",
        reference: row.reference ?? "",
        row: Number(row.row ?? 0),
        status: row.status ?? "Success",
        warnings: Array.isArray(row.warnings)
          ? row.warnings.join("; ")
          : row.warnings ?? "",
      }));
      const result: DataPortabilityImportResult = {
        auditTrail: [
          `Who: ${currentStaff?.email ?? currentStaff?.name ?? "Authenticated admin"}`,
          `When: ${completedAt}`,
          `Dataset: ${dataPortabilityEntityLabels[dataPortabilityPreview.entity]}`,
          `Rows: ${importResult.records}`,
          `Result: ${importResult.status}`,
          `Restore Point ID: ${importResult.restorePointId}`,
        ],
        completedAt,
        created: importResult.created,
        dataset: dataPortabilityPreview.entity,
        durationMs: importResult.durationMs,
        failed: importResult.failed,
        fileName: dataPortabilityPreview.fileName,
        logRows,
        records: importResult.records,
        restorePointId: importResult.restorePointId,
        result: importResult.failed > 0 ? "partial" : "success",
        skipped: importResult.skipped,
        startedAt,
        updated: importResult.updated,
        user: currentStaff?.email ?? currentStaff?.name ?? "Authenticated admin",
      };

      if (dataPortabilityPreview.entity === "bookings") {
        setBookings(await getBookings());
      } else {
        await refreshLiveCustomerRecords();
      }

      setDataPortabilityImportResult(result);
      await refreshDataPortabilityHistory();
      setDataPortabilityImportStatus(
        `Import complete. ${result.created} created, ${result.updated} updated, ${result.skipped} skipped, ${result.failed} failed.`,
      );
      showWorkflowToast("✓ Import complete");
    } catch (error) {
      setDataPortabilityImportError(
        error instanceof Error ? error.message : "Import failed.",
      );
      setDataPortabilityImportStatus(
        "Import failed. The database transaction was rolled back.",
      );
      showWorkflowToast("⚠ Import failed");
    } finally {
      setIsDataPortabilityImporting(false);
    }
  }

  async function restoreDataPortabilityImport(
    entry: DataPortabilityImportHistoryEntry,
  ) {
    if (
      !canViewDataPortability ||
      entry.finalStatus !== "success" ||
      !entry.restorePointId
    ) {
      return;
    }

    try {
      const preview = await fetchSupabaseApi<{
        restorePoint: {
          bookingCount: number;
          customerCount: number;
          dataset: DataPortabilityEntity;
          id: string;
          restoredAt: string | null;
          restoreCount: number;
        } | null;
      }>("/api/admin/data-portability/imports", {
        body: {
          action: "restore-preview",
          importId: entry.id,
        },
        method: "POST",
      });

      if (!preview.restorePoint) {
        setDataPortabilityImportError("Restore point could not be found.");
        return;
      }

      if (preview.restorePoint.restoreCount > 0) {
        setDataPortabilityImportError(
          "This import has already been restored once.",
        );
        return;
      }

      const confirmed = window.confirm(
        [
          "Restore this Data Portability import?",
          "",
          `Dataset: ${dataPortabilityEntityLabels[preview.restorePoint.dataset]}`,
          `Bookings affected: ${preview.restorePoint.bookingCount}`,
          `Customers affected: ${preview.restorePoint.customerCount}`,
          "",
          "This restore runs server-side in a database transaction and does not send emails.",
        ].join("\n"),
      );

      if (!confirmed) {
        return;
      }

      setDataPortabilityImportStatus("Restoring import...");
      await fetchSupabaseApi<{ result: unknown }>(
        "/api/admin/data-portability/imports",
        {
          body: {
            action: "restore",
            importId: entry.id,
          },
          method: "POST",
        },
      );
      await Promise.all([
        refreshDataPortabilityHistory(),
        getBookings().then(setBookings),
        refreshLiveCustomerRecords(),
      ]);
      setDataPortabilityImportStatus("Import restore complete.");
      showWorkflowToast("✓ Import restored");
    } catch (error) {
      setDataPortabilityImportError(
        error instanceof Error ? error.message : "Import could not be restored.",
      );
      showWorkflowToast("⚠ Restore failed");
    }
  }

  function exportReport(reportType: OperationalReportType) {
    const csv = createCsv(getReportRows(reportType));

    downloadTextFile(
      `${reportType}-${analyticsSelectedShow?.supabaseId ?? analyticsSelectedShow?.id ?? "no-show"}.csv`,
      csv,
      "text/csv;charset=utf-8",
    );
  }

  function printReport(reportType: OperationalReportType) {
    const rows = getReportRows(reportType) as Array<
      Record<string, string | number | undefined>
    >;
    const headers = rows[0] ? Object.keys(rows[0]) : [];
    const html = `<!doctype html><html><head><title>${operationalReportLabels[reportType]}</title><style>body{font-family:Arial,sans-serif;padding:24px;color:#111}h1{font-size:24px}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{border:1px solid #ccc;padding:8px;text-align:left;font-size:12px}th{background:#eee}</style></head><body><h1>${operationalReportLabels[reportType]}</h1><p>${getShowLabel(analyticsSelectedShow)}</p><table><thead><tr>${headers.map((header) => `<th>${header}</th>`).join("")}</tr></thead><tbody>${rows.map((row) => `<tr>${headers.map((header) => `<td>${String(row[header] ?? "")}</td>`).join("")}</tr>`).join("")}</tbody></table></body></html>`;
    const printWindow = window.open("", "_blank");

    if (!printWindow) {
      return;
    }

    printWindow.document.write(html);
    printWindow.document.close();
    printWindow.print();
  }

  function checkInGuest(booking: DemoBooking) {
    if (
      !canCheckInGuests ||
      !isOperationallyActiveBooking(booking)
    ) {
      return;
    }

    const arrivalTime = new Date().toISOString();
    const checkedInBooking = {
      ...booking,
      arrivalTime,
      lifecycleHistory: [
        createLifecycleEvent(booking, "checked-in", "Guest arrived"),
        ...(booking.lifecycleHistory ?? []),
      ],
      status: "checked-in" as const,
    };
    const checkInRecord = createWorkflowCommunication(
      checkedInBooking,
      "check-in-confirmation",
      "email",
    );

    saveBookings(
      bookings.map((currentBooking) =>
        currentBooking.reference === booking.reference
          ? {
              ...currentBooking,
              arrivalTime,
              communicationHistory: [
                checkInRecord,
                ...(currentBooking.communicationHistory ?? []),
              ],
              lifecycleHistory: checkedInBooking.lifecycleHistory,
              status: "checked-in",
            }
          : currentBooking,
      ),
    );
    void createTicketValidation({
      booking: checkedInBooking,
      code: checkedInBooking.ticketCode ?? checkedInBooking.reference,
      deviceLabel: "Manual Check-In",
      notes: "Manual check-in recorded.",
      result: "checked_in",
    });
    void sendPreferredBrowserNotification(
      "guest-checked-in",
      "check-in-confirmed",
    );
    void sendZingaraStaffPushNotification("guest-checked-in", {
      bookingReference: booking.reference,
    });
  }

  function findTicketRecord(code: string) {
    const normalizedCode = normalizeTicketReference(code);

    if (!normalizedCode) {
      return {};
    }

    for (const currentBooking of bookings) {
      const guestTicket = getGuestTicketsForBooking(currentBooking).find(
        (ticket) => ticket.ticketCode === normalizedCode,
      );

      if (guestTicket) {
        return {
          booking: currentBooking,
          guestTicket,
        };
      }
    }

    const booking = bookings.find(
      (currentBooking) =>
        currentBooking.reference === normalizedCode ||
        currentBooking.ticketCode === normalizedCode ||
        createTicketCode(currentBooking.reference) === normalizedCode,
    );

    if (booking) {
      return {
        booking,
      };
    }

    const waitlistEntry = waitlist.find(
      (entry) =>
        entry.id === normalizedCode ||
        createTicketCode(entry.id) === normalizedCode ||
        entry.bookingReference === normalizedCode,
    );

    return {
      waitlistEntry,
    };
  }

  function createValidationResultForState(state: TicketState | "Invalid") {
    if (state === "Active") {
      return "valid" as const;
    }

    if (state === "Checked In") {
      return "already_used" as const;
    }

    if (state === "Cancelled") {
      return "cancelled" as const;
    }

    if (state === "Refunded") {
      return "refunded" as const;
    }

    return "invalid" as const;
  }

  function validateTicketCodeValue(code: string) {
    const { booking, guestTicket, waitlistEntry } = findTicketRecord(code);

    if (booking) {
      const state = guestTicket
        ? guestTicket.status === "checked-in"
          ? "Checked In"
          : getBookingTicketState(booking)
        : getBookingTicketState(booking);
      const isDuplicateCheckIn = state === "Checked In";

      setTicketValidationResult({
        booking,
        guestTicket,
        message: isDuplicateCheckIn
          ? "Already checked in. Duplicate check-in blocked."
          : state === "Cancelled"
            ? "Ticket is cancelled and cannot be checked in."
            : state === "Pending Payment"
            ? "Ticket found, but payment is still pending."
              : "Ticket is valid for check-in.",
        state,
      });
      void createTicketValidation({
        booking,
        code: guestTicket?.ticketCode ?? normalizeTicketReference(code),
        deviceLabel: isScannerOpen ? "QR Scanner" : "Manual Validation",
        notes: isDuplicateCheckIn
          ? "Duplicate scan blocked."
          : state === "Active"
            ? "Ticket scanned and accepted for check-in."
            : `Ticket scan rejected: ${state}.`,
        result: createValidationResultForState(state),
      });
      return;
    }

    if (waitlistEntry) {
      setTicketValidationResult({
        message:
          "This code belongs to a waitlist entry and is not a confirmed admission ticket.",
        state: "Waitlist",
        waitlistEntry,
      });
      void createTicketValidation({
        code,
        deviceLabel: isScannerOpen ? "QR Scanner" : "Manual Validation",
        notes: "Waitlist ticket rejected at entrance validation.",
        result: "invalid",
      });
      return;
    }

    setTicketValidationResult({
      message: "No booking or waitlist ticket matches this code.",
      state: "Invalid",
    });
    void createTicketValidation({
      code,
      deviceLabel: isScannerOpen ? "QR Scanner" : "Manual Validation",
      notes: "Invalid ticket code scanned.",
      result: "invalid",
    });
  }

  function validateTicketCode() {
    validateTicketCodeValue(ticketValidationInput);
  }

  useEffect(() => {
    if (!isScannerOpen || !canCheckInGuests) {
      return;
    }

    let isActive = true;
    let hasDecodedCode = false;
    let scanTimer = 0;
    let stream: MediaStream | null = null;
    let videoElement: HTMLVideoElement | null = null;

    function stopCamera() {
      window.clearTimeout(scanTimer);
      stream?.getTracks().forEach((track) => track.stop());

      if (videoElement) {
        videoElement.pause();
        videoElement.srcObject = null;
      }
    }

    function acceptDecodedCode(code: string) {
      const nextCode = code.trim();

      if (!nextCode || hasDecodedCode || !isActive) {
        return;
      }

      hasDecodedCode = true;
      stopCamera();
      setTicketValidationInput(nextCode);
      validateTicketCodeValue(nextCode);
    }

    async function startCameraScanner() {
      try {
        setScannerCameraError("");

        if (!navigator.mediaDevices?.getUserMedia) {
          setScannerCameraError(
            "Camera scanning is not supported in this browser. Enter the ticket code manually below.",
          );
          return;
        }

        stream = await navigator.mediaDevices.getUserMedia({
          audio: false,
          video: {
            facingMode: { ideal: "environment" },
            height: { ideal: 720 },
            width: { ideal: 1280 },
          },
        });

        videoElement = scannerVideoRef.current;

        if (!isActive || !videoElement) {
          stream.getTracks().forEach((track) => track.stop());
          return;
        }

        videoElement.srcObject = stream;
        await videoElement.play();

        const BarcodeDetectorConstructor = (
          window as typeof window & {
            BarcodeDetector?: {
              getSupportedFormats?: () => Promise<string[]>;
              new (options?: { formats?: string[] }): {
                detect: (
                  source: HTMLVideoElement,
                ) => Promise<Array<{ rawValue?: string }>>;
              };
            };
          }
        ).BarcodeDetector;
        let nativeQrSupported = Boolean(BarcodeDetectorConstructor);

        if (BarcodeDetectorConstructor?.getSupportedFormats) {
          try {
            nativeQrSupported = (
              await BarcodeDetectorConstructor.getSupportedFormats()
            ).includes("qr_code");
          } catch {
            nativeQrSupported = false;
          }
        }

        const detector = nativeQrSupported && BarcodeDetectorConstructor
          ? new BarcodeDetectorConstructor({ formats: ["qr_code"] })
          : null;
        let fallbackDecoder: import("@zxing/browser").BrowserQRCodeReader | null =
          null;
        let fallbackCanvas: HTMLCanvasElement | null = null;
        let fallbackContext: CanvasRenderingContext2D | null = null;

        if (!detector) {
          try {
            const { BrowserQRCodeReader } = await import("@zxing/browser");
            fallbackDecoder = new BrowserQRCodeReader();
            fallbackCanvas = document.createElement("canvas");
            fallbackContext = fallbackCanvas.getContext("2d", {
              willReadFrequently: true,
            });

            if (!fallbackContext) {
              throw new Error("Canvas rendering is unavailable.");
            }
          } catch {
            stopCamera();
            setScannerCameraError(
              "Automatic QR scanning could not start. Enter the ticket code manually below.",
            );
            return;
          }
        }

        async function scanFrame() {
          if (!isActive || hasDecodedCode || !videoElement) {
            return;
          }

          try {
            if (detector) {
              const codes = await detector.detect(videoElement);
              acceptDecodedCode(codes[0]?.rawValue ?? "");
            } else if (
              fallbackDecoder &&
              fallbackCanvas &&
              fallbackContext &&
              videoElement.readyState >= HTMLMediaElement.HAVE_CURRENT_DATA
            ) {
              const sourceWidth = videoElement.videoWidth;
              const sourceHeight = videoElement.videoHeight;

              if (sourceWidth > 0 && sourceHeight > 0) {
                const scale = Math.min(960 / sourceWidth, 1);
                const targetWidth = Math.max(Math.round(sourceWidth * scale), 1);
                const targetHeight = Math.max(Math.round(sourceHeight * scale), 1);

                if (
                  fallbackCanvas.width !== targetWidth ||
                  fallbackCanvas.height !== targetHeight
                ) {
                  fallbackCanvas.width = targetWidth;
                  fallbackCanvas.height = targetHeight;
                }

                fallbackContext.drawImage(
                  videoElement,
                  0,
                  0,
                  targetWidth,
                  targetHeight,
                );
                acceptDecodedCode(
                  fallbackDecoder.decodeFromCanvas(fallbackCanvas).getText(),
                );
              }
            }
          } catch {
            // No QR was found in this frame, or video metadata is still settling.
          }

          if (isActive && !hasDecodedCode) {
            scanTimer = window.setTimeout(scanFrame, detector ? 450 : 300);
          }
        }

        scanFrame();
      } catch (error) {
        const cameraError = error as DOMException;
        const message =
          cameraError.name === "NotAllowedError" ||
          cameraError.name === "SecurityError"
            ? "Camera permission was denied. Allow camera access or enter the ticket code manually below."
            : cameraError.name === "NotFoundError" ||
                cameraError.name === "OverconstrainedError"
              ? "No usable camera was found. Enter the ticket code manually below."
              : "Camera access was unavailable. Enter the ticket code manually below.";

        stopCamera();
        setScannerCameraError(message);
      }
    }

    startCameraScanner();

    return () => {
      isActive = false;
      stopCamera();
    };
    // validateTicketCodeValue reads live booking state; scanner restarts only on open/permission changes.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [canCheckInGuests, isScannerOpen]);

  function checkInValidatedTicket() {
    const booking = ticketValidationResult?.booking;
    const guestTicket = ticketValidationResult?.guestTicket;

    if (!booking || !canCheckInGuests) {
      return;
    }

    const freshBooking =
      bookings.find(
        (currentBooking) =>
          currentBooking.reference === booking.reference,
      ) ?? booking;
    const freshState = getBookingTicketState(freshBooking);
    const freshGuestTicket = guestTicket
      ? getGuestTicketsForBooking(freshBooking).find(
          (ticket) => ticket.ticketCode === guestTicket.ticketCode,
        )
      : undefined;

    if (freshGuestTicket) {
      if (freshGuestTicket.status === "checked-in") {
        setTicketValidationResult({
          booking: freshBooking,
          guestTicket: freshGuestTicket,
          message: "Already checked in. Duplicate check-in blocked.",
          state: "Checked In",
        });
        return;
      }

      if (freshState !== "Active") {
        setTicketValidationResult({
          booking: freshBooking,
          guestTicket: freshGuestTicket,
          message:
            freshState === "Cancelled"
              ? "Ticket is cancelled and cannot be checked in."
              : freshState === "Pending Payment"
                ? "Ticket found, but payment is still pending."
                : "Ticket is no longer active for check-in.",
          state: freshState,
        });
        return;
      }

      const arrivalTime = new Date().toISOString();
      const checkedInGuestTicket = {
        ...freshGuestTicket,
        checkedInAt: arrivalTime,
        status: "checked-in" as const,
      };
      const nextBooking = {
        ...freshBooking,
        guestTickets: getGuestTicketsForBooking(freshBooking).map((ticket) =>
          ticket.ticketCode === checkedInGuestTicket.ticketCode
            ? checkedInGuestTicket
            : ticket,
        ),
        lifecycleHistory: [
          createLifecycleEvent(
            freshBooking,
            "checked-in",
            `Guest ticket checked in: ${checkedInGuestTicket.ticketCode}`,
          ),
          ...(freshBooking.lifecycleHistory ?? []),
        ],
      };

      saveBookings(
        bookings.map((currentBooking) =>
          currentBooking.reference === freshBooking.reference
            ? nextBooking
            : currentBooking,
        ),
      );
      void createTicketValidation({
        booking: nextBooking,
        code: checkedInGuestTicket.ticketCode,
        deviceLabel: "Entrance Check-In",
        notes: "Individual ticket accepted and guest checked in.",
        result: "checked_in",
      });
      void sendPreferredBrowserNotification(
      "guest-checked-in",
      "check-in-confirmed",
    );
      void sendZingaraStaffPushNotification("guest-checked-in", {
        bookingReference: freshBooking.reference,
      });
      setTicketValidationResult({
        booking: nextBooking,
        guestTicket: checkedInGuestTicket,
        message: "Guest ticket checked in. Other guests remain pending.",
        state: "Checked In",
      });
      return;
    }

    if (freshState !== "Active") {
      setTicketValidationResult({
        booking: freshBooking,
        message:
          freshState === "Checked In"
            ? "Already checked in. Duplicate check-in blocked."
            : freshState === "Cancelled"
              ? "Ticket is cancelled and cannot be checked in."
              : freshState === "Pending Payment"
                ? "Ticket found, but payment is still pending."
                : "Ticket is no longer active for check-in.",
        state: freshState,
      });
      return;
    }

    const arrivalTime = new Date().toISOString();
    const checkedInBooking = {
      ...freshBooking,
      arrivalTime,
      lifecycleHistory: [
        createLifecycleEvent(freshBooking, "checked-in", "Guest arrived"),
        ...(freshBooking.lifecycleHistory ?? []),
      ],
      status: "checked-in" as const,
    };
    const checkInRecord = createWorkflowCommunication(
      checkedInBooking,
      "check-in-confirmation",
      "email",
    );

    saveBookings(
      bookings.map((currentBooking) =>
        currentBooking.reference === freshBooking.reference
          ? {
              ...currentBooking,
              arrivalTime,
              communicationHistory: [
                checkInRecord,
                ...(currentBooking.communicationHistory ?? []),
              ],
              lifecycleHistory: checkedInBooking.lifecycleHistory,
              status: "checked-in",
            }
          : currentBooking,
      ),
    );
    void createTicketValidation({
      booking: checkedInBooking,
      code: ticketValidationInput,
      deviceLabel: "Entrance Check-In",
      notes: "Ticket accepted and guest checked in.",
      result: "checked_in",
    });
    void sendPreferredBrowserNotification(
      "guest-checked-in",
      "check-in-confirmed",
    );
    void sendZingaraStaffPushNotification("guest-checked-in", {
      bookingReference: freshBooking.reference,
    });
    setTicketValidationResult({
      booking: checkedInBooking,
      message: "Guest checked in. Duplicate scans will now be blocked.",
      state: "Checked In",
    });
  }

  function overrideCheckInValidatedTicket() {
    const booking = ticketValidationResult?.booking;
    const guestTicket = ticketValidationResult?.guestTicket;

    if (!booking || !canManageBookings) {
      return;
    }

    const freshBooking =
      bookings.find(
        (currentBooking) =>
          currentBooking.reference === booking.reference,
      ) ?? booking;

    if ((freshBooking.status ?? "confirmed") === "cancelled") {
      setTicketValidationResult({
        booking: freshBooking,
        message: "Manager override blocked: this booking is cancelled.",
        state: "Cancelled",
      });
      return;
    }

    const freshGuestTicket = guestTicket
      ? getGuestTicketsForBooking(freshBooking).find(
          (ticket) => ticket.ticketCode === guestTicket.ticketCode,
        )
      : undefined;

    if (freshGuestTicket) {
      const arrivalTime = new Date().toISOString();
      const checkedInGuestTicket = {
        ...freshGuestTicket,
        checkedInAt: arrivalTime,
        status: "checked-in" as const,
      };
      const nextBooking = {
        ...freshBooking,
        guestTickets: getGuestTicketsForBooking(freshBooking).map((ticket) =>
          ticket.ticketCode === checkedInGuestTicket.ticketCode
            ? checkedInGuestTicket
            : ticket,
        ),
        lifecycleHistory: [
          createLifecycleEvent(
            freshBooking,
            "checked-in",
            `Manager override guest ticket check-in: ${checkedInGuestTicket.ticketCode}`,
          ),
          ...(freshBooking.lifecycleHistory ?? []),
        ],
      };

      saveBookings(
        bookings.map((currentBooking) =>
          currentBooking.reference === freshBooking.reference
            ? nextBooking
            : currentBooking,
        ),
      );
      void createTicketValidation({
        booking: nextBooking,
        code: checkedInGuestTicket.ticketCode,
        deviceLabel: "Manager Override",
        notes: "Manager override individual ticket check-in recorded.",
        result: "checked_in",
      });
      void sendPreferredBrowserNotification(
      "guest-checked-in",
      "check-in-confirmed",
    );
      void sendZingaraStaffPushNotification("guest-checked-in", {
        bookingReference: freshBooking.reference,
      });
      setTicketValidationResult({
        booking: nextBooking,
        guestTicket: checkedInGuestTicket,
        message: "Manager override check-in recorded for this guest ticket.",
        state: "Checked In",
      });
      return;
    }

    const arrivalTime = new Date().toISOString();
    const checkedInBooking = {
      ...freshBooking,
      arrivalTime,
      lifecycleHistory: [
        createLifecycleEvent(
          freshBooking,
          "checked-in",
          "Manager override check-in",
        ),
        ...(freshBooking.lifecycleHistory ?? []),
      ],
      status: "checked-in" as const,
    };
    const checkInRecord = createWorkflowCommunication(
      checkedInBooking,
      "check-in-confirmation",
      "email",
    );

    saveBookings(
      bookings.map((currentBooking) =>
        currentBooking.reference === freshBooking.reference
          ? {
              ...currentBooking,
              arrivalTime,
              communicationHistory: [
                checkInRecord,
                ...(currentBooking.communicationHistory ?? []),
              ],
              lifecycleHistory: checkedInBooking.lifecycleHistory,
              status: "checked-in",
            }
          : currentBooking,
      ),
    );
    void createTicketValidation({
      booking: checkedInBooking,
      code: ticketValidationInput,
      deviceLabel: "Manager Override",
      notes: "Manager override check-in recorded.",
      result: "checked_in",
    });
    void sendPreferredBrowserNotification(
      "guest-checked-in",
      "check-in-confirmed",
    );
    void sendZingaraStaffPushNotification("guest-checked-in", {
      bookingReference: freshBooking.reference,
    });
    setTicketValidationResult({
      booking: checkedInBooking,
      message: "Manager override check-in recorded.",
      state: "Checked In",
    });
  }

  async function moveBooking(
    booking: DemoBooking,
    nextTableId: string,
  ) {
    if (!canManageBookings || isBookingReadOnly(booking.reference)) {
      if (isBookingReadOnly(booking.reference)) {
        showWorkflowToast("This booking is currently being edited.");
      }
      return false;
    }

    const setCompatibilityWarning = (message: string) => {
      setTableCompatibilityWarnings((currentWarnings) => ({
        ...currentWarnings,
        [booking.reference]: message,
      }));
    };
    const nextTable = tables.find(
      (table) => table.id === nextTableId,
    );
    const nextZone = nextTable
      ? getZoneById(nextTable.zoneId)
      : undefined;

    if (!nextTable || !nextZone) {
      setCompatibilityWarning(
        "Select a live table before moving this booking.",
      );
      return false;
    }

    if (nextTable.id === booking.tableId) {
      setTableCompatibilityWarnings((currentWarnings) => {
        const nextWarnings = { ...currentWarnings };
        delete nextWarnings[booking.reference];
        return nextWarnings;
      });
      return true;
    }

    if (
      !nextTable.authoritativeId ||
      !isEligibleBookingMoveTarget(nextTable, booking, tables)
    ) {
      setCompatibilityWarning(
        "Select an available configured physical, temporary, or merged table in the same seating zone.",
      );
      return false;
    }

    const moved = await reallocateBookingToPhysicalTable(
      booking,
      nextTable.authoritativeId,
      nextTable.tableNumber,
    );

    if (moved) {
      setTableCompatibilityWarnings((currentWarnings) => {
        const nextWarnings = { ...currentWarnings };
        delete nextWarnings[booking.reference];
        return nextWarnings;
      });
    }

    return moved;
  }

  async function refreshAssignedShowState(showId: string) {
    showLoadRequestRef.current += 1;
    selectedShowTableLoadRequestRef.current += 1;

    const [nextShowPayload, nextBookings] = await Promise.all([
      getShowsWithTables({ tableShow: showId }),
      getBookings(),
    ]);

    if (!nextShowPayload.tablesLoaded) {
      throw new Error("Assigned table inventory could not be refreshed.");
    }

    const selectedShowTables = applyBookingOccupancyToTables(
      nextShowPayload.tables,
      nextBookings,
    );

    setBookings(nextBookings);
    setTables((currentTables) =>
      mergeTablesForShows(currentTables, selectedShowTables, [showId]),
    );
    setIsShowsLoading(false);
  }

  async function assignFloorQueuedBooking(booking: DemoBooking) {
    if (!canManageBookings || isBookingReadOnly(booking.reference)) {
      if (isBookingReadOnly(booking.reference)) {
        showWorkflowToast("This booking is currently being edited.");
      }
      return;
    }

    if (!booking.showId) {
      showWorkflowToast("This booking does not have a resolved performance.");
      return;
    }

    const allocation = findBestTableAllocation(
      tables,
      booking.showId,
      booking.zoneId,
      booking.partySize,
    );

    if (!allocation) {
      showWorkflowToast(
        "No suitable existing table is available. Create or merge an operational table before assigning this booking.",
      );
      return;
    }

    const nextZone = getZoneById(allocation.table.zoneId);

    if (!nextZone) {
      showWorkflowToast("The suggested table zone could not be resolved.");
      return;
    }

    if (allocation.isCombination) {
      showWorkflowToast(
        "Combined-table assignments must be created in Table Management before assigning this booking.",
      );
      return;
    }

    const assignedBooking = {
      ...booking,
      tableId: allocation.table.id,
      tableNumber: allocation.table.tableNumber,
      zoneId: nextZone.id,
      zoneTitle: nextZone.title,
    };

    if (floorAssignmentInFlightRef.current.has(booking.reference)) {
      return;
    }

    floorAssignmentInFlightRef.current.add(booking.reference);

    try {
      await assignBookingTable(assignedBooking);
      await refreshAssignedShowState(booking.showId);
      showWorkflowToast(
        `Assigned ${booking.reference} to ${allocation.table.tableNumber}.`,
      );
    } catch (error) {
      await refreshAssignedShowState(booking.showId).catch(() => undefined);
      showWorkflowToast(
        error instanceof Error
          ? error.message
          : "The table assignment could not be saved.",
      );
    } finally {
      floorAssignmentInFlightRef.current.delete(booking.reference);
    }
  }

  async function sendTicket(
    booking: DemoBooking,
    channel: CommunicationChannel,
  ) {
    if (channel === "push") {
      const ticketRecord = createWorkflowCommunication(
        booking,
        "ticket-resend",
        "push",
        {
          message: `Push ticket sent to registered app devices · Live ticket ${getTicketUrl(booking.reference)}`,
          updateSummary: `Ticket resent by ${currentStaff?.name ?? "staff"}.`,
        },
      );

      try {
        const pushResult = await sendZingaraGuestPushNotification(
          "ticket-resend",
          {
            bookingReference: booking.reference,
            message: ticketRecord.message,
            title: "Your Zingara ticket is ready",
          },
        );

        if (!pushResult.ok) {
          await persistCustomGuestCommunication(
            booking,
            ticketRecord,
            "failed",
          );
          showWorkflowToast(
            (pushResult.subscriptionCount ?? 0) === 0
              ? "No active push subscription is available for this guest."
              : "Push notification could not be sent.",
          );
          return;
        }

        const result = await persistCustomGuestCommunication(
          booking,
          ticketRecord,
          "sent",
        );

        setBookings((currentBookings) =>
          appendCommunicationToBookings(
            currentBookings,
            booking.reference,
            () => ({
              ...ticketRecord,
              id: result.row?.id ?? ticketRecord.id,
              sentAt:
                result.row?.sent_at ??
                result.row?.created_at ??
                ticketRecord.sentAt,
            }),
          ),
        );
        showWorkflowToast("✓ Push notification sent successfully.");
      } catch (error) {
        console.error("[Zingara Admin] Ticket push failed", error);
        showWorkflowToast("⚠ Push notification could not be sent.");
      }
      return;
    }

    sendWorkflowCommunication(booking, "ticket-resend", channel, {
      message: `${communicationChannelLabels[channel]} ticket sent to ${
        channel === "email"
          ? booking.customer.email
          : channel === "sms"
            ? booking.customer.phone
            : "registered app devices"
      } · Live ticket ${getTicketUrl(booking.reference)}`,
      updateSummary: `Ticket resent by ${currentStaff?.name ?? "staff"}.`,
    });
  }

  function resendConfirmation(booking: DemoBooking) {
    sendWorkflowCommunication(
      booking,
      "confirmation-resend",
      "email",
      {
        updateSummary: `Confirmation resent by ${currentStaff?.name ?? "staff"}.`,
      },
    );
  }

  async function persistCustomGuestCommunication(
    booking: DemoBooking,
    record: DemoBooking["communicationHistory"][number],
    deliveryStatus?: "failed" | "sent",
  ) {
    return fetchSupabaseApi<{
      deduped?: boolean;
      row: {
        created_at?: string | null;
        id?: string;
        sent_at?: string | null;
        status?: "failed" | "sent";
      } | null;
    }>("/api/admin/communications", {
      body: {
        booking,
        deliveryStatus,
        record,
      },
      method: "POST",
    });
  }

  async function persistAdminBookingState(booking: DemoBooking) {
    await fetchSupabaseApi<{ row: unknown }>("/api/admin/bookings", {
      body: {
        action: "update-state",
        booking,
      },
      method: "PATCH",
    });
    await updatePayment(booking);
    await updateTicket(booking);
    setBookings(await getBookings());
  }

  function canSendCustomerPaymentLink(booking: DemoBooking) {
    const financials = getBookingFinancials(booking);

    if (!canManageBookings || !canManageCommunications) {
      return false;
    }

    return (
      Boolean(booking.customer.email?.trim()) &&
      isPaymentLinkEligible({
        archived: Boolean(booking.archivedAt),
        bookingStatus: booking.status,
        confirmedPaidAmount: financials.amountPaid,
        paymentStatus: financials.paymentStatus,
        totalAmount: financials.totalPrice,
      })
    );
  }

  async function sendCustomerPaymentLink(booking: DemoBooking) {
    if (!canSendCustomerPaymentLink(booking)) {
      setPaymentLinkSendState((currentState) => ({
        ...currentState,
        [booking.reference]: {
          isSending: false,
          message: "This booking is not eligible for a payment link.",
          tone: "error",
        },
      }));
      return;
    }

    setPaymentLinkSendState((currentState) => ({
      ...currentState,
      [booking.reference]: {
        isSending: true,
        message: "Sending secure payment link...",
        tone: "success",
      },
    }));

    try {
      const result = await fetchSupabaseApi<{
        deduped?: boolean;
        row?: {
          created_at?: string | null;
          id?: string;
          message?: string;
          sent_at?: string | null;
          status?: "failed" | "sent";
          subject?: string | null;
        } | null;
      }>("/api/admin/bookings/payment-link", {
        body: {
          bookingReference: booking.reference,
        },
        method: "POST",
      });

      if (result.row?.status !== "sent" && !result.deduped) {
        throw new Error("Payment link email could not be sent.");
      }

      if (result.row) {
        const sentAt =
          result.row.sent_at ?? result.row.created_at ?? new Date().toISOString();

        setBookings((currentBookings) =>
          appendCommunicationToBookings(
            currentBookings,
            booking.reference,
            () => ({
              channel: "email",
              id: result.row?.id ?? `${booking.reference}-payment-link-${sentAt}`,
              message: result.row?.message ?? "Secure payment link sent.",
              sentAt,
              subject:
                result.row?.subject ?? `Secure payment link for ${booking.reference}`,
              trigger: "custom-message",
            }),
          ),
        );
      }

      setPaymentLinkSendState((currentState) => ({
        ...currentState,
        [booking.reference]: {
          isSending: false,
          message: result.deduped
            ? "Payment link was already sent."
            : "Payment link sent successfully.",
          tone: "success",
        },
      }));
    } catch (error) {
      console.error("[Zingara Admin] Payment link send failed", error);
      setPaymentLinkSendState((currentState) => ({
        ...currentState,
        [booking.reference]: {
          isSending: false,
          message:
            error instanceof Error
              ? error.message
              : "Payment link could not be sent.",
          tone: "error",
        },
      }));
    }
  }

  async function sendCustomGuestMessage(booking: DemoBooking) {
    const form = customMessageForms[booking.reference];
    const message = form?.message.trim();
    const channel = form?.channel ?? "email";
    const subject = form?.subject.trim() || "Zingara guest message";

    if (!canManageCommunications || !message) {
      return;
    }

    if (channel === "sms") {
      setCustomMessageSendState((currentState) => ({
        ...currentState,
        [booking.reference]: {
          isSending: false,
          message: "Future SMS is not available yet.",
          tone: "error",
        },
      }));
      return;
    }

    setCustomMessageSendState((currentState) => ({
      ...currentState,
      [booking.reference]: {
        isSending: true,
        message:
          channel === "push"
            ? "Sending push notification..."
            : "Sending email...",
        tone: "success",
      },
    }));

    const communicationRecord = createWorkflowCommunication(
      booking,
      "custom-message",
      channel,
      {
        message,
        subject,
        updateSummary: message,
      },
    );

    try {
      if (channel === "email") {
        const result = await persistCustomGuestCommunication(
          booking,
          communicationRecord,
        );

        if (result.row?.status !== "sent") {
          throw new Error("Email could not be delivered.");
        }

        setBookings((currentBookings) =>
          appendCommunicationToBookings(
            currentBookings,
            booking.reference,
            () => communicationRecord,
          ),
        );
        setCustomMessageSendState((currentState) => ({
          ...currentState,
          [booking.reference]: {
            isSending: false,
            message: "Email sent successfully.",
            tone: "success",
          },
        }));
      } else {
        const pushResult = await sendZingaraGuestPushNotification(
          "custom-message",
          {
            bookingReference: booking.reference,
            message,
            title: subject,
          },
        );

        if (!pushResult.ok) {
          await persistCustomGuestCommunication(
            booking,
            communicationRecord,
            "failed",
          );
          setCustomMessageSendState((currentState) => ({
            ...currentState,
            [booking.reference]: {
              isSending: false,
              message:
                (pushResult.subscriptionCount ?? 0) === 0
                  ? "No active push subscription is available for this guest."
                  : "Push notification could not be sent.",
              tone: "error",
            },
          }));
          return;
        }

        await persistCustomGuestCommunication(
          booking,
          communicationRecord,
          "sent",
        );
        setBookings((currentBookings) =>
          appendCommunicationToBookings(
            currentBookings,
            booking.reference,
            () => communicationRecord,
          ),
        );
        setCustomMessageSendState((currentState) => ({
          ...currentState,
          [booking.reference]: {
            isSending: false,
            message: "Push notification sent successfully.",
            tone: "success",
          },
        }));
      }

      setCustomMessageForms((currentForms) => ({
        ...currentForms,
        [booking.reference]: {
          channel,
          message: "",
          subject: "",
        },
      }));
    } catch (error) {
      console.error("[Zingara Admin] Custom guest message failed", error);
      setCustomMessageSendState((currentState) => ({
        ...currentState,
        [booking.reference]: {
          isSending: false,
          message:
            channel === "push"
              ? "Push notification could not be sent."
              : "Email could not be sent.",
          tone: "error",
        },
      }));
    }
  }

  function showWorkflowToast(message: string) {
    setWorkflowToast(message);
    if (workflowToastTimerRef.current) {
      window.clearTimeout(workflowToastTimerRef.current);
    }
    workflowToastTimerRef.current = window.setTimeout(() => {
      setWorkflowToast("");
    }, 2800);
  }

  function sendShowReminder() {
    if (!canManageCommunications) {
      return;
    }

    const activeBookings = workflowShowBookings.filter(
      (booking) =>
        isOperationallyActiveBooking(booking) &&
        (booking.status ?? "confirmed") !== "checked-in",
    );

    if (activeBookings.length === 0) {
      setWorkflowStatus(
        "No active guests are available for reminders on this show.",
      );
      return;
    }

    saveBookings(
      activeBookings.reduce(
        (nextBookings, booking) =>
          appendCommunicationToBookings(
            nextBookings,
            booking.reference,
            (currentBooking) =>
              createWorkflowCommunication(
                currentBooking,
                "show-reminder",
                "email",
              ),
          ),
        bookings,
      ),
    );
    setWorkflowStatus(
      `Show reminders sent to ${activeBookings.length} booking${activeBookings.length === 1 ? "" : "s"}.`,
    );
    void sendPreferredBrowserNotification(
      "operational-broadcast-sent",
      "booking-updated",
      {
        body: "Show reminders have been sent successfully.",
      },
    );
  }

  function openSelectedTemplateCommunicationConfirmation() {
    if (!canManageCommunications || !selectedCommunicationTemplate) {
      return;
    }

    const activeBookings = workflowShowBookings.filter(
      isOperationallyActiveBooking,
    );

    if (activeBookings.length === 0) {
      setWorkflowStatus(
        "No active bookings are available for this communication.",
      );
      return;
    }

    setIsWorkflowSendConfirmOpen(true);
  }

  function closeSelectedTemplateCommunicationConfirmation() {
    if (isWorkflowSending) {
      return;
    }

    setIsWorkflowSendConfirmOpen(false);
  }

  function sendSelectedTemplateCommunication() {
    if (
      isWorkflowSending ||
      !canManageCommunications ||
      !selectedCommunicationTemplate
    ) {
      return;
    }

    const activeBookings = workflowShowBookings.filter(
      isOperationallyActiveBooking,
    );

    if (activeBookings.length === 0) {
      setWorkflowStatus(
        "No active bookings are available for this communication.",
      );
      setIsWorkflowSendConfirmOpen(false);
      return;
    }

    setIsWorkflowSending(true);

    try {
      saveBookings(
        activeBookings.reduce(
          (nextBookings, booking) =>
            appendCommunicationToBookings(
              nextBookings,
              booking.reference,
              (currentBooking) =>
                createTemplateCommunication(
                  currentBooking,
                  selectedCommunicationTemplate,
                ),
            ),
          bookings,
        ),
      );
      setWorkflowStatus(
        `Communication sent successfully to ${activeBookings.length} booking${activeBookings.length === 1 ? "" : "s"}.`,
      );
      showWorkflowToast("Communication sent successfully.");
      void sendPreferredBrowserNotification(
        "operational-broadcast-sent",
        "booking-updated",
        {
          body: "Communication sent successfully.",
        },
      );
      setIsWorkflowSendConfirmOpen(false);
    } catch {
      setWorkflowStatus("Communication could not be sent.");
      showWorkflowToast("⚠ Could not send communication");
    } finally {
      setIsWorkflowSending(false);
    }
  }

  function broadcastOperationalUpdate() {
    const message = broadcastForm.message.trim();

    if (!canManageCommunications || !message) {
      return;
    }

    const showBookings = workflowShowBookings.filter(
      isOperationallyActiveBooking,
    );

    if (showBookings.length === 0) {
      setWorkflowStatus(
        "No active bookings are available for this broadcast.",
      );
      return;
    }

    saveBookings(
      showBookings.reduce(
        (nextBookings, booking) =>
          appendCommunicationToBookings(
            nextBookings,
            booking.reference,
            (currentBooking) =>
              createWorkflowCommunication(
                currentBooking,
                "operational-broadcast",
                broadcastForm.channel,
                {
                  message,
                  subject:
                    broadcastForm.subject.trim() ||
                    "Zingara operational update",
                  updateSummary: message,
                },
              ),
          ),
        bookings,
      ),
    );
    setBroadcastForm((currentForm) => ({
      ...currentForm,
      message: "",
      subject: "",
    }));
    setWorkflowStatus(
      `Operational update sent to ${showBookings.length} booking${showBookings.length === 1 ? "" : "s"}.`,
    );
    showWorkflowToast("Broadcast sent successfully.");
    void sendPreferredBrowserNotification(
      "operational-broadcast-sent",
      "booking-updated",
      {
        body: "Operational update sent successfully.",
      },
    );
    void sendZingaraStaffPushNotification("operational-broadcast-sent");
  }

  function findWaitlistConversionTable(entry: DemoWaitlistEntry) {
    const eligibleZones = entry.desiredZoneId
      ? seatingZones.filter((zone) => zone.id === entry.desiredZoneId)
      : seatingZones;

    for (const zone of eligibleZones) {
      const canSeatParty =
        entry.partySize >= zone.minGuests &&
        entry.partySize <= zone.maxGuests;
      const allocation = canSeatParty
        ? findBestTableAllocation(
            tables,
            entry.showId,
            zone.id,
            entry.partySize,
          )
        : undefined;

      if (allocation) {
        return {
          allocation,
          table: allocation.table,
          zone,
        };
      }
    }

    return null;
  }

  function updateWaitlistEntry(
    entryId: string,
    updates: Partial<DemoWaitlistEntry>,
  ) {
    if (!canManageWaitlist) {
      return;
    }

    saveWaitlist(
      waitlist.map((entry) =>
        entry.id === entryId
          ? {
              ...entry,
              ...updates,
            }
          : entry,
      ),
    );
  }

  function promoteWaitlistEntry(entry: DemoWaitlistEntry) {
    if (!canManageWaitlist || entry.status !== "waiting") {
      return;
    }

    const promotionRecord =
      createWaitlistPromotionCommunication(entry);

    updateWaitlistEntry(entry.id, {
      communicationHistory: [
        promotionRecord,
        ...(entry.communicationHistory ?? []),
      ],
      promotedAt: new Date().toISOString(),
      status: "promoted",
    });
    void sendZingaraStaffPushNotification("waitlist-promotion", {
      waitlistId: entry.id,
    });
    void sendZingaraGuestPushNotification("waitlist-promoted", {
      bookingReference: entry.id,
    });
  }

  function removeWaitlistEntry(entry: DemoWaitlistEntry) {
    if (
      !canManageWaitlist ||
      entry.status === "converted" ||
      entry.status === "removed"
    ) {
      return;
    }

    updateWaitlistEntry(entry.id, {
      status: "removed",
    });
  }

  function convertWaitlistEntry(entry: DemoWaitlistEntry) {
    if (
      !canManageWaitlist ||
      entry.status === "converted" ||
      entry.status === "removed"
    ) {
      return;
    }

    const allocation = findWaitlistConversionTable(entry);

    if (!allocation) {
      return;
    }

    const bookingReference = createAvailableBookingReference(bookings);
    const show = shows.find((demoShow) => demoShow.id === entry.showId);
    const subtotalPrice = allocation.zone.price * entry.partySize;
    const now = new Date().toISOString();
    const booking: DemoBooking = {
      reference: bookingReference,
      showId: entry.showId,
      zoneId: allocation.zone.id,
      zoneTitle: allocation.zone.title,
      tableId: allocation.table.id,
      tableNumber: allocation.table.tableNumber,
      partySize: entry.partySize,
      bookingDate: getShowLabel(show),
      addons: [],
      addonsTotal: 0,
      subtotalPrice,
      discountAmount: 0,
      totalPrice: subtotalPrice,
      pricePerPerson: allocation.zone.price,
      paymentOption: "deposit",
      paymentStatus: "pending-payment",
      depositPercentage: 0,
      amountPaid: 0,
      balanceDue: subtotalPrice,
      source: "waitlist",
      ticketCode: createTicketCode(bookingReference),
      ticketIssuedAt: now,
      customer: entry.customer,
      status: "pending-payment",
      lifecycleHistory: [
        {
          id: `${bookingReference}-created`,
          toStatus: "waitlisted",
          note: "Created from waitlist",
          createdAt: now,
        },
        {
          id: `${bookingReference}-pending-payment`,
          fromStatus: "waitlisted",
          toStatus: "pending-payment",
          note: "Converted from waitlist and awaiting payment",
          createdAt: now,
        },
      ],
      operationalNotes:
        entry.notes || "Converted from waitlist into booking.",
      cancellationReason: "",
      refundNotes: "",
      communicationHistory: [],
      createdAt: now,
    };
    const confirmationRecord = createWorkflowCommunication(
      booking,
      "booking-confirmation",
      "email",
      {
        updateSummary:
          "Converted from waitlist and assigned an available table.",
      },
    );
    const paymentRecord = createWorkflowCommunication(
      booking,
      "payment-confirmation",
      "email",
    );

    saveBookings([
      {
        ...booking,
        communicationHistory: [confirmationRecord, paymentRecord],
      },
      ...bookings,
    ]);
    saveTables(
      applyTableAllocation(
        tables,
        allocation.allocation,
        bookingReference,
        entry.notes ||
          `Converted from waitlist for ${entry.customer.name}`,
      ),
    );
    saveWaitlist(
      waitlist.map((waitlistEntry) =>
        waitlistEntry.id === entry.id
          ? {
              ...waitlistEntry,
              bookingReference,
              convertedAt: now,
              promotedAt: waitlistEntry.promotedAt ?? now,
              status: "converted",
            }
          : waitlistEntry,
      ),
    );
  }

  function openCustomerProfile(
    customer: {
      email?: string;
      name?: string;
      phone?: string;
    },
    context: {
      bookingReference?: string;
      source: "bookings" | "customers" | "direct";
    } = { source: "direct" },
  ) {
    const customerKey = getCustomerKey(customer);
    const bookingCustomerId = context.bookingReference
      ? bookings.find(
          (booking) => booking.reference === context.bookingReference,
        )?.customerId
      : undefined;
    const matchedProfile = bookingCustomerId
      ? customerProfiles.find(
          (profile) => profile.customerId === bookingCustomerId,
        )
      : customerProfiles.find((profile) => profile.key === customerKey);

    console.log("[Zingara CRM] Open Profile clicked", {
      customer,
      customerKey,
    });
    console.log("[Zingara CRM] customer found", {
      found: Boolean(matchedProfile),
      profile: matchedProfile?.customer.name,
    });

    setCustomerSearch("");
    setSelectedCustomerKey(
      matchedProfile
        ? getCustomerProfileSelectionId(matchedProfile)
        : `snapshot:${customerKey}`,
    );
    setCustomerProfileReturnContext(context);
    setActiveAdminTab("customers");

    console.log("[Zingara CRM] profile loaded", {
      customerKey,
    });
  }

  function returnFromCustomerProfile() {
    if (
      customerProfileReturnContext.source === "bookings" &&
      customerProfileReturnContext.bookingReference
    ) {
      setActiveAdminTab("bookings");
      setBookingSearch(customerProfileReturnContext.bookingReference);
      setBookingPage(1);
      setSelectedCustomerKey(null);
      setCustomerProfileReturnContext({ source: "direct" });
      return;
    }

    setActiveAdminTab("customers");
    setSelectedCustomerKey(null);
    setCustomerProfileReturnContext({ source: "direct" });
  }

  async function updateCustomerCrmRecord(
    profile: CustomerProfile,
    updates: Partial<Pick<DemoCustomerCrmRecord, "notes" | "vipTags">>,
  ) {
    if (!canManageBookings) {
      return;
    }

    if (!profile.customerId) {
      showWorkflowToast("⚠ Customer is not linked to a live record");
      return;
    }

    const liveCustomer = liveCustomerRecords.find(
      (record) => record.id === profile.customerId,
    );

    if (!liveCustomer) {
      showWorkflowToast("⚠ Customer is not linked to a live record");
      return;
    }

    try {
      const updatedCustomer = await updateCustomerCrmDetails(liveCustomer.id, {
        notes: updates.notes ?? liveCustomer.relationship_notes ?? "",
        vipTags:
          updates.vipTags ?? liveCustomer.preferences?.vipTags ?? [],
      });

      if (!updatedCustomer) {
        throw new Error("Customer could not be updated.");
      }

      setLiveCustomerRecords((currentRecords) =>
        currentRecords.map((record) =>
          record.id === updatedCustomer.id
            ? {
                ...record,
                preferences: updatedCustomer.preferences,
                relationship_notes: updatedCustomer.relationship_notes,
              }
            : record,
        ),
      );
      setCustomerRelationshipNoteDraft(null);
      showWorkflowToast("✓ Saved · Customer updated");
    } catch {
      showWorkflowToast("⚠ Could not save");
    }
  }

  function getLiveCustomerForProfile(profile: CustomerProfile) {
    if (profile.customerId) {
      return (
        liveCustomerRecords.find(
          (record) => record.id === profile.customerId,
        ) ?? null
      );
    }

    return (
      resolveLiveCustomer({
        customer: {
          email: profile.customer.email,
          key: profile.key,
          phone: profile.customer.phone,
        },
        records: liveCustomerRecords,
      }) ?? null
    );
  }

  function getLiveCustomerForBooking(booking: DemoBooking) {
    if (booking.customerId) {
      return (
        liveCustomerRecords.find(
          (record) => record.id === booking.customerId,
        ) ?? null
      );
    }

    const bookingKey = getCustomerKey(booking.customer);

    return (
      resolveLiveCustomer({
        customer: {
          email: booking.customer.email,
          key: bookingKey,
          phone: booking.customer.phone,
        },
        records: liveCustomerRecords,
      }) ?? null
    );
  }

  function getCustomerProfileNameStatus(profile: CustomerProfile) {
    const liveCustomer = getLiveCustomerForProfile(profile);
    const liveCustomerNameParts = liveCustomer
      ? deriveCustomerNameParts({
          firstName: liveCustomer.first_name,
          lastName: liveCustomer.surname,
        })
      : null;

    return classifyCustomerName({
      displayName: liveCustomer
        ? getLiveCustomerName(liveCustomer)
        : profile.customer.name,
      firstName: liveCustomerNameParts?.firstName,
      lastName: liveCustomerNameParts?.lastName,
    });
  }

  function beginCustomerIdentityEdit(customerId: string) {
    const customer = liveCustomerRecords.find(
      (record) => record.id === customerId,
    );

    if (!customer) {
      setEditingCustomerIdentityId(null);
      setCustomerIdentityError(
        "The linked customer record is no longer available.",
      );
      populateCustomerIdentityForm(null);
      return;
    }

    populateCustomerIdentityForm(customer);
    setEditingCustomerIdentityId(customer.id);
    setCustomerIdentityError("");
  }

  function populateCustomerIdentityForm(customer: LiveCustomerRecord | null) {
    const nameParts = customer
      ? deriveCustomerNameParts({
          firstName: customer.first_name,
          lastName: customer.surname,
        })
      : null;

    setCustomerIdentityForm({
      email: customer?.email ?? "",
      firstName: nameParts?.firstName ?? "",
      lastName: nameParts?.lastName ?? "",
      mobile: customer?.mobile ?? "",
    });
  }

  function cancelCustomerIdentityEdit() {
    setEditingCustomerIdentityId(null);
    setCustomerIdentityError("");
    populateCustomerIdentityForm(null);
  }

  async function saveCustomerIdentityDetails() {
    if (!editingCustomerIdentityId || !canManageBookings) {
      return;
    }

    const firstName = customerIdentityForm.firstName.trim();

    if (!firstName) {
      setCustomerIdentityError("First name is required.");
      return;
    }

    setIsCustomerIdentitySaving(true);
    setCustomerIdentityError("");

    try {
      const updatedCustomer = await updateCustomerIdentityDetails(
        editingCustomerIdentityId,
        {
          email: customerIdentityForm.email,
          firstName,
          lastName: customerIdentityForm.lastName,
          mobile: customerIdentityForm.mobile,
        },
      );

      if (!updatedCustomer) {
        throw new Error("Customer details could not be updated.");
      }

      setLiveCustomerRecords((currentRecords) =>
        currentRecords.map((record) =>
          record.id === updatedCustomer.id
            ? {
                ...record,
                email: updatedCustomer.email,
                first_name: updatedCustomer.first_name,
                mobile: updatedCustomer.mobile,
                preferences: updatedCustomer.preferences,
                relationship_notes: updatedCustomer.relationship_notes,
                surname: updatedCustomer.surname,
              }
            : record,
        ),
      );
      setBookings(await getBookings());
      await refreshLiveCustomerRecords();
      setSelectedCustomerKey(`customer:${updatedCustomer.id}`);
      cancelCustomerIdentityEdit();
      showWorkflowToast("✓ Customer details updated");
    } catch (error) {
      setCustomerIdentityError(
        error instanceof Error
          ? error.message
          : "Customer details could not be updated.",
      );
    } finally {
      setIsCustomerIdentitySaving(false);
    }
  }

