                                        item.tone === "error"
                                          ? "border-red-300/35 bg-red-950/25"
                                          : item.tone === "warning"
                                            ? "border-amber-300/35 bg-amber-950/25"
                                            : item.tone === "success"
                                              ? "border-emerald-300/30 bg-emerald-950/20"
                                              : item.tone === "info"
                                                ? "border-sky-300/30 bg-sky-950/20"
                                                : "border-white/10 bg-zinc-950"
