                                            durationMs: entry.durationMs,
                                            failed: entry.failed,
                                            fileName: entry.fileName,
                                            logRows: entry.logRows,
                                            records: entry.records,
                                            restorePointId: entry.restorePointId,
                                            result: entry.result,
                                            skipped: entry.skipped,
                                            startedAt: entry.completedAt,
                                            updated: entry.updated,
                                            user: entry.user,
